// ── Sanitize a string to be safe as a folder/file name component ──
function sanitizeFolderName(name) {
  return String(name || "")
    .trim()
    .replace(/[\\/:*?"<>|]/g, "_")  // replace Windows-unsafe chars
    .replace(/\s+/g, "_")           // spaces → underscores
    .replace(/_+/g, "_")            // collapse consecutive underscores
    .replace(/^_|_$/g, "")         // trim leading/trailing underscores
    .slice(0, 60) || "Client";     // max 60 chars, never empty
}

// ── Get All: when active, intercepts every download at the one choke point
// every existing download path already funnels through, and packs the file
// into a single JSZip instead of triggering individual browser downloads.
// This means every existing Excel/JSON builder function is reused completely
// unmodified — only the final "save to disk" step is redirected.
let __getAllCollector = null;

// Blob URLs are same-origin and can be read straight from the popup. Remote
// portal URLs (the IMS generateDoc / generateOutwardsDoc file links, for
// example) cannot: a popup-origin fetch to return.gst.gov.in has no CORS
// grant, so it rejects with "Failed to fetch". In normal mode the browser's
// downloads API sidesteps CORS entirely, which is why IMS worked outside
// Get All and blew up inside it. Route those through the service worker,
// which holds the host permission.
async function fetchBlobForZip(url) {
  if (typeof url === "string" && /^blob:/i.test(url)) {
    const r = await fetch(url);
    if (!r.ok) throw new Error(`HTTP ${r.status}`);
    return r.blob();
  }
  const msg = await bgFetch(url, { method: "GET", responseType: "arraybuffer" });
  if (!msg || !msg.status) {
    throw new Error((msg && msg.error) || (msg && msg.statusCode ? `HTTP ${msg.statusCode}` : "Download failed"));
  }
  const b64 = msg.responseBase64 || "";
  const binary = atob(b64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
  return new Blob([bytes]);
}

const downloadAs = (url, filename) => {
  const prefs = loadPrefs();
  let finalName = filename;
  if (prefs.useClientFolder) {
    const clientName = sanitizeFolderName(
      session.selectedClientName || session.businessName || ""
    );
    if (clientName) {
      finalName = `NEO-GST/${clientName}/${filename}`;
    }
  }

  if (__getAllCollector) {
    const collector = __getAllCollector;
    // finalName may include "NEO-GST/<client>/" prefix; strip the
    // client-folder prefix inside the zip since the zip itself is
    // already scoped to one GSTIN/FY.
    const zipPath = finalName.replace(/^NEO-GST\//, "");
    return fetchBlobForZip(url).then((blob) => {
      collector.zip.file(zipPath, blob);
      collector.savedFiles.push(zipPath);
      return null;
    });
  }

  const dlPromise = browser.downloads.download({ url, filename: finalName });
  // Notify background to show a notification when this download completes
  dlPromise && dlPromise.then && dlPromise.then((downloadId) => {
    if (typeof downloadId === "number") {
      browser.runtime.sendMessage({
        type: "gc-returns-pro-download-started",
        downloadId,
        filename: finalName.split("/").pop(),
      }).catch(() => {});
    }
  }).catch(() => {});
  return dlPromise;
};
async function downloadBlobAs(blob, filename) {
  const blobUrl = URL.createObjectURL(blob);
  try {
    return await downloadAs(blobUrl, filename);
  } finally {
    setTimeout(() => {
      try {
        URL.revokeObjectURL(blobUrl);
      } catch (err) {
        // ignore revoke issues
      }
    }, 2000);
  }
}

function releaseLargeArray(items) {
  if (!Array.isArray(items)) return;
  for (let i = 0; i < items.length; i++) items[i] = null;
  items.length = 0;
}
const saveBlobUrl = (fileName, url) => downloadAs(url, fileName);
// GSTR-1A is the Rule 59(4A) amendment return: same JSON schema as GSTR-1, so
// it reuses the whole GSTR-1 build pipeline. isGstr1AReturn() exists only where
// the two genuinely differ (the fetch route -- 1A has no live-sections API).
const isGstr1FamilyApiCode = (code) => {
  const upper = String(code || "").toUpperCase();
  return upper === "GSTR1" || upper === "GSTR1A";
};
const isGstr1Return = (cfg) => !!cfg && isGstr1FamilyApiCode(cfg.apiCode);
const isGstr1AReturn = (cfg) => !!cfg && String(cfg.apiCode || "").toUpperCase() === "GSTR1A";
const isGstr2aReturn = (cfg) => cfg && cfg.apiCode === "GSTR2A";
const isGstr2bReturn = (cfg) => cfg && cfg.apiCode === "GSTR2B";
const isGstr3bReturn = (cfg) => cfg && cfg.apiCode === "GSTR3B";
const isStructuredJsonExcelReturn = (cfg) => isGstr1Return(cfg) || isGstr2aReturn(cfg) || isGstr2bReturn(cfg);
const supportsExcelDownloadReturn = (cfg) => isStructuredJsonExcelReturn(cfg) || isGstr3bReturn(cfg);
const isGeneratedStructuredReturn = (cfg) => isGstr1Return(cfg) || isGstr2aReturn(cfg);

