const tax=(d)=>({iamt:num(d.iamt),camt:num(d.camt),samt:num(d.samt),csamt:num(d.csamt)});

function rowsB2B(b2b){const out=[];arr(b2b).forEach(s=>{const ctin=s.ctin||s.gstin||"",rname=s.cfnm||s.cfin||s.nm||"";arr(s.inv).forEach(inv=>{arr(inv.itms).forEach(it=>{const d=itemDet(it),t=tax(d);out.push({ctin,rname,inum:inv.inum||"",idt:inv.idt||"",val:num(inv.val),pos:posLabel(inv.pos),rchrg:inv.rchrg||"",diff:inv.diff_percent!=null?num(inv.diff_percent):"",ityp:invTypeLabel(inv.inv_typ),etin:inv.etin||"",rt:num(d.rt),txval:num(d.txval),...t,src:inv.srctyp||"",irn:inv.irn||"",irndt:inv.irngendate||""});});});});return out;}
