function rowsCDNUR(cdnur){const out=[];arr(cdnur).forEach(nt=>{arr(nt.itms).forEach(it=>{const d=itemDet(it),t=tax(d);out.push({urtyp:nt.typ||"",ntnum:nt.nt_num||"",ntdt:nt.nt_dt||"",ntty:nt.ntty||"",pos:posLabel(nt.pos),ntval:num(nt.val),diff:nt.diff_percent!=null?num(nt.diff_percent):"",rt:num(d.rt),txval:num(d.txval),...t});});});return out;}
function rowsB2CL(b2cl){const out=[];arr(b2cl).forEach(g=>{arr(g.inv).forEach(inv=>{arr(inv.itms).forEach(it=>{const d=itemDet(it),t=tax(d);out.push({inum:inv.inum||"",idt:inv.idt||"",val:num(inv.val),pos:posLabel(g.pos),diff:inv.diff_percent!=null?num(inv.diff_percent):"",rt:num(d.rt),txval:num(d.txval),iamt:t.iamt,csamt:t.csamt,etin:inv.etin||""});});});});return out;}
