function rowsEXP(exp){const out=[];arr(exp).forEach(g=>{arr(g.inv).forEach(inv=>{arr(inv.itms).forEach(it=>{const d=itemDet(it),t=tax(d);const portCode=inv.sbpcode||inv.sbp_code||inv.portcode||inv.port_code||inv.port||g.sbpcode||g.portcode||"";out.push({etyp:expTypeLabel(g.exp_typ),inum:inv.inum||"",idt:inv.idt||"",val:num(inv.val),port:portCode,sbnum:inv.sbnum||inv.sb_num||"",sbdt:inv.sbdt||inv.sb_dt||"",diff:inv.diff_percent!=null?num(inv.diff_percent):"",rt:num(d.rt),txval:num(d.txval),iamt:t.iamt,csamt:t.csamt,src:inv.srctyp||"",irn:inv.irn||"",irndt:inv.irngendate||""});});});});return out;}
