    for(const ref of refs){const decoded=XLSX.utils.decode_cell(ref);let row=Array.from(sheetData.getElementsByTagName('row')).find(x=>Number(x.getAttribute('r'))===decoded.r+1);if(!row){row=doc.createElementNS(ns,'row');row.setAttribute('r',String(decoded.r+1));const after=Array.from(sheetData.getElementsByTagName('row')).find(x=>Number(x.getAttribute('r'))>decoded.r+1);sheetData.insertBefore(row,after||null);}let cell=Array.from(row.getElementsByTagName('c')).find(x=>x.getAttribute('r')===ref);if(!cell){cell=doc.createElementNS(ns,'c');cell.setAttribute('r',ref);const after=Array.from(row.getElementsByTagName('c')).find(x=>XLSX.utils.decode_cell(x.getAttribute('r')).c>decoded.c);row.insertBefore(cell,after||null);}Array.from(cell.childNodes).forEach(n=>cell.removeChild(n));const src=source[ref]||{v:'',t:'s'};if(typeof src.v==='number'){cell.setAttribute('t','n');const v=doc.createElementNS(ns,'v');v.textContent=String(src.v);cell.appendChild(v);}else{cell.setAttribute('t','inlineStr');const is=doc.createElementNS(ns,'is'),t=doc.createElementNS(ns,'t');t.setAttribute('xml:space','preserve');t.textContent=String(src.v==null?'':src.v);is.appendChild(t);cell.appendChild(is);}}
