  const compDoc=await docFor('Refund Computation');setCell(compDoc,'B1',{v:meta.legalName||meta.tradeName||''});setCell(compDoc,'B2',{v:meta.gstin||session.gstin||''});setCell(compDoc,'B3',{v:`Computation of GST Refund for the Period ${refundPeriodLabel(entries)}`});
