function buildCombinedGstr3bWorkbookXml(payloads) {
  const contexts = (payloads || [])
    .map(g3bContext)
    .filter((c) => c.period)
    .sort((a, b) => g3bPeriodSortKey(a.period).localeCompare(g3bPeriodSortKey(b.period)));
  if (!contexts.length) throw new Error("No GSTR-3B periods to export");

  const identity = g3bIdentity(payloads);
  const spec = g3bSpec();
  const combined = buildGstr3bCombinedSummarySheet(contexts, identity, spec);
  const periodSheets = contexts
    .map((ctx, i) => buildGstr3bPeriodSheet(ctx, identity, combined.rowById, 2 + i, spec))
    .join("\n");

  const baseXml = `<?xml version="1.0"?>
<Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet"
 xmlns:o="urn:schemas-microsoft-com:office:office"
 xmlns:x="urn:schemas-microsoft-com:office:excel"
 xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"
 xmlns:html="http://www.w3.org/TR/REC-html40">
 <Styles>${G3B_STYLES}</Styles>
 ${combined.xml}
 ${periodSheets}
</Workbook>`;
  // NEO-GST Reco Stage 3: append one Payment Reco sheet per period (best-effort).
  try {
    const mergeParts = [{ xml: baseXml, idPrefix: "", namePrefix: "" }];
    (payloads || []).forEach((payload, i) => {
      const root = (payload && payload.data) || payload || {};
      const period = String(root.rtnprd || root.ret_period || root.rtn_prd || root.fp || `p${i}`);
      mergeParts.push({ xml: buildReco3bPaymentWorksheetXml(payload, period), idPrefix: `pay${i}_`, namePrefix: `${period} ` });
    });
    return mergeSpreadsheetMlWorkbooks(mergeParts);
  } catch (err) {
    return baseXml;
  }
}

