    groups: MAJOR_HEADS.map((h) => taxBlock(h.label, h.key))
      .concat(MAJOR_HEADS.map((h) => taxBlock(`Balance - ${h.label}`, `${h.key}bal`))),
    trailing: [{ label: "Balance - Total", aliases: ["tot_rng_bal"] }],
