  let imsWs=null,imsRows=[];
  try{const imsEntries=adapted.map(e=>({period:e.period,payload:{data:{imsFile:e.payload.data.imsFile}}}));const imsBlob=await buildG1VsImsConsolidatedBlob(imsEntries);const imsWb=XLSX.read(await imsBlob.arrayBuffer(),{type:"array",cellStyles:true});imsWs=imsWb.Sheets.Reco||null;if(imsWs){const raw=XLSX.utils.sheet_to_json(imsWs,{header:1,defval:""}),hi=raw.findIndex(r=>r.includes("IMS Taxable"));imsRows=hi>=0?raw.slice(hi+1):[];}}catch(_){imsWs=null;}
  const sheetRows=(wb,name)=>XLSX.utils.sheet_to_json(wb.Sheets[name],{header:1,defval:""}).slice(1);
  const g1Data=sheetRows(ewbWb,"GSTR1 Data"),ewbData=sheetRows(ewbWb,"EWB Data"),einvData=sheetRows(einvWb,"E-Invoice Data");
  const periods=[...new Set((entries||[]).map(e=>String(e.period)))];
  const metrics=[["Taxable Value",9,2,8],["IGST",10,3,9],["CGST",11,4,10],["SGST",12,5,11],["Cess",13,6,12]];
  const groups=[
    {table:"3.1(a)",name:"Outward taxable supplies other than zero-rated, nil-rated and exempt",pattern:"3.1(a)*",sections:["B2B","B2BA","B2CL","B2CS","B2CLA","B2CSA","CDNR","CDNRA","CDNUR","CDNURA","AT","ATA","TXPD","TXPDA","ECO","ECOA"],ims:true},
    {table:"3.1(b)",name:"Zero-rated outward supplies",pattern:"3.1(b)*",sections:["EXP","EXPA"]},
    {table:"3.1(c)+(e)",name:"Nil-rated, exempt and non-GST outward supplies",pattern:"3.1(c)+3.1(e)*",sections:[]},
    {table:"Total",name:"Total outward supplies excluding reverse charge inward supplies",pattern:"<>3.1(d)*",sections:null,hsn:true,total:true},
  ];
  const dashboard=[["Return Period","GSTR-3B Table","Particulars","Amount Head","GSTR-3B","GSTR-1","HSN","E-Invoice","E-Way Bill","IMS Outward (B2B)","3B - GSTR-1","GSTR-1 - HSN","GSTR-1 - E-Invoice","GSTR-1 - E-Way Bill","GSTR-1 B2B - IMS"]], formulas=[];
  const sum=(rows,p,c,sections)=>rows.filter(r=>String(r[0])===p&&(!sections||sections.includes(String(r[1])))).reduce((n,r)=>n+(Number(r[c])||0),0);
  const sumFormula=(sheet,col,n,sections)=>sections&&sections.length?sections.map(s=>`SUMIFS('${sheet}'!${col}:${col},'${sheet}'!A:A,$A${n},'${sheet}'!B:B,"${s}")`).join("+"):`SUMIFS('${sheet}'!${col}:${col},'${sheet}'!A:A,$A${n})`;
  periods.forEach(p=>groups.forEach(group=>metrics.forEach(([label,srcCol,g3Col,hsnCol])=>{
    const n=dashboard.length+1,g3=g3Rows.filter(r=>String(r[0])===p&&(group.total?!/^3\.1\(d\)/.test(String(r[1])):String(r[1]).startsWith(group.table))).reduce((a,r)=>a+(Number(r[g3Col])||0),0);
    const g1RecoCol=7+(srcCol-9),g1=group.sections&&group.sections.length?sum(g1Data,p,srcCol,group.sections):g3Rows.filter(r=>String(r[0])===p&&(group.total?!/^3\.1\(d\)/.test(String(r[1])):String(r[1]).startsWith(group.table))).reduce((a,r)=>a+(Number(r[g1RecoCol])||0),0);
    const ewb=group.sections&&group.sections.length?sum(ewbData,p,srcCol,group.sections):group.total?sum(ewbData,p,srcCol):0,einv=group.sections&&group.sections.length?sum(einvData,p,srcCol,group.sections):group.total?sum(einvData,p,srcCol):0,hsn=group.hsn?sum(hsnRows,p,hsnCol):0,ims=group.ims?sum(imsRows,p,9+(srcCol-9)):0,b2b=sum(g1Data,p,srcCol,["B2B","B2BA"]);
    dashboard.push([p,group.table,group.name,label,g3,g1,group.hsn?hsn:"",group.sections&&group.sections.length||group.total?einv:"",group.sections&&group.sections.length||group.total?ewb:"",group.ims?ims:"",g3-g1,group.hsn?g1-hsn:"",group.sections&&group.sections.length||group.total?g1-einv:"",group.sections&&group.sections.length||group.total?g1-ewb:"",group.ims?b2b-ims:""]);
    const sourceCol=XLSX.utils.encode_col(srcCol),g3Letter=XLSX.utils.encode_col(g3Col),g1RecoLetter=XLSX.utils.encode_col(g1RecoCol),hsnLetter=XLSX.utils.encode_col(hsnCol),imsLetter=XLSX.utils.encode_col(9+(srcCol-9));
    formulas.push({cell:`E${n}`,formula:`SUMIFS('3B vs GSTR-1'!${g3Letter}:${g3Letter},'3B vs GSTR-1'!A:A,$A${n},'3B vs GSTR-1'!B:B,"${group.pattern}")`,value:g3},{cell:`K${n}`,formula:`E${n}-F${n}`,value:g3-g1});
    if(group.sections&&group.sections.length)formulas.push({cell:`F${n}`,formula:sumFormula("GSTR1 Data",sourceCol,n,group.sections),value:g1});else formulas.push({cell:`F${n}`,formula:`SUMIFS('3B vs GSTR-1'!${g1RecoLetter}:${g1RecoLetter},'3B vs GSTR-1'!A:A,$A${n},'3B vs GSTR-1'!B:B,"${group.pattern}")`,value:g1});
    if((group.sections&&group.sections.length)||group.total){formulas.push({cell:`H${n}`,formula:sumFormula("E-Invoice Data",sourceCol,n,group.sections),value:einv},{cell:`I${n}`,formula:sumFormula("EWB Data",sourceCol,n,group.sections),value:ewb},{cell:`M${n}`,formula:`F${n}-H${n}`,value:g1-einv},{cell:`N${n}`,formula:`F${n}-I${n}`,value:g1-ewb});}
    if(group.hsn)formulas.push({cell:`G${n}`,formula:sumFormula("HSN Data",hsnLetter,n,null),value:hsn},{cell:`L${n}`,formula:`F${n}-G${n}`,value:g1-hsn});
    if(group.ims)formulas.push({cell:`J${n}`,formula:`SUMIFS('GSTR-1 vs IMS Outward'!${imsLetter}:${imsLetter},'GSTR-1 vs IMS Outward'!A:A,$A${n})`,value:ims},{cell:`O${n}`,formula:`${sumFormula("GSTR1 Data",sourceCol,n,["B2B","B2BA"])}-J${n}`,value:b2b-ims});
  })));
  const dashWs=idsSheetFromAoa(dashboard,[16,14,48,20,...new Array(11).fill(19)],formulas);
  dashWs.A1.s={...dashWs.A1.s,font:{name:"Calibri",sz:11,bold:true,color:{rgb:"FFFFFF"}},fill:{patternType:"solid",fgColor:{rgb:"17365D"}}};
  const wb=XLSX.utils.book_new();wb.Workbook={CalcPr:{calcMode:"auto",fullCalcOnLoad:true,forceFullCalc:true},Sheets:[]};
  const append=(name,ws)=>{let nm=sanitizeWorksheetName(name).slice(0,31),i=2;while(wb.SheetNames.includes(nm))nm=sanitizeWorksheetName(`${name} ${i++}`).slice(0,31);XLSX.utils.book_append_sheet(wb,ws,nm);};
  append("Summary",dashWs);append("3B vs GSTR-1",g3Sheet.ws);
  [[ewbWb,"GSTR1 vs E-Way Bill","GSTR-1 vs EWB"],[ewbWb,"Invoice Reco","EWB Invoice Reco"],[ewbWb,"EWB Data","EWB Data"],[ewbWb,"GSTR1 Data","GSTR1 Data"],[einvWb,"GSTR1 vs E-Invoice","GSTR-1 vs E-Invoice"],[einvWb,"Invoice Reco","E-Invoice Reco"],[einvWb,"E-Invoice Data","E-Invoice Data"]].forEach(([book,from,to])=>{if(book.Sheets[from])append(to,book.Sheets[from]);});
  append("HSN Data",hsnSheet.ws);
  if(imsWs)append("GSTR-1 vs IMS Outward",imsWs);else append("GSTR-1 vs IMS Outward",renderRecoLongSheet("IMS",{title:"GSTR-1 vs IMS Outward",note:"IMS Outward was unavailable for the selected period(s).",headers:["Status"],rows:[["Unavailable"]],numFromCol:1}).ws);
  const statusRows=[["Period","Source","Status / error"]];(entries||[]).forEach(e=>{statusRows.push([e.period,"GSTR-1 / GSTR-3B","Fetched"],[e.period,"E-Way Bill",Object.keys((e.eway&&e.eway.errors)||{}).length?JSON.stringify(e.eway.errors):"Fetched"],[e.period,"E-Invoice",Object.keys((e.einvoice&&e.einvoice.errors)||{}).length?JSON.stringify(e.einvoice.errors):"Fetched"],[e.period,"IMS Outward",e.imsFile?"Fetched":(e.imsError||"Unavailable")]);});append("Source Status",idsSheetFromAoa(statusRows,[16,24,90]));
  return idsApplyNormalWorkbookViews(workbookToBlob(wb));
