async function fetchSummaryPayload(cfg, period) {
  if (!cfg) throw new Error("Summary type not selected");
  if (["EWAY_BILL", "G1_VS_EWB"].includes(cfg.key)) return fetchEwayBillPayload(cfg, period);
  if (["E_INVOICE", "G1_VS_EINV"].includes(cfg.key)) return fetchEinvoicePayload(cfg, period);
  if(cfg.key==="OUTPUT_RECO"){
    const gstr3b=await recoGstr3b(period);
    const gstr1Summary=await recoGstr1Summary(period);
    const gstr1Full=await recoGstr1(period);
    const eway=(await fetchEwayBillPayload(otherConfig.EWAY_BILL,period)).data;
    eway.gstr1=gstr1Full;
    const einvoice=(await fetchEinvoicePayload(otherConfig.E_INVOICE,period)).data;
    einvoice.gstr1=gstr1Full;
    let imsFile=null,imsError="";
    try{imsFile=await fetchImsOutPeriodFile(otherConfig.IMS_OUT,period.value);}catch(err){imsError=err&&err.message?err.message:String(err);}
    return {data:{rtn_prd:period.value,gstr3b,gstr1_summary:gstr1Summary,gstr1_full:gstr1Full,eway,einvoice,imsFile,imsError}};
  }
  if (cfg.key === "G1SUM") {
    return fetchGstr1SummaryPayload(period);
  }
  if (cfg.key === "G2ASUM") {
    return fetchGstr2aJsonPayload(period);
  }
  if (cfg.key === "G2AOTHER") {
    return fetchGstr2aOtherSummaryPayload(period);
  }
  if (cfg.key === "G2BSUM") {
    return makeBlankSummaryPayload(cfg, period);
  }
  // v2.3.2 — these go through the reco cache, not the raw fetchers. When
  // prefetchRecoPayloadsByHost has already warmed the cache, every call below
  // resolves from memory and no subdomain switch happens mid-build.
  if (cfg.key === "G3B_VS_G1SUM") {
    const gstr3b = await recoGstr3b(period);
    const gstr1Summary = await recoGstr1Summary(period);
    const gstr1Full = await recoGstr1(period);
    return {
      data: {
        rtn_prd: period.value,
        gstr3b,
        gstr1_summary: gstr1Summary,
        gstr1_full: gstr1Full,
        books: cfg.key === "RCM_RECO" ? booksRegisterState : null,
      },
    };
  }
  if (cfg.key === "G3B_VS_G2ASUM") {
    const gstr3b = await recoGstr3b(period);
    const gstr2a = await recoGstr2a(period);
    return {
      data: {
        rtn_prd: period.value,
        gstr3b,
        gstr2a,
      },
    };
  }
  if (cfg.key === "G3B_VS_G2BSUM") {
    const gstr3b = await recoGstr3b(period);
    const gstr2b = await recoGstr2b(period);
    const ims = await recoImsInward();
    return { data: { rtn_prd: period.value, gstr3b, gstr2b, ims } };
  }
  if (cfg.key === "G2A_VS_G2BSUM") {
    const gstr2a = await recoGstr2a(period);
    const gstr2b = await recoGstr2b(period);
    return { data: { rtn_prd: period.value, gstr2a, gstr2b } };
  }
  if (cfg.key === "G1_VS_IMSOUT") {
    const gstr1 = await recoGstr1(period);
    let imsFile = null;
    try {
      imsFile = await fetchImsOutPeriodFile(rc("G1") || {}, period.value);
    } catch (err) {
      imsFile = null;
    }
    return { data: { rtn_prd: period.value, gstr1, imsFile } };
  }
  if (cfg.key === "G3B_ECL") {
    const gstr3b = await recoGstr3b(period);
    return { data: { rtn_prd: period.value, gstr3b } };
  }
  if (cfg.key === "CMP_FY") {
    const report = await fetchPortalComparisonReport(period);
    // Pull GSTR-3B for each month of the FY so the ITC sheet's "claimed"
    // column is real. Best-effort per month: unfiled months stay blank.
    const fyStart = gstr1aFyFromPeriod(period.value);
    const itc3bByPeriod = {};
    const codes = cmpFyPeriodCodes(fyStart);
    for (let i = 0; i < codes.length; i += 1) {
      const code = codes[i];
      try {
        // eslint-disable-next-line no-await-in-loop
        const p3b = await recoGstr3b({ value: code });
        const net = cmpGstr3bNetItc(p3b);
        if (net != null) itc3bByPeriod[code] = net;
      } catch (err) { /* month not filed / unavailable */ }
    }
    return { data: { rtn_prd: period.value, fy: report.fy, comparison: report.data, itc3bByPeriod } };
  }
  if (cfg.key === "VENDOR_INTEL") {
    const gstr2a = await recoGstr2a(period);
    const gstr2b = await recoGstr2b(period);
    return { data: { rtn_prd: period.value, gstr2a, gstr2b } };
  }
  if (cfg.key === "RET_STATUS") {
    const result = await fetchBulkReturnStatus(period);
    return { data: { rtn_prd: period.value, fy: result.fy, returns: result.rows } };
  }
  if (cfg.key === "BOOKS_2B") {
    if (!booksRegisterState || !booksRegisterState.rows || !booksRegisterState.rows.length) {
      throw new Error("Upload a Purchase Register (.xlsx / .csv) first \u2014 use the file picker above the period list.");
    }
    const gstr2b = await recoGstr2b(period);
    return { data: { rtn_prd: period.value, gstr2b, books: booksRegisterState } };
  }
  if (["REFUND_EXPWOP", "REFUND_IDS", "REFUND_EXPWT", "G9_PREP", "RCM_RECO", "REFUND_EXCESS_CASH"].includes(cfg.key)) {
    // Everything the refund working paper needs, straight from the portal:
    // GSTR-3B (horizontal sheet + ITC/turnover figures), GSTR-2B (all invoice
    // sections), and GSTR-1 (summary for the turnover reco, full for detail).
    // Each goes through the same warmed reco cache the other recos use, so no
    // extra subdomain bouncing happens.
    const gstr3b = await recoGstr3b(period);
    let gstr2b = null;
    let ims = null;
    if (!["REFUND_EXPWT", "REFUND_EXCESS_CASH"].includes(cfg.key)) {
      try { gstr2b = await recoGstr2b(period); } catch (e) { gstr2b = null; }
      ims = await recoImsInward();
      if (!ims.available) addActivity(`IMS Inward unavailable: ${ims.error}. No invoice was excluded automatically.`, "text-warning");
    }
    let gstr1Summary = null;
    let gstr1Full = null;
    try {
      gstr1Summary = await portalWorkflowWithTimeout(recoGstr1Summary(period), 35000, `GSTR-1 summary ${period.value}`);
    } catch (e) {
      gstr1Summary = null;
      addActivity(`GSTR-1 summary unavailable for ${period.value}: ${e&&e.message?e.message:e}`, "text-warning");
    }
    try {
      gstr1Full = await portalWorkflowWithTimeout(recoGstr1(period), 60000, `GSTR-1 invoice details ${period.value}`);
    } catch (e) {
      gstr1Full = null;
      const consequence=refundRequiresGstr1InvoiceDetails(cfg)
        ? "The GSTR-1 summary will now be checked for a confirmed NIL return before the refund export decides whether to stop."
        : "Continuing with available return data.";
      addActivity(`GSTR-1 invoice details unavailable for ${period.value}: ${e&&e.message?e.message:e}. ${consequence}`, "text-warning");
    }
    const detailSource = getGstr1SectionSourceData(gstr1Full) || {};
    const hasGstr1Detail = !!gstr1Full
      && (gstr1AssembledHasDetail(detailSource) || gstr1AssembledHasDetail(gstr1Full));
    const nilAssessment = refundGstr1SummaryNilAssessment(gstr1Summary);
    if (!hasGstr1Detail && nilAssessment.confirmed) {
      gstr1Full = refundNilGstr1Payload(period, gstr1Summary);
      addActivity(`GSTR-1 ${period.value}: summary confirms NIL (${nilAssessment.reason}); invoice details are not required.`, "text-success");
    } else if (!hasGstr1Detail) {
      addActivity(`GSTR-1 ${period.value}: NIL could not be confirmed because ${nilAssessment.reason}.`, "text-danger");
    }
    if (refundRequiresGstr1InvoiceDetails(cfg)) {
      // For REFUND_EXPWOP/IDS the portal ideally supplies GSTR-1 invoice details
      // so export invoices can be listed.  However if the portal API fails to
      // return them (timeout, filing-in-progress, portal error) we must NOT
      // abort the whole workbook — the user will fill the invoices sheet manually.
      // A NIL return confirmed by the summary is the only case where missing
      // details are unambiguously OK; everything else gets a loud warning.
      const nilConfirmed = !!(gstr1Full && gstr1Full.__nilReturnConfirmed);
      const finalDetailSource = getGstr1SectionSourceData(gstr1Full) || {};
      const hasDetail = nilConfirmed
        || gstr1AssembledHasDetail(finalDetailSource)
        || gstr1AssembledHasDetail(gstr1Full || {});
      if (!hasDetail) {
        const reason = !gstr1Summary
          ? "GSTR-1 summary was also unavailable"
          : `NIL could not be confirmed (${refundGstr1SummaryNilAssessment(gstr1Summary).reason})`;
        addActivity(
          `GSTR-1 ${period.value}: invoice details not available (${reason}). ` +
          "The export invoice list on the refund workbook will be blank — please enter invoice details manually.",
          "text-danger",
        );
        // Proceed: gstr1Full remains null; the workbook builder handles null gracefully.
      }
    }
    if (cfg.key === "REFUND_IDS") {
      const missing=[];
      if (!gstr3b) missing.push("GSTR-3B");
      if (!gstr2b) missing.push("GSTR-2B");
      if (missing.length) throw new Error(`IDS export stopped for ${period.value}: ${missing.join(", ")} not fetched from GST Portal. No workbook was created with old or partial data.`);
    }
    return {
      data: {
        rtn_prd: period.value,
        gstr3b,
        gstr2b,
        ims,
        gstr1_summary: gstr1Summary,
        gstr1_full: gstr1Full,
      },
    };
  }
  return makeBlankSummaryPayload(cfg, period);
}

function flattenSummaryPayloadRows(source, payload, reportPeriod) {
  const rows = [];
  const flatRows = [];
  flattenObjectToRows(payload || {}, "", flatRows);
  flatRows.forEach((row) => {
    rows.push({
      report_period: reportPeriod || "",
      source,
      field: row.field,
      value: row.value,
    });
  });
  if (!rows.length) {
    rows.push({
      report_period: reportPeriod || "",
      source,
      field: "status",
      value: "No data",
    });
  }
  return rows;
}

// ---------------------------------------------------------------------------
// NEO-GST Reco Stage 3 — GSTR-3B vs GSTR-1 (outward liability)
//
// Both sides here are computed values, not live spreadsheet formulas — unlike
// the 3B-vs-2B Reco, this pipeline (buildXlsxBlobFromSheets) only ever writes
// plain values into cells, it has no formula support. The 3B side reuses
// sup_details straight off the payload; the GSTR-1 side reuses the exact same
// sumGstr1SummaryNode/pickGstr1SummaryNode primitives that already power the
// existing "GSTR-1 Summary" sheet, so the numbers here are guaranteed to
// match what that sheet already shows (no re-derivation, no drift).
//
// One genuine tax-technical caveat, flagged rather than hidden: GSTR-1's
// zero-rated supplies split into "with payment of tax" (EXPWP/SEZWP, which
// carry an IGST figure) and "without payment" (EXPWOP/SEZWOP, taxable value
// only, no tax). GSTR-3B's 3.1(b) figure is the portal's own aggregate and
// doesn't cleanly separate the two, so the "Zero-rated" row below compares
// 3.1(b) against EXPWP+SEZWP only (the tax-bearing portion) and calls out
// EXPWOP+SEZWOP separately as a memo so the taxable-value gap is explained
// rather than showing up as an unexplained difference.
// ---------------------------------------------------------------------------
function extractGstr3bOutwardTotals(gstr3bPayload) {
  const root = (gstr3bPayload && gstr3bPayload.data) || gstr3bPayload || {};
  const sd = root.sup_details || {};
  const bucket = (b) => ({
    txval: asNumber(b && b.txval), igst: asNumber(b && b.iamt), cgst: asNumber(b && b.camt),
    sgst: asNumber(b && b.samt), cess: asNumber(b && b.csamt),
  });
  return {
    taxable: bucket(sd.osup_det),
    zeroRated: bucket(sd.osup_zero),
    nilExempt: bucket(sd.osup_nil_exmp),
    nonGst: bucket(sd.osup_nongst),
    rcmInward: bucket(sd.isup_rev),
  };
}

function extractGstr1OutwardTotals(gstr1SummaryPayload) {
  const g1 = (aliases, opts) => sumGstr1SummaryNode(pickGstr1SummaryNode(gstr1SummaryPayload, aliases), opts);
  const g1nodes = (aliases, opts) => sumGstr1SummaryNodes(pickGstr1SummaryNodes(gstr1SummaryPayload, aliases), opts);
  const add4 = (...parts) => parts.reduce((acc, p) => ({
    txval: acc.txval + (p.value || 0), igst: acc.igst + (p.igst || 0), cgst: acc.cgst + (p.cgst || 0),
    sgst: acc.sgst + (p.sgst || 0), cess: acc.cess + (p.cess || 0),
  }), { txval: 0, igst: 0, cgst: 0, sgst: 0, cess: 0 });

  const b2b4a = g1(["B2B_4A", "b2b_regular", "b2breg"]);
  const b2b4b = g1(["B2B_4B", "b2brcm", "b2b_reverse", "b2b_reverse_charge"]);
  const b2cl = g1(["B2CL", "b2cl_large"]);
  const b2cs = g1(["B2CS", "b2c_others"]);
  const sezwop = g1(["B2B_SEZWOP", "sezwop"]);
  const de6c = g1(["B2B_6C", "de", "deemed", "deemed_exports"]);
  const cdnr = g1(["CDNR"]);
  const cdnur = g1(["CDNUR"]);
  const taxable = add4(b2b4a, b2b4b, b2cl, b2cs, sezwop, de6c);
  taxable.txval -= (cdnr.value || 0) + (cdnur.value || 0);
  taxable.igst -= (cdnr.igst || 0) + (cdnur.igst || 0);
  taxable.cgst -= (cdnr.cgst || 0) + (cdnur.cgst || 0);
  taxable.sgst -= (cdnr.sgst || 0) + (cdnur.sgst || 0);
  taxable.cess -= (cdnr.cess || 0) + (cdnur.cess || 0);

  const expwp = g1(["EXP_EXPWP", "expwp", "export_wp", "exports_wp"]);
  const sezwp = g1(["B2B_SEZWP", "sezwp"]);
  const zeroRatedWithTax = add4(expwp, sezwp);
  const expwop = g1(["EXP_EXPWOP", "expwop", "export_wop", "exports_wop"]);
  const sezwopMemo = sezwop; // reused above but shown again as memo context
  const zeroRatedMemoOnly = add4(expwop, sezwopMemo);

  const nilTotal = g1(["NIL"], { valueOnly: true, nilField: "total" });
  const liability = g1(["TTL_LIAB"]);

  return {
    taxable,
    zeroRatedWithTax,
    zeroRatedMemoOnly,
    totalLiability: { txval: liability.value || 0, igst: liability.igst || 0, cgst: liability.cgst || 0, sgst: liability.sgst || 0, cess: liability.cess || 0, seen: !!liability.seen },
    nilExempt: { txval: nilTotal.value || 0, igst: 0, cgst: 0, sgst: 0, cess: 0 },
  };
}

function buildReco3bVs1Rows(gstr3bPayload, gstr1SummaryPayload, reportPeriod) {
  const threeB = extractGstr3bOutwardTotals(gstr3bPayload);
  const oneB = extractGstr1OutwardTotals(gstr1SummaryPayload);
  const rows = [];
  const fmt = (v) => Math.round((v || 0) * 100) / 100; // keep paise precision, display format handles rounding
  const addRow = (head, three, one, note) => {
    rows.push({
      head,
      gstr3b_txval: fmt(three.txval), gstr3b_igst: fmt(three.igst), gstr3b_cgst: fmt(three.cgst), gstr3b_sgst: fmt(three.sgst), gstr3b_cess: fmt(three.cess),
      gstr1_txval: one ? fmt(one.txval) : "", gstr1_igst: one ? fmt(one.igst) : "", gstr1_cgst: one ? fmt(one.cgst) : "", gstr1_sgst: one ? fmt(one.sgst) : "", gstr1_cess: one ? fmt(one.cess) : "",
      diff_txval: one ? fmt(three.txval - one.txval) : "", diff_igst: one ? fmt(three.igst - one.igst) : "",
      diff_cgst: one ? fmt(three.cgst - one.cgst) : "", diff_sgst: one ? fmt(three.sgst - one.sgst) : "", diff_cess: one ? fmt(three.cess - one.cess) : "",
      note: note || "",
    });
  };
  addRow("3.1(a) Taxable outward supplies (other than zero-rated/nil/exempt)", threeB.taxable, oneB.taxable,
    "GSTR-1 side = B2B(4A)+B2B RCM(4B)+B2CL+B2CS+SEZ(without payment)+Deemed Exports(6C), net of CDNR/CDNUR credit-debit notes.");
  addRow("3.1(b) Zero-rated supplies (tax-bearing portion)", threeB.zeroRated, oneB.zeroRatedWithTax,
    "GSTR-1 side = Exports with payment (EXPWP) + SEZ with payment (SEZWP) only \u2014 see memo row below for the without-payment portion.");
  rows.push({
    head: "Memo: Zero-rated without payment of tax (EXPWOP + SEZWOP)", gstr3b_txval: "", gstr3b_igst: "", gstr3b_cgst: "", gstr3b_sgst: "", gstr3b_cess: "",
    gstr1_txval: fmt(oneB.zeroRatedMemoOnly.txval), gstr1_igst: "", gstr1_cgst: "", gstr1_sgst: "", gstr1_cess: "",
    diff_txval: "", diff_igst: "", diff_cgst: "", diff_sgst: "", diff_cess: "",
    note: "No tax on this portion \u2014 taxable value only, shown for context. Not included in the 3.1(b) comparison above.",
  });
  addRow("3.1(c)+3.1(e) Nil rated, exempted and non-GST", { txval: threeB.nilExempt.txval + threeB.nonGst.txval, igst: 0, cgst: 0, sgst: 0, cess: 0 }, oneB.nilExempt,
    "3B figure combines osup_nil_exmp (3.1c) and osup_nongst (3.1e); GSTR-1 side is table 8's combined Nil+Exempt+Non-GST total.");
  addRow("3.1(d) Inward supplies liable to reverse charge", threeB.rcmInward, null,
    "Recipient's own RCM liability \u2014 not present in the supplier's own GSTR-1 at all. 3B-only reference row.");
  return rows;
}

function buildReco3bVs1WorksheetXml(gstr3bPayload, gstr1SummaryPayload, reportPeriod) {
  const rows = buildReco3bVs1Rows(gstr3bPayload, gstr1SummaryPayload, reportPeriod);
  const cell = (value, style, type) => `<Cell ss:StyleID="${style}"><Data ss:Type="${type || "String"}">${escapeXml(value == null ? "" : value)}</Data></Cell>`;
  const numCell = (value) => (value === "" || value == null ? cell("", G3B_NUM_NA) : cell(value, G3B_NUM, "Number"));
  const out = [];
  out.push(`<Row>${cell(`Reco & Summ \u2014 GSTR-3B vs GSTR-1 (Period: ${reportPeriod || "-"})`, "G3BTitle")}</Row>`);
  out.push(`<Row><Cell ss:StyleID="G3BBlank"/></Row>`);
  out.push(`<Row>${cell("Head", "G3BHeader")}${cell("GSTR-3B Taxable", "G3BHeader")}${cell("GSTR-3B IGST", "G3BHeader")}${cell("GSTR-3B CGST", "G3BHeader")}${cell("GSTR-3B SGST", "G3BHeader")}${cell("GSTR-3B Cess", "G3BHeader")}${cell("GSTR-1 Taxable", "G3BHeader")}${cell("GSTR-1 IGST", "G3BHeader")}${cell("GSTR-1 CGST", "G3BHeader")}${cell("GSTR-1 SGST", "G3BHeader")}${cell("GSTR-1 Cess", "G3BHeader")}${cell("Diff Taxable", "G3BHeader")}${cell("Diff IGST", "G3BHeader")}${cell("Diff CGST", "G3BHeader")}${cell("Diff SGST", "G3BHeader")}${cell("Diff Cess", "G3BHeader")}${cell("Note", "G3BHeader")}</Row>`);
  rows.forEach((r) => {
    out.push(`<Row>${cell(r.head, "G3BItem")}${numCell(r.gstr3b_txval)}${numCell(r.gstr3b_igst)}${numCell(r.gstr3b_cgst)}${numCell(r.gstr3b_sgst)}${numCell(r.gstr3b_cess)}${numCell(r.gstr1_txval)}${numCell(r.gstr1_igst)}${numCell(r.gstr1_cgst)}${numCell(r.gstr1_sgst)}${numCell(r.gstr1_cess)}${numCell(r.diff_txval)}${numCell(r.diff_igst)}${numCell(r.diff_cgst)}${numCell(r.diff_sgst)}${numCell(r.diff_cess)}${cell(r.note, "G3BNote")}</Row>`);
  });
  const colXml = ['<Column ss:AutoFitWidth="0" ss:Width="260"/>']
    .concat(Array.from({ length: 15 }, () => '<Column ss:AutoFitWidth="0" ss:Width="95"/>'))
    .concat(['<Column ss:AutoFitWidth="0" ss:Width="260"/>'])
    .join("");
  return `<?xml version="1.0"?>
<Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet"
 xmlns:o="urn:schemas-microsoft-com:office:office"
 xmlns:x="urn:schemas-microsoft-com:office:excel"
 xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"
 xmlns:html="http://www.w3.org/TR/REC-html40">
 <Styles>${G3B_STYLES}</Styles>
 <Worksheet ss:Name="Reco"><Table>${colXml}${out.join("")}</Table></Worksheet>
</Workbook>`;
}

// ---------------------------------------------------------------------------
// NEO-GST Reco Stage 3 — GSTR-3B vs GSTR-2A (aggregate; the existing "3B vs
// GSTR-2A" chip previously fetched a blank placeholder for the 2A side and
// never actually compared anything — fixed here to pull real 2A data).
//
// Unlike 2B, GSTR-2A carries no ITC-eligibility classification (no RCM/ISD/
// "all other" split, no available-vs-not-available flag) — it's simply every
// invoice reported against this GSTIN, full stop. So this is one aggregate
// row (total tax across B2B + CDNR + ISD + Import of goods), not a per-head
// breakdown like the 2B version. Treat it as a coverage check ("does 2A even
// contain what 3B claimed"), not a like-for-like Table 4 tie-out.
// ---------------------------------------------------------------------------
function extractGstr2aAllInvoiceTotal(payload) {
  const roots = [];
  const pushRoot = (o) => { if (o && typeof o === "object") roots.push(o); };
  pushRoot(payload); pushRoot(payload && payload.data);
  pushRoot(payload && payload.__portalResponse); pushRoot(payload && payload.__portalResponse && payload.__portalResponse.data);
  ((payload && payload.__linkedPayloads) || []).forEach((lp) => { pushRoot(lp); pushRoot(lp && lp.data); });
  let taxable = 0, igst = 0, cgst = 0, sgst = 0, cess = 0;
  const addAmt = (d) => {
    taxable += asNumber(d && d.txval); igst += asNumber(d && d.iamt);
    cgst += asNumber(d && d.camt); sgst += asNumber(d && d.samt); cess += asNumber(d && d.csamt);
  };
  const seen = new Set();
  roots.forEach((root) => {
    if (!root || seen.has(root)) return;
    seen.add(root);
    (Array.isArray(root.b2b) ? root.b2b : []).forEach((s) => (Array.isArray(s.inv) ? s.inv : []).forEach((inv) => {
      const items = Array.isArray(inv.itms) && inv.itms.length ? inv.itms : [null];
      items.forEach((it) => addAmt((it && (it.itm_det || it)) || {}));
    }));
    (Array.isArray(root.cdnr) ? root.cdnr : []).forEach((s) => (Array.isArray(s.nt) ? s.nt : []).forEach((nt) => {
      const items = Array.isArray(nt.itms) && nt.itms.length ? nt.itms : [null];
      items.forEach((it) => addAmt((it && (it.itm_det || it)) || {}));
    }));
    (Array.isArray(root.isd) ? root.isd : []).forEach((isd) => {
      const docs = Array.isArray(isd.itms) ? isd.itms : (Array.isArray(isd.doclist) ? isd.doclist : []);
      docs.forEach((d) => addAmt(d));
    });
    (Array.isArray(root.impg) ? root.impg : []).forEach((item) => { taxable += asNumber(item.txval); igst += asNumber(item.igst); cess += asNumber(item.cess); });
    (Array.isArray(root.impgsez) ? root.impgsez : []).forEach((item) => { taxable += asNumber(item.txval); igst += asNumber(item.igst); cess += asNumber(item.cess); });
  });
  return { taxable, igst, cgst, sgst, cess };
}

function buildReco3bVs2aSheets(gstr3bPayload, gstr2aPayload, period) {
  return buildReco3bVs2aMultiPeriodSheet([
    { period: period || "", gstr3b: gstr3bPayload, gstr2a: gstr2aPayload },
  ]);
}

// v2.3.2 — one Reco sheet covering every period, one row per month plus a
// grand-total row, all period-labelled. This replaces the old "Get All"
// behaviour where twelve unlabelled single-period Reco sheets were stacked
// into an indistinguishable block and paired with a 29k-row raw JSON dump.
function buildReco3bVs2aMultiPeriodSheet(entries) {
  const fmt = (v) => Math.round((v || 0) * 100) / 100;
  const rows = [];
  const totals = { b_tx: 0, b_i: 0, b_c: 0, b_s: 0, b_ce: 0, a_tx: 0, a_i: 0, a_c: 0, a_s: 0, a_ce: 0 };
  (entries || []).forEach(({ period, gstr3b, gstr2a }) => {
    let net3b = { taxable: 0, igst: 0, cgst: 0, sgst: 0, cess: 0 };
    let twoA = { taxable: 0, igst: 0, cgst: 0, sgst: 0, cess: 0 };
    try { net3b = extractGstr3bItcBlockTotals(gstr3b).net4c || net3b; } catch (e) {}
    try { twoA = extractGstr2aAllInvoiceTotal(gstr2a) || twoA; } catch (e) {}
    totals.b_tx += net3b.taxable || 0; totals.b_i += net3b.igst || 0; totals.b_c += net3b.cgst || 0; totals.b_s += net3b.sgst || 0; totals.b_ce += net3b.cess || 0;
    totals.a_tx += twoA.taxable || 0; totals.a_i += twoA.igst || 0; totals.a_c += twoA.cgst || 0; totals.a_s += twoA.sgst || 0; totals.a_ce += twoA.cess || 0;
    rows.push({
      period: period || "",
      gstr3b_igst: fmt(net3b.igst), gstr3b_cgst: fmt(net3b.cgst), gstr3b_sgst: fmt(net3b.sgst), gstr3b_cess: fmt(net3b.cess),
      gstr2a_igst: fmt(twoA.igst), gstr2a_cgst: fmt(twoA.cgst), gstr2a_sgst: fmt(twoA.sgst), gstr2a_cess: fmt(twoA.cess),
      diff_igst: fmt((net3b.igst || 0) - (twoA.igst || 0)), diff_cgst: fmt((net3b.cgst || 0) - (twoA.cgst || 0)),
      diff_sgst: fmt((net3b.sgst || 0) - (twoA.sgst || 0)), diff_cess: fmt((net3b.cess || 0) - (twoA.cess || 0)),
    });
  });
  if (rows.length > 1) {
    rows.push({
      period: "TOTAL",
      gstr3b_igst: fmt(totals.b_i), gstr3b_cgst: fmt(totals.b_c), gstr3b_sgst: fmt(totals.b_s), gstr3b_cess: fmt(totals.b_ce),
      gstr2a_igst: fmt(totals.a_i), gstr2a_cgst: fmt(totals.a_c), gstr2a_sgst: fmt(totals.a_s), gstr2a_cess: fmt(totals.a_ce),
      diff_igst: fmt(totals.b_i - totals.a_i), diff_cgst: fmt(totals.b_c - totals.a_c),
      diff_sgst: fmt(totals.b_s - totals.a_s), diff_cess: fmt(totals.b_ce - totals.a_ce),
    });
  }
  const titlePeriod = (entries && entries.length === 1) ? ` (Period: ${entries[0].period || "-"})` : ` (${(entries || []).length} periods)`;
  return [{
    name: "Reco",
    rows,
    columns: ["period", "gstr3b_igst", "gstr3b_cgst", "gstr3b_sgst", "gstr3b_cess", "gstr2a_igst", "gstr2a_cgst", "gstr2a_sgst", "gstr2a_cess", "diff_igst", "diff_cgst", "diff_sgst", "diff_cess"],
    options: {
      schemaReturnType: "GENERIC",
      skipDefaultHeader: true,
      customHeaderRows: [
        [`Reco & Summ \u2014 GSTR-3B (ITC 4(C) net) vs GSTR-2A (all invoices)${titlePeriod}`],
        ["Period", "GSTR-3B ITC", "", "", "", "GSTR-2A ITC", "", "", "", "Difference (3B \u2212 2A)", "", "", ""],
        ["", "IGST", "CGST", "SGST", "Cess", "IGST", "CGST", "SGST", "Cess", "IGST", "CGST", "SGST", "Cess"],
        ["2A is a coverage check, not a per-head tie-out: it carries no RCM/ISD eligibility split. A large gap usually means supplier filings missing in 2A, not an error on your side. Taxable value is omitted \u2014 3B Table 4 has none."],
      ],
      merges: ["A1:M1", "B2:E2", "F2:I2", "J2:M2", "A2:A3", "A4:M4"],
    },
  }];
}

function buildSummaryWorkbookSheets(cfg, payload, period) {
  const reportPeriod = period && period.value ? period.value : "";
  if (cfg.key === "EWAY_BILL") {
    const sections = payload && payload.data && payload.data.sections || {};
    return Object.entries(sections).map(([section,response])=>({
      name: `EWB ${section}`.slice(0,31),
      rows: flattenSummaryPayloadRows(`E-Way Bill ${section}`,response,reportPeriod),
      columns: ["report_period","source","field","value"],
      options: {schemaReturnType:"GENERIC"}
    }));
  }
  if (cfg.key === "G3B_VS_G1SUM") {
    const data = payload && payload.data ? payload.data : {};
    const gstr3bRows = buildGstr3bSummarySheetRows(data.gstr3b, false);
    const gstr1Rows = buildGstr1SummarySheetRows(data.gstr1_summary, false, reportPeriod);
    const recoRows = buildReco3bVs1Rows(data.gstr3b, data.gstr1_summary, reportPeriod);
    const sheets = [
      {
        name: "Reco",
        rows: recoRows,
        columns: ["head", "gstr3b_txval", "gstr3b_igst", "gstr3b_cgst", "gstr3b_sgst", "gstr3b_cess", "gstr1_txval", "gstr1_igst", "gstr1_cgst", "gstr1_sgst", "gstr1_cess", "diff_txval", "diff_igst", "diff_cgst", "diff_sgst", "diff_cess", "note"],
        options: {
          schemaReturnType: "GENERIC",
          skipDefaultHeader: true,
          customHeaderRows: [
            [`Reco & Summ \u2014 GSTR-3B vs GSTR-1 (Period: ${reportPeriod || "-"})`],
            ["Head", "GSTR-3B", "", "", "", "", "GSTR-1", "", "", "", "", "Difference (3B \u2212 1)", "", "", "", "", "Note"],
            ["", "Taxable Value", "IGST", "CGST", "SGST", "Cess", "Taxable Value", "IGST", "CGST", "SGST", "Cess", "Taxable Value", "IGST", "CGST", "SGST", "Cess", ""],
          ],
          merges: ["A1:Q1", "B2:F2", "G2:K2", "L2:P2", "A2:A3", "Q2:Q3"],
        },
      },
      {
        name: "GSTR-3B",
        rows: gstr3bRows,
        columns: getSpreadsheetColumns(gstr3bRows, ["Section", "Particulars", "Taxable Value", "IGST", "CGST", "SGST", "CESS"]),
        options: { schemaReturnType: "GENERIC" },
      },
      {
        name: "GSTR-1 Summary",
        rows: gstr1Rows,
        columns: getSpreadsheetColumns(gstr1Rows, ["row_type", "Description", "No. of records", "Document Type", "Value", "Integrated Tax", "Central Tax", "State/UT Tax", "Cess"]),
        options: { schemaReturnType: "GENERIC" },
      },
    ];
    // Full GSTR-1 data (all sections) so the workbook carries both returns for reco.
    if (data.gstr1_full) {
      try {
        const g1State = createGstr1WorkbookState({ maxWorksheetRows: XLSX_MAX_WORKSHEET_DATA_ROWS, lightweightMode: true });
        appendGstr1PayloadToWorkbookState(g1State, data.gstr1_full);
        collectGstr1WorkbookSheets(g1State).forEach((s) => {
          sheets.push({
            name: ("G1 " + s.name).slice(0, 31),
            rows: s.rows || [],
            columns: s.columns || getSpreadsheetColumns(s.rows || []),
            options: s.options || { schemaReturnType: "GSTR1" },
          });
        });
      } catch (e) {}
    }
    return sheets;
  }
  if (cfg.key === "G2ASUM") {
    return buildGstr2aSummaryWorkbookSheetsFromEntries([{ period, payload }]);
  }
  if (cfg.key === "G2AOTHER") {
    const metaRows = buildGstr2aOtherMetaRows(payload, false);
    return [
      {
        name: "Summary",
        rows: metaRows,
        columns: ["field", "value"],
        options: { schemaReturnType: "GENERIC" },
      },
    ].concat(buildGstr2aOtherSectionRows(payload, false));
  }
  if (cfg.key === "G3B_VS_G2ASUM") {
    const data = payload && payload.data ? payload.data : {};
    let recoSheets = [];
    try {
      recoSheets = buildReco3bVs2aSheets(data.gstr3b, data.gstr2a, reportPeriod);
    } catch (err) {
      recoSheets = [];
    }
    const sheets = recoSheets.slice();
    // Raw JSON dumps helped nobody. Carry the actual GSTR-3B summary and the
    // GSTR-2A sections as readable sheets so the reco can be traced back to
    // source figures.
    try {
      const gstr3bRows = buildGstr3bSummarySheetRows(data.gstr3b, false);
      sheets.push({
        name: "GSTR-3B",
        rows: gstr3bRows,
        columns: getSpreadsheetColumns(gstr3bRows, ["Section", "Particulars", "Taxable Value", "IGST", "CGST", "SGST", "CESS"]),
        options: { schemaReturnType: "GENERIC" },
      });
    } catch (e) {}
    try {
      buildGstr2aSectionWorkbookRows(data.gstr2a, false).forEach((section) => {
        const rows = section.rows || [];
        sheets.push({
          name: ("2A " + section.name).slice(0, 31),
          rows,
          columns: getSpreadsheetColumns(rows, ["row_no"]),
          options: section.options || { schemaReturnType: "GSTR2A" },
        });
      });
    } catch (e) {}
    return sheets;
  }
  const sourceName = cfg.display || cfg.key;
  const rows = flattenSummaryPayloadRows(sourceName, payload, reportPeriod);
  return [{
    name: sourceName,
    rows,
    columns: ["report_period", "source", "field", "value"],
    options: { schemaReturnType: "GENERIC" },
  }];
}

function buildCombinedSummaryWorkbookSheets(cfg, entries) {
  if (cfg && cfg.key === "G3B_VS_G1SUM") {
    const gstr3bRows = [];
    const gstr1Rows = [];
    (entries || []).forEach((entry) => {
      const data = entry && entry.payload && entry.payload.data ? entry.payload.data : {};
      buildGstr3bSummarySheetRows(data.gstr3b, true).forEach((row) => gstr3bRows.push(row));
      buildGstr1SummarySheetRows(data.gstr1_summary, true, entry && entry.period ? entry.period.value : "").forEach((row) => gstr1Rows.push(row));
    });
    return [
      {
        name: "GSTR-3B",
        rows: gstr3bRows,
        columns: getSpreadsheetColumns(gstr3bRows, ["report_period", "Section", "Particulars", "Taxable Value", "IGST", "CGST", "SGST", "CESS"]),
        options: { schemaReturnType: "GENERIC" },
      },
      {
        name: "GSTR-1 Summary",
        rows: gstr1Rows,
        columns: getSpreadsheetColumns(gstr1Rows, ["report_period", "row_type", "Description", "No. of records", "Document Type", "Value", "Integrated Tax", "Central Tax", "State/UT Tax", "Cess"]),
        options: { schemaReturnType: "GENERIC" },
      },
    ];
  }
  if (cfg && cfg.key === "G2ASUM") {
    return buildGstr2aSummaryWorkbookSheetsFromEntries(entries);
  }
  if (cfg && cfg.key === "G2AOTHER") {
    const sheetsByName = new Map();
    const pushRows = (name, rows, columns, options) => {
      if (!sheetsByName.has(name)) {
        sheetsByName.set(name, { name, rows: [], preferredColumns: columns || [], options: options || { schemaReturnType: "GENERIC" } });
      }
      const target = sheetsByName.get(name);
      (rows || []).forEach((row) => target.rows.push(row));
    };
    (entries || []).forEach((entry) => {
      pushRows("Summary", buildGstr2aOtherMetaRows(entry.payload, true), ["report_period", "field", "value"], { schemaReturnType: "GENERIC" });
      buildGstr2aOtherSectionRows(entry.payload, true).forEach((sheet) => {
        pushRows(sheet.name, sheet.rows || [], sheet.columns || ["report_period", "row_no"], sheet.options || { schemaReturnType: "GSTR2A" });
      });
    });
    return Array.from(sheetsByName.values()).map((sheet) => ({
      name: sheet.name,
      rows: sheet.rows,
      columns: getSpreadsheetColumns(sheet.rows, sheet.preferredColumns),
      options: sheet.options,
    }));
  }
  const sheetsByName = new Map();
  (entries || []).forEach((entry) => {
    const sheets = buildSummaryWorkbookSheets(cfg, entry.payload, entry.period);
    (sheets || []).forEach((sheet) => {
      if (!sheetsByName.has(sheet.name)) {
        sheetsByName.set(sheet.name, {
          name: sheet.name,
          rows: [],
          preferredColumns: sheet.columns || [],
          options: sheet.options || { schemaReturnType: "GENERIC" },
        });
      }
      const target = sheetsByName.get(sheet.name);
      (sheet.rows || []).forEach((row) => target.rows.push(row));
    });
  });
  return Array.from(sheetsByName.values()).map((sheet) => ({
    name: sheet.name,
    rows: sheet.rows,
    columns: getSpreadsheetColumns(sheet.rows, sheet.preferredColumns),
    options: sheet.options,
  }));
}

async function downloadSummaryPeriod(period, mode) {
  const cfg = session.return || getCurrentTypeConfig();
  if (cfg && !session.return) session.return = cfg;
  // Every click is a fresh statutory-data snapshot. Do not reuse payloads from
  // an earlier download, even where GSTIN and period are unchanged.
  clearRecoCache();

  // ── COMPUTED MODULE PATH ────────────────────────────────────────────────
  // If this module declares needs/compute/render (a self-contained "computed"
  // module), run the generic engine instead of the hardcoded reco branches.
  // The whole recipe lives in the module file, so this needs no per-module code.
  const computedDesc = (typeof __REG.computedByKey === "function") && cfg && __REG.computedByKey(cfg.key);
  if (computedDesc && typeof self !== "undefined" && self.NEOGST_COMPUTED && self.NEOGST_COMPUTED.isComputed(computedDesc)) {
    const btnC = getElement(`btn-summary-${mode === "excel" ? "excel" : "json"}-${period.value}`);
    if (btnC) { btnC.disabled = true; btnC.textContent = mode === "excel" ? "Preparing..." : "Downloading..."; }
    try {
      const sources = await fetchNeedsSources(computedDesc.needs, period);
      const gstinForFile = resolveSummaryGstin() || session.gstin || "GSTIN";
      if (mode === "json") {
        await downloadBlobAs(new Blob([JSON.stringify(sources, null, 2)], { type: "application/json" }),
          `${makeJsonFileName(cfg.fileNameCode || cfg.key, gstinForFile, period.value)}.json`);
      } else {
        const out = self.NEOGST_COMPUTED.build({
          descriptor: computedDesc, sources,
          meta: { gstin: gstinForFile, periodLabel: period.label || period.value },
          XLSX,
        });
        await downloadBlobAs(out.blob, out.fileName);
      }
      showStatus("Downloaded");
      return;
    } catch (e) {
      showStatus((e && e.message) ? e.message : "Failed", true);
      return;
    } finally {
      if (btnC) { btnC.disabled = false; btnC.textContent = mode === "excel" ? "Excel" : "JSON"; }
    }
  }
  // ── end computed module path ────────────────────────────────────────────

  const btn = getElement(`btn-summary-${mode === "excel" ? "excel" : "json"}-${period.value}`);
  const info = getElement(`info-${period.value}`);
  if (btn) {
    btn.disabled = true;
    btn.textContent = mode === "excel" ? "Preparing..." : "Downloading...";
  }
  try {
    const payload = await fetchSummaryPayload(cfg, period);
    const gstinForFile = resolveSummaryGstin() || session.gstin || "GSTIN";
    const fileBase = makeJsonFileName(cfg.fileNameCode || cfg.key, gstinForFile, period.value);
    if (mode === "excel") {
      if (cfg.key === "G3B_VS_G1SUM") {
        const data = payload && payload.data ? payload.data : {};
        // Combine the full GSTR-3B and full GSTR-1 into a single workbook so the
        // user gets one file instead of downloading and merging two separately.
        // NEO-GST Reco Stage 3: a real Reco worksheet goes in first, ahead of
        // the two raw returns, built from the same payloads already fetched.
        let recoXml = null;
        try {
          recoXml = buildReco3bVs1WorksheetXml(data.gstr3b, data.gstr1_summary, period && period.value);
        } catch (err) {
          recoXml = null;
        }
        const mergeParts = [];
        if (recoXml) mergeParts.push({ xml: recoXml, idPrefix: "reco_", namePrefix: "" });
        mergeParts.push({ xml: buildGstr3bWorkbookXml(data.gstr3b), idPrefix: "g3b_", namePrefix: "" });
        mergeParts.push({
          xml: buildGstr1WorkbookXml(data.gstr1_full || data.gstr1_summary),
          idPrefix: "g1_",
          namePrefix: "G1 ",
        });
        const combinedXml = mergeSpreadsheetMlWorkbooks(mergeParts);
        const combinedBlob = await buildXlsxBlobFromWorkbookXml(combinedXml, { compression: true });
        await downloadBlobAs(
          combinedBlob,
          `${makeJsonFileName("R3B_R1_COMBINED", gstinForFile, period.value)}.xlsx`,
        );
      } else if (cfg.key === "G3B_VS_G2BSUM") {
        const data = payload && payload.data ? payload.data : {};
        const blob = await buildReco3bVs2bV2Blob([{period:period.value,gstr2b:data.gstr2b,gstr3b:data.gstr3b,ims:data.ims}]);
        await downloadBlobAs(blob, `${makeJsonFileName("R3B_R2B_RECO", gstinForFile, period.value)}.xlsx`);
      } else if (cfg.key === "G2A_VS_G2BSUM") {
        const data = payload && payload.data ? payload.data : {};
        const blob = await buildGstr2aWorkbookXlsxBlob(data.gstr2a, data.gstr2b);
        await downloadBlobAs(blob, `${makeJsonFileName("R2A_R2B_RECO", gstinForFile, period.value)}.xlsx`);
      } else if (cfg.key === "G1_VS_IMSOUT") {
        const data = payload && payload.data ? payload.data : {};
        let blob;
        try {
          if (data.imsFile && data.imsFile.kind === "xlsx") {
            const imsWorkbook = readImsWorkbook(data.imsFile.bytes);
            const combined = combineImsWorkbooks([{ period: period.value, workbook: imsWorkbook }]);
            const { map: imsMap, sheetName: imsSheetName } = extractImsOutwardInvoiceTotals(combined);
            const g1Map = await extractGstr1B2BInvoiceTotalsForPeriods([period.value]);
            const recoWs = buildReco1VsImsSheet(g1Map, imsMap, imsSheetName);
            combined.SheetNames.splice(0, 0, "Reco");
            combined.Sheets.Reco = recoWs;
            blob = workbookToBlob(combined);
          } else {
            // No IMS Outward file for this period (not yet available on the
            // portal, or came back as JSON) — still give GSTR-1 + a note.
            const g1Map = await extractGstr1B2BInvoiceTotalsForPeriods([period.value]);
            const recoWs = buildReco1VsImsSheet(g1Map, new Map(), null);
            blob = workbookToBlob({ SheetNames: ["Reco"], Sheets: { Reco: recoWs } });
          }
        } catch (err) {
          throw new Error(`Could not build GSTR-1 vs IMS Outward reco: ${err && err.message ? err.message : err}`);
        }
        await downloadBlobAs(blob, `${makeJsonFileName("R1_IMSOUT_RECO", gstinForFile, period.value)}.xlsx`);
      } else if (cfg.key === "G3B_ECL") {
        const data = payload && payload.data ? payload.data : {};
        const g3bXml = buildGstr3bWorkbookXml(data.gstr3b);
        let blob = await buildXlsxBlobFromWorkbookXml(g3bXml, { compression: true });
        // v2.3 — bolt on the cash-vs-challan cross-check. Best-effort: if the
        // challan API is unreachable the original workbook is downloaded as-is.
        try {
          const sheet = await buildChallanVsCashSheet(data.gstr3b, period);
          const wb = await readGstr3bWorkbookForMerge(blob, g3bXml);
          wb.SheetNames.splice(0, 0, sheet.name);
          wb.Sheets[sheet.name] = sheet.ws;
          if (wb.Workbook && Array.isArray(wb.Workbook.Sheets)) wb.Workbook.Sheets.unshift({ Hidden: 0 });
          const buf = XLSX.write(wb, { bookType: "xlsx", type: "array", cellStyles: true });
          blob = new Blob([buf], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" });
        } catch (err) { /* keep the plain 3B workbook */ }
        await downloadBlobAs(blob, `${makeJsonFileName("R3B_ECL_RECO", gstinForFile, period.value)}.xlsx`);
      } else if (cfg.key === "CMP_FY") {
        const data = payload && payload.data ? payload.data : {};
        const blob = buildComparisonReportBlob(
          { fy: data.fy, data: data.comparison, itc3bByPeriod: data.itc3bByPeriod },
          gstinForFile,
        );
        await downloadBlobAs(blob, `${makeJsonFileName("FY_CMP_RECO", gstinForFile, String(data.fy || period.value).replace("-", "_"))}.xlsx`);
      } else if (cfg.key === "VENDOR_INTEL") {
        const data = payload && payload.data ? payload.data : {};
        const docs2a = extractRecoDocTotals(data.gstr2a);
        const docs2b = extractRecoDocTotals(data.gstr2b);
        const wb = XLSX.utils.book_new();
        const vi = buildVendorIntelSheet(docs2a, docs2b, period.value);
        XLSX.utils.book_append_sheet(wb, vi.ws, vi.name);
        const mi = buildMissingIn2bSheet(docs2a, docs2b);
        XLSX.utils.book_append_sheet(wb, mi.ws, mi.name);
        await downloadBlobAs(workbookToBlob(wb), `${makeJsonFileName("VENDOR_INTEL", gstinForFile, period.value)}.xlsx`);
      } else if (cfg.key === "RET_STATUS") {
        const data = payload && payload.data ? payload.data : {};
        const blob = buildReturnStatusBlob({ fy: data.fy, rows: data.returns }, gstinForFile);
        await downloadBlobAs(blob, `${makeJsonFileName("RET_STATUS", gstinForFile, String(data.fy || period.value).replace("-", "_"))}.xlsx`);
      } else if (cfg.key === "BOOKS_2B") {
        const data = payload && payload.data ? payload.data : {};
        const docs2b = extractRecoDocTotals(data.gstr2b);
        const results = reconcileBooksVs2b(data.books.rows, docs2b);
        const blob = buildBooksVs2bBlob(data.books, results, period.value, gstinForFile);
        await downloadBlobAs(blob, `${makeJsonFileName("BOOKS_2B_RECO", gstinForFile, period.value)}.xlsx`);
      } else if(cfg.key==="OUTPUT_RECO"){
        const data=payload&&payload.data?payload.data:{};
        const blob=await buildOutputReconciliationsBlob([{period:period.value,...data}]);
        await downloadBlobAs(blob,`${makeJsonFileName("OUTPUT_RECO",gstinForFile,period.value)}.xlsx`);
      } else {
        const blob = ["E_INVOICE", "G1_VS_EINV"].includes(cfg.key) ? await buildEinvoiceWorkbookBlob([{period,payload}],cfg.key==="G1_VS_EINV")
          : ["EWAY_BILL", "G1_VS_EWB"].includes(cfg.key) ? await buildEwayWorkbookBlob([{period, payload}], cfg.key === "G1_VS_EWB") : cfg.key === "G1SUM"
          ? await buildXlsxBlobFromWorkbookXml(buildGstr1SummaryWorkbookXml(payload))
          : await buildXlsxBlobFromSheets(buildSummaryWorkbookSheets(cfg, payload, period), { compression: true });
        await downloadBlobAs(blob, `${fileBase}.xlsx`);
      }
    } else {
      await downloadBlobAs(
        new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" }),
        `${fileBase}.json`,
      );
    }
    if (info) info.innerHTML = pill("Downloaded", "success");
    if (btn) btn.textContent = mode === "excel" ? "Excel" : "JSON";
  } catch (err) {
    if (info) info.innerHTML = pill(err && err.message ? err.message : "Failed", "danger");
    if (btn) btn.textContent = "Failed";
  } finally {
    if (btn) btn.disabled = false;
  }
}

function complianceInstructionRows(kind) {
  const common = [
    { section:"Control", requirement:"Portal-derived values must be reconciled to books and filing evidence before use.", status:"Review required" },
    { section:"Control", requirement:"Blank values are not zero and must not be treated as confirmed.", status:"Review required" },
  ];
  const byKind = {
    REFUND_IDS: [
      { section:"Formula", requirement:"Current Rule 89(5): (inverted turnover x Net ITC / adjusted turnover) - tax payable x (Net ITC / ITC on inputs and input services).", status:"Formula sheet" },
      { section:"Classification", requirement:"Mark eligible inverted outward supplies and classify inward ITC as inputs/input services/capital goods/ineligible.", status:"Manual evidence required" },
      { section:"Documents", requirement:"Statement 1, Statement 1A, covering letter, declarations/undertakings and ledger evidence.", status:"Checklist" },
    ],
    REFUND_EXCESS_CASH: [
      { section:"Formula", requirement:"Claim by head is limited to the lower of amount requested and verified refundable cash-ledger balance.", status:"Manual request input" },
      { section:"Control", requirement:"Check outstanding liabilities, utilisation and transfers before filing.", status:"Portal verification" },
    ],
    REFUND_EXPWT: [
      { section:"Goods", requirement:"Reconcile GSTR-1 Table 6A invoice, shipping bill, port, EGM and Customs refund status under Rule 96.", status:"Customs evidence required" },
      { section:"Services", requirement:"Prepare Statement 2 and invoice-to-FIRC/BRC correlation for RFD-01.", status:"Bank evidence required" },
    ],
    G9_PREP: [
      { section:"Annual return", requirement:"Reconcile Tables 4-18 using filed GSTR-1/1A, GSTR-3B, ITC data and subsequent-period amendments.", status:"FY review" },
      { section:"Liability", requirement:"Flag additional liability separately; do not mark DRC-03 as paid without evidence.", status:"Evidence required" },
    ],
    RCM_RECO: [
      { section:"Liability", requirement:"Books RCM liability versus GSTR-3B Table 3.1(d).", status:"Books import required" },
      { section:"ITC", requirement:"RCM ITC should be tracked after verified tax payment; GSTR-3B aggregates must not be fabricated into invoices.", status:"Timing review" },
    ],
  };
  return common.concat(byKind[kind] || []);
}

function complianceFormulaSheet(kind) {
  let aoa;
  if (kind === "REFUND_IDS") {
    aoa = [["Refund - Inverted Duty Structure (Rule 89(5))","Value","Source / control"],["Turnover of eligible inverted-rated supplies",0,"Classified outward supplies"],["Net ITC on eligible inputs",0,"Exclude services, capital goods and ineligible ITC"],["Adjusted total turnover",0,"Reconciled turnover"],["Tax payable on eligible inverted supplies",0,"Outward classification"],["ITC availed on inputs and input services",0,"Before restricting Net ITC to inputs"],["Maximum refund",0,"Current formula; not below zero"]];
  } else if (kind === "REFUND_EXCESS_CASH") {
    aoa = [["Tax head","Verified available balance","Amount requested","Eligible request"],["IGST",0,0,0],["CGST",0,0,0],["SGST/UTGST",0,0,0],["Cess",0,0,0],["Total",0,0,0]];
  } else if (kind === "REFUND_EXPWT") {
    aoa = [["Export with payment of tax","Taxable value","IGST paid","Refund received","Pending / exception"],["Goods - Rule 96 / Customs",0,0,0,0],["Services - RFD-01 Statement 2",0,0,0,0],["Total",0,0,0,0]];
  } else if (kind === "RCM_RECO") {
    aoa = [["Period / control","IGST","CGST","SGST/UTGST","Cess"],["Books RCM liability",0,0,0,0],["GSTR-3B Table 3.1(d)",0,0,0,0],["Liability difference",0,0,0,0],["Verified cash payment",0,0,0,0],["Cash-payment difference",0,0,0,0],["Eligible RCM ITC after payment",0,0,0,0],["RCM ITC claimed",0,0,0,0],["ITC timing difference",0,0,0,0]];
  } else {
    aoa = [["GSTR-9 preparation control","GSTR-1/Books","GSTR-3B","Proposed GSTR-9","Difference"],["Taxable outward supplies",0,0,0,0],["Zero-rated supplies",0,0,0,0],["Exempt / nil-rated supplies",0,0,0,0],["ITC availed",0,0,0,0],["ITC reversed / ineligible",0,0,0,0],["Tax payable / paid",0,0,0,0]];
  }
  const ws = XLSX.utils.aoa_to_sheet(aoa);
  ws["!cols"] = aoa[0].map((_, i) => ({ wch: i === 0 ? 40 : 18 }));
  for (let c=0;c<aoa[0].length;c+=1) { const ref=XLSX.utils.encode_cell({r:0,c}); ws[ref].s=refundGroupStyle(); }
  if (kind === "REFUND_IDS") ws.B7 = { t:"n", v:0, f:"MAX(0,(B2*B3/B4)-(B5*(B3/B6)))", s:refundNumStyle({bold:true}) };
  if (kind === "REFUND_EXCESS_CASH") {
    for(let r=1;r<=4;r+=1) ws[XLSX.utils.encode_cell({r,c:3})] = {t:"n",v:0,f:`MIN(B${r+1},C${r+1})`,s:refundNumStyle()};
    for(let c=1;c<=3;c+=1) ws[XLSX.utils.encode_cell({r:5,c})] = {t:"n",v:0,f:`SUM(${XLSX.utils.encode_col(c)}2:${XLSX.utils.encode_col(c)}5)`,s:refundNumStyle({bold:true})};
  }
  const differenceRows = kind === "RCM_RECO" ? [[3,1,2],[5,2,4],[8,6,7]] : [];
  differenceRows.forEach(([r,a,b]) => { for(let c=1;c<aoa[0].length;c+=1) if (kind === "RCM_RECO" || c===4) { const col=kind === "RCM_RECO"?c:4; ws[XLSX.utils.encode_cell({r,c:col})]={t:"n",v:0,f:`${XLSX.utils.encode_cell({r:a,c:kind === "RCM_RECO"?c:3})}-${XLSX.utils.encode_cell({r:b,c:kind === "RCM_RECO"?c:2})}`,s:refundNumStyle()}; if(kind!=="RCM_RECO") break; } });
  if (kind === "G9_PREP") for(let r=1;r<aoa.length;r+=1) ws[XLSX.utils.encode_cell({r,c:4})]={t:"n",v:0,f:`D${r+1}-C${r+1}`,s:refundNumStyle()};
  return { name:"Computation", ws };
}

async function buildComplianceWorkingBlob(kind, entries, profile) {
  const sourceRows=[];
  const importedBooks=[];
  (entries||[]).forEach((entry)=>{
    [["GSTR-3B",entry.gstr3b],["GSTR-2B",entry.gstr2b],["GSTR-1 Summary",entry.gstr1_summary],["GSTR-1",entry.gstr1_full]].forEach(([source,payload])=>{
      if(payload) sourceRows.push(...flattenSummaryPayloadRows(source,payload,entry.period));
    });
    if (entry.books && Array.isArray(entry.books.rows)) importedBooks.push(...entry.books.rows);
  });
  const specs=[
    {name:"Requirements",rows:complianceInstructionRows(kind),columns:["section","requirement","status"],options:{schemaReturnType:"GENERIC"}},
    {name:"Portal Source Data",rows:sourceRows,columns:["report_period","source","field","value"],options:{schemaReturnType:"GENERIC"}},
    {name:"Books Import",rows:importedBooks.length?importedBooks:[{period:"",gstin:"",document_number:"",document_date:"",supply_type:"",hsn_sac:"",taxable_value:"",igst:"",cgst:"",sgst:"",cess:"",rcm_status:"",eligibility:"",remarks:""}],columns:getSpreadsheetColumns(importedBooks.length?importedBooks:[{}],["period","gstin","document_number","document_date","supply_type","hsn_sac","taxable_value","igst","cgst","sgst","cess","rcm_status","eligibility","remarks"]),options:{schemaReturnType:"GENERIC"}},
    {name:"Declarations Checklist",rows:complianceInstructionRows(kind).filter(r=>r.section==="Documents"||r.section==="Control"),columns:["section","requirement","status"],options:{schemaReturnType:"GENERIC"}},
    {name:"Taxpayer Profile",rows:[{gstin:(profile&&profile.gstin)||session.gstin||"",legal_name:(profile&&profile.legalName)||"",trade_name:(profile&&profile.tradeName)||"",principal_place:(profile&&profile.address)||"",authorised_signatory:(profile&&profile.signatory&&profile.signatory.name)||""}],columns:["gstin","legal_name","trade_name","principal_place","authorised_signatory"],options:{schemaReturnType:"GENERIC"}},
  ];
  return combineRecoSheetsToBlob([complianceFormulaSheet(kind)],specs);
}

async function buildSimpleRefundDocx(title, paragraphs) {
  const zip = new JSZip();
  const pXml = [title].concat(paragraphs || []).map((text, index) => `<w:p><w:pPr>${index===0?'<w:jc w:val="center"/>':''}</w:pPr><w:r><w:rPr>${index===0?'<w:b/><w:sz w:val="30"/>':''}</w:rPr><w:t xml:space="preserve">${escapeXmlText(text)}</w:t></w:r></w:p>`).join("");
  zip.file("[Content_Types].xml", `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>`);
  zip.folder("_rels").file(".rels", `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>`);
  zip.folder("word").file("document.xml", `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>${pXml}<w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="1440" w:right="1440" w:bottom="1440" w:left="1440"/></w:sectPr></w:body></w:document>`);
  return zip.generateAsync({type:"blob",compression:"DEFLATE"});
}

async function buildIdsReferenceDocument(templateName, profile, periodLabel) {
  const response=await fetch(chrome.runtime.getURL(`templates/ids/${templateName}`));if(!response.ok)throw new Error(`IDS document template missing: ${templateName}`);const zip=await JSZip.loadAsync(await response.arrayBuffer());const path='word/document.xml';const parser=new DOMParser();const serializer=new XMLSerializer();const doc=parser.parseFromString(await zip.file(path).async('string'),'application/xml');
  const legal=(profile&&profile.legalName)||(profile&&profile.tradeName)||'________________';const trade=(profile&&profile.tradeName)||legal;const gstin=(profile&&profile.gstin)||session.gstin||'________________';const address=(profile&&profile.address)||'________________';const jurisdiction=(profile&&profile.jurisdiction&&profile.jurisdiction.raw)||'The Jurisdictional Proper Officer';const today=moment().format('DD.MM.YYYY');
  const replace=[[/ANANTI METAL MART/g,String(legal).toUpperCase()],[/ANANTI METAL MART/g,String(legal).toUpperCase()],[/Ananti Metal Mart/g,legal],[/ANANTI METAL MART/g,String(legal).toUpperCase()],[/33AHMPN7770P1ZH/g,gstin],[/1, Payala Pachaiappan street, Thattangulam, Choolai, Chennai, Tamil Nadu, 600112/g,address],[/JUL[’']24\s*(?:TO|-|To|to)\s*MAY[’']26/gi,periodLabel],[/Jul[’']24\s*(?:to|-|To)\s*May[’']26/g,periodLabel],[/19\.08\.2026/g,today],[/19-08-2026/g,today],[/The Office of Commercial State Taxes,/g,jurisdiction],[/Division- Chennai North-III,/g,''],[/Circle- Choolai/g,''],[/Chennai, Tamil Nadu/g,''],[/Place: Chennai/g,'Place: ________________']];
  Array.from(doc.getElementsByTagNameNS('*','p')).forEach(p=>{const texts=Array.from(p.getElementsByTagNameNS('*','t'));if(!texts.length)return;let value=texts.map(t=>t.textContent||'').join('');if(/engaged in the business of Factory \/ Manufacturing/i.test(value))value=`We, M/s. ${legal}, with GSTIN: ${gstin}, having principal place of business at ${address}, are engaged in registered business activities. The rate-wise classification of outward supplies and inward inputs supporting the inverted duty structure is enclosed with the refund working.`;if(/This is to certify that in respect of the refund amounting to Rs\./i.test(value))value=`This is to certify that in respect of the refund amounting to Rs. ______________ (Rupees ______________________________________________ only) claimed by M/s. ${legal} ('the applicant') having GSTIN No. ${gstin}, for the tax period ${periodLabel}, the incidence of tax and interest has not been passed on to any other person.`;if(/^CA Appala Naidu Kotla/i.test(value))value='Name of Chartered Accountant: ____________________';if(/Membership No: 246404/i.test(value))value=`Membership No: ______________    Date: ${today}    UDIN: ____________________    Place: ________________`;
    replace.forEach(([a,b])=>{value=value.replace(a,b);});texts[0].textContent=value;texts[0].setAttribute('xml:space','preserve');for(let i=1;i<texts.length;i+=1)texts[i].textContent='';});zip.file(path,serializer.serializeToString(doc));const bytes=await zip.generateAsync({type:'arraybuffer',compression:'DEFLATE'});return new Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'});
}

async function buildRefundSupportDocuments(kind, profile, periodLabel) {
  const legal = (profile&&profile.legalName)||"________________";
  const gstin = (profile&&profile.gstin)||session.gstin||"________________";
  const signatory = (profile&&profile.signatory&&profile.signatory.name)||"________________";
  const address=(profile&&profile.address)||"________________";
  const jurisdiction=(profile&&profile.jurisdiction&&profile.jurisdiction.raw)||"The Jurisdictional Proper Officer";
  const common=[`Applicant: ${legal}`,`GSTIN: ${gstin}`,`Principal place of business: ${address}`,`Refund period: ${periodLabel}`,`Authorised signatory: ${signatory}`,"Place: ________________    Date: ________________"];
  const content={
    REFUND_IDS:["The claim relates to accumulated input tax credit arising from an eligible inverted duty structure under clause (ii) of the first proviso to section 54(3), computed under Rule 89(5).","The turnover identified as inverted-rated supply and the tax payable thereon have been separately classified and reconciled with filed returns and books.","Net ITC includes eligible credit on inputs only. Input services, capital goods, blocked credit, ineligible credit and amounts covered by Rule 89(4A)/(4B), where applicable, have been excluded from Net ITC.","The same amount has not been claimed under another refund category or in another application.","If any sanctioned amount is subsequently found inadmissible, the applicant undertakes to repay it with applicable interest."],
    REFUND_EXCESS_CASH:["The amount requested represents excess balance verified in the electronic cash ledger after considering utilisation, transfer and outstanding liabilities.","The applicant confirms that the same balance has not been claimed elsewhere and authorises debit of the claimed amount from the electronic cash ledger."],
    REFUND_EXPWT:["For goods, invoice, shipping bill, EGM and Customs refund-status evidence must be reconciled under Rule 96.","For services, export invoices and FIRC/BRC realisation evidence must agree with Statement 2 and the amount of integrated tax actually paid.","The applicant confirms that no duplicate refund has been claimed for the same invoices."],
  };
  if(kind === "REFUND_IDS") return [
    {name:"01 Covering Letter.docx",blob:await buildIdsReferenceDocument("Covering Letter.docx",profile,periodLabel)},
    {name:"02 Declaration - Section 54(3).docx",blob:await buildIdsReferenceDocument("Refund Declarations _ 54(3).docx",profile,periodLabel)},
    {name:"03 Declaration - Section 54(3)(ii).docx",blob:await buildIdsReferenceDocument("Refund Declarations _ 54(3)(ii).docx",profile,periodLabel)},
    {name:"04 Undertaking - Section 16(2)(c).docx",blob:await buildIdsReferenceDocument("Undertaking 16(2)(c) of CGST Act.docx",profile,periodLabel)},
    {name:"05 CA Certificate - Refund.docx",blob:await buildIdsReferenceDocument("CA Certificate_Refund.docx",profile,periodLabel)},
  ];
  if(kind === "REFUND_EXPWT") return [
    {name:"01 Covering Letter - Export With Tax.docx",blob:await buildSimpleRefundDocx("REFUND - EXPORT WITH PAYMENT OF INTEGRATED TAX",[`To: ${jurisdiction}`,"Subject: Refund of integrated tax paid on eligible exports.","Sir / Madam,",`We submit the export-with-payment refund working for ${legal} covering ${periodLabel}. Goods exports are reconciled through the Rule 96 / Customs route, while service exports are supported through RFD-01 Statement 2 and FIRC/BRC evidence.`,"The invoice register, GSTR-1 versus GSTR-3B reconciliation and supporting schedules are enclosed.",...common])},
    {name:"02 Declaration - No Duplicate Export Refund.docx",blob:await buildSimpleRefundDocx("DECLARATION - EXPORT WITH PAYMENT OF TAX",["I/We declare that the same export invoices and integrated tax have not been claimed under another refund category or application.","For goods, the shipping bill, export manifest/report and Customs refund status have been verified. For services, the export conditions and foreign-exchange realisation evidence have been verified.","Invoices marked pending or incomplete in the working have not been treated as fully supported merely because they appear in GSTR-1.",...common])},
    {name:"03 Undertaking for Inadmissible Refund.docx",blob:await buildSimpleRefundDocx("UNDERTAKING",["I/We undertake to repay any refund found to have been erroneously or inadmissibly sanctioned, together with applicable interest and consequences under law.","I/We confirm that the particulars furnished in the application and supporting statements are true and correct to the best of my/our knowledge and belief.",...common])},
    {name:"04 Export Refund Document Checklist.docx",blob:await buildSimpleRefundDocx("DOCUMENT CHECKLIST - EXPORT WITH PAYMENT OF TAX",["[ ] Export invoices agree with GSTR-1 Table 6A","[ ] Zero-rated turnover and IGST agree with GSTR-3B Table 3.1(b)","[ ] Goods: shipping bill / bill of export details verified","[ ] Goods: EGM / export report status verified","[ ] Goods: Customs scroll/refund status and bank credit verified","[ ] Services: Statement 2 prepared","[ ] Services: FIRC/BRC and realisation date verified","[ ] Export eligibility and place-of-supply conditions reviewed","[ ] Duplicate refund check completed","[ ] Registration, bank account and authorised signatory verified",...common])},
  ];
  if(kind === "REFUND_EXCESS_CASH") return [
    {name:"01 Covering Letter - Excess Cash Balance.docx",blob:await buildSimpleRefundDocx("REFUND OF EXCESS BALANCE IN ELECTRONIC CASH LEDGER",[`To: ${jurisdiction}`,"Subject: Application for refund of excess balance in the Electronic Cash Ledger.","Sir / Madam,",`We submit the refund application of ${legal} for the excess balance verified in the Electronic Cash Ledger. The enclosed head-wise claim, portal ledger, liability checks and taxpayer particulars form part of this application.`,"We request sanction of the admissible amount after verification of the electronic liability and cash ledgers.",...common])},
    {name:"02 Declaration - Excess Cash Ledger Balance.docx",blob:await buildSimpleRefundDocx("DECLARATION - EXCESS CASH LEDGER BALANCE",["I/We declare that the amount requested is restricted to the verified balance available under each major and minor head of the Electronic Cash Ledger.","The claimed balance has not been utilised, transferred through Form GST PMT-09, adjusted against liability, or claimed in another refund application.","Outstanding return liabilities, demands and recovery proceedings have been reviewed before filing the application.",...common])},
    {name:"03 Undertaking for Inadmissible Refund.docx",blob:await buildSimpleRefundDocx("UNDERTAKING",["I/We undertake to repay any refund found to have been erroneously or inadmissibly sanctioned, together with applicable interest and consequences under law.","I/We confirm that the particulars and ledger balances furnished are true and correct to the best of my/our knowledge and belief.",...common])},
    {name:"04 Cash Ledger Refund Checklist.docx",blob:await buildSimpleRefundDocx("DOCUMENT CHECKLIST - EXCESS CASH BALANCE",["[ ] Electronic Cash Ledger downloaded up to the claim date","[ ] Amount requested checked separately for every major and minor head","[ ] Electronic Liability Ledger and outstanding return liability verified","[ ] Outstanding demand / recovery proceedings verified","[ ] PMT-09 transfers and subsequent utilisation verified","[ ] Duplicate refund claim check completed","[ ] RFD-01 amount agrees with the head-wise claim","[ ] Registration, bank account and authorised signatory verified",...common])},
  ];
  return [
    {name:"Refund Covering Letter.docx",blob:await buildSimpleRefundDocx("REFUND APPLICATION - COVERING LETTER",common.concat(content[kind]||[]))},
    {name:"Refund Declaration and Undertaking.docx",blob:await buildSimpleRefundDocx("DECLARATION AND UNDERTAKING",(content[kind]||[]).concat(common))},
    {name:"Refund Document Checklist.docx",blob:await buildSimpleRefundDocx("SUPPORTING DOCUMENT CHECKLIST",complianceInstructionRows(kind).map(r=>`[ ] ${r.requirement}`).concat(common))},
  ];
}

async function downloadSummaryAll(mode) {
  // Recover the config if session.return was left stale (e.g. a category read
  // that resolved to an empty string). getCurrentTypeConfig reads the live
  // category + type selector, so it always reflects what the user selected.
  const cfg = session.return || getCurrentTypeConfig();
  if (cfg && !session.return) session.return = cfg;
  // Download All must also fetch a new portal snapshot; otherwise it can reuse
  // the immediately preceding run's period payloads from the open popup.
  clearRecoCache();
  const btn = getElement(mode === "excel" ? "btn-summary-all-excel" : "btn-summary-all-json");
  if (btn) {
    btn.disabled = true;
    btn.textContent = mode === "excel" ? "Preparing Excel..." : "Downloading JSON...";
  }
  setBulkActionMessage(null);
  let periods = (session.periods || []).filter((period) => period && period.isValid);
  // v2.3 — an FY-wide report is the same file for every period in the year;
  // fetch it once instead of twelve identical times.
  if (cfg && cfg.fyWide && periods.length > 1) periods = [periods[0]];
  const entries = [];
  const failures = [];
  const generating = [];

  // REFUND_EXPWOP — pull the Electronic Credit Ledger FIRST, while the portal
  // tab is still on return.gst.gov.in with a live session. prefetchRecoPayloads
  // ByHost() below finishes on gstr2b.gst.gov.in, and arriving at the ledger
  // endpoint cold from there is what made the ECL sheet go missing.
  let refundEcl = null;
  let refundCash = null;
  let refundProfile = null;
  if (cfg && ["REFUND_EXPWOP", "REFUND_IDS", "REFUND_EXCESS_CASH", "REFUND_EXPWT", "G9_PREP"].includes(cfg.key) && mode === "excel") {
    if (["REFUND_EXPWOP", "REFUND_IDS"].includes(cfg.key)) {
      if (btn) btn.textContent = "Fetching Electronic Credit Ledger...";
      refundEcl = await refundFetchEclBundle(periods);
      if (refundEcl.ok) {
        addActivity(`ECL fetched (${refundEcl.from} to ${refundEcl.to}).`, "text-success");
      } else {
      // Loud, not "text-muted" — a refund working paper without the ECL is not
      // a silently-acceptable outcome.
      addActivity(
        `ECL fetch failed: ${refundEcl.error} — the workbook will carry a blank ECL template for manual entry.`,
        "text-danger",
      );
        // NOTE: ECL failure is intentionally NOT added to failures[] — the
        // refundBuildEclPlaceholderSheet() already handles missing ECL by
        // labelling the sheet with the portal's error message so the user can
        // fill the balance manually.  Pushing to failures[] would abort the
        // entire workbook for REFUND_EXPWOP/IDS via the refundRequiresGstr1
        // InvoiceDetails guard on line ~24833, which is not what we want.
      }
    }
    if (cfg.key === "REFUND_EXCESS_CASH") {
      if (btn) btn.textContent = "Fetching Electronic Cash Ledger...";
      refundCash = await refundFetchCashBundle(periods);
      if (refundCash.ok) addActivity(`Cash ledger fetched (${refundCash.from} to ${refundCash.to}).`, "text-success");
      else { addActivity(`Cash ledger fetch failed: ${refundCash.error} — manual head-wise entry will remain available.`, "text-danger"); failures.push(`Cash ledger: ${refundCash.error}`); }
    }
    if (btn) btn.textContent = "Fetching company profile...";
    try {
      refundProfile = await refundFetchCompanyProfile(session.gstin);
      if (!refundProfile || !refundProfile.address) {
        failures.push("Company profile: principal place of business address was not returned by the portal");
      }
    } catch (profileErr) {
      failures.push(`Company profile: ${profileErr && profileErr.message ? profileErr.message : profileErr}`);
      refundProfile = null;
    }
  }

  // v2.3.2 — warm every period's data one subdomain at a time before building
  // anything. Without this, the loop below bounced the portal tab between
  // return.gst.gov.in and gstr2b.gst.gov.in once per period.
  try {
    await prefetchRecoPayloadsByHost(cfg, periods, ({ host, index, total }) => {
      if (btn) {
        const label = host === "gstr2b.gst.gov.in" ? "GSTR-2B" : "portal returns";
        btn.textContent = `Fetching ${label} (${index}/${total})...`;
      }
    });
  } catch (err) {
    addActivity(`Prefetch could not complete: ${err && err.message ? err.message : err}`, "text-warning");
  }

  for (let i = 0; i < periods.length; i += 1) {
    const period = periods[i];
    if (btn) btn.textContent = mode === "excel" ? `Preparing (${i + 1}/${periods.length})...` : `Downloading (${i + 1}/${periods.length})...`;
    try {
      // eslint-disable-next-line no-await-in-loop
      const payload = await fetchSummaryPayload(cfg, period);
      entries.push({ period, payload });
    } catch (err) {
      const message=err&&err.message?err.message:"Failed";
      if(isPortalGenerationMessage(message)){
        const label=`${cfg.display||cfg.key} for period ${period.value}`;
        generating.push(label);showPortalGenerationNotice(label);
      }else failures.push(`${period.value}: ${message}`);
    }
  }
  try {
    if(generating.length)throw new Error(`GST Portal is generating ${generating.slice(0,3).join(", ")}${generating.length>3?` and ${generating.length-3} more period(s)`:""}. No partial report was downloaded. Please try again after generation is complete.`);
    if(cfg&&refundRequiresGstr1InvoiceDetails(cfg)&&failures.length)throw new Error(`${cfg.display||cfg.key} export stopped because current GST Portal data was incomplete: ${failures.slice(0,3).join("; ")}${failures.length>3?`; and ${failures.length-3} more error(s)`:""}. No partial workbook was downloaded.`);
    if (!entries.length) throw new Error(failures[0] || "No summary data downloaded");
    const periodTag = entries.length > 1
      ? `${entries[0].period.value}_to_${entries[entries.length - 1].period.value}`
      : entries[0].period.value;
    const gstinForFile = resolveSummaryGstin() || session.gstin || "GSTIN";
    const fileBase = makeJsonFileName(cfg.fileNameCode || cfg.key, gstinForFile, periodTag);
    if (mode === "excel") {
      let blob;
      let downloadFilename = `${fileBase}_ALL.xlsx`;
      const recoEntries = entries.map((entry) => {
        const d = entry.payload && entry.payload.data ? entry.payload.data : {};
        return {
          period: entry.period.value,
          gstr3b: d.gstr3b, gstr2a: d.gstr2a, gstr2b: d.gstr2b,
          gstr1_summary: d.gstr1_summary, gstr1_full: d.gstr1_full, books: d.books, ims: d.ims,
          eway:d.eway,einvoice:d.einvoice,imsFile:d.imsFile,imsError:d.imsError,
        };
      });
      if (cfg.key === "G3B_VS_G1SUM") {
        blob = await buildReco3bVs1V2Blob(recoEntries);
      } else if (cfg.key === "G3B_VS_G2ASUM") {
        blob = await buildReco3bVs2aV2Blob(recoEntries.map((e) => ({ period: e.period, gstr3b: e.gstr3b, gstr2a: e.gstr2a })));
      } else if (cfg.key === "G3B_VS_G2BSUM") {
        blob = await buildReco3bVs2bV2Blob(recoEntries.map((e) => ({ period: e.period, gstr3b: e.gstr3b, gstr2b: e.gstr2b, ims: e.ims })));
      } else if (cfg.key === "G2A_VS_G2BSUM") {
        blob = await buildReco2aVs2bV2Blob(recoEntries);
      } else if (cfg.key === "VENDOR_INTEL") {
        blob = await buildVendorIntelConsolidatedBlob(recoEntries);
      } else if (cfg.key === "G3B_ECL") {
        blob = await buildReco3bEclV2Blob(recoEntries);
      } else if (cfg.key === "CMP_FY") {
        const data = entries[0].payload.data || {};
        blob = buildComparisonReportBlob({fy:data.fy,data:data.comparison,itc3bByPeriod:data.itc3bByPeriod}, gstinForFile);
      } else if (cfg.key === "BOOKS_2B") {
        blob = await buildBooksVs2bConsolidatedBlob(recoEntries);
      } else if(cfg.key==="OUTPUT_RECO"){
        blob=await buildOutputReconciliationsBlob(recoEntries);
      } else if (["REFUND_IDS", "REFUND_EXCESS_CASH", "REFUND_EXPWT", "G9_PREP", "RCM_RECO"].includes(cfg.key)) {
        blob = cfg.key === "REFUND_IDS"
          ? await buildRefundIdsBlob(recoEntries, { ecl:refundEcl, eclAfter3b:refundEcl&&refundEcl.eclAfter3b, eclClaimDate:refundEcl&&refundEcl.eclClaimDate, profile:refundProfile })
          : cfg.key === "REFUND_EXPWT"
            ? await buildRefundExpwtBlob(recoEntries,{profile:refundProfile})
            : cfg.key === "REFUND_EXCESS_CASH"
              ? await buildRefundExcessCashBlob(recoEntries,{profile:refundProfile,cash:refundCash})
            : cfg.key === "G9_PREP"
              ? await buildGstr9OfflineToolBlob(recoEntries,refundProfile)
            : await buildComplianceWorkingBlob(cfg.key, recoEntries, refundProfile);
        if (cfg.key === "G9_PREP") downloadFilename = `${fileBase}_ALL.xlsm`;
        if (["REFUND_IDS", "REFUND_EXCESS_CASH", "REFUND_EXPWT"].includes(cfg.key)) {
          const docs = await buildRefundSupportDocuments(cfg.key, refundProfile, refundPeriodLabel(recoEntries));
          const refundZip = new JSZip();
          refundZip.file(`${fileBase}_ALL.xlsx`, await blob.arrayBuffer());
          docs.forEach((doc) => refundZip.file(doc.name, doc.blob));
          blob = await refundZip.generateAsync({ type:"blob", compression:"DEFLATE" });
          downloadFilename = `${fileBase}_ALL.zip`;
        }
      } else if (cfg.key === "REFUND_EXPWOP") {
        // The ECL (sheet + both balance snapshots) was fetched up-front in a
        // single round-trip by refundFetchEclBundle(), before the GSTR fetches
        // moved the tab off return.gst.gov.in. Nothing is re-fetched here.
        //   • eclAfter3b   = closing balance as on the end of the last refund month
        //   • eclClaimDate = closing balance as on today (date of claim)
        // Either may be null; buildRefundComputationSheet leaves that column
        // manual when it is.
        blob = await buildRefundExpwopBlob(recoEntries, {
          ecl: refundEcl,
          eclAfter3b: refundEcl ? refundEcl.eclAfter3b : null,
          eclClaimDate: refundEcl ? refundEcl.eclClaimDate : null,
          profile: refundProfile,
        });
        const docs = await refundBuildWordDocuments(recoEntries, Object.assign({}, refundIdentity(recoEntries), refundProfile || {}));
        const refundZip = new JSZip();
        refundZip.file(`${fileBase}_ALL.xlsx`, await blob.arrayBuffer());
        for (const doc of docs) refundZip.file(doc.name, await doc.blob.arrayBuffer());
        blob = await refundZip.generateAsync({ type: "blob", compression: "DEFLATE" });
        downloadFilename = `${fileBase}_ALL.zip`;
      } else if (cfg.key === "G1_VS_IMSOUT") {
        blob = await buildG1VsImsConsolidatedBlob(entries);
      } else {
        blob = ["E_INVOICE", "G1_VS_EINV"].includes(cfg.key) ? await buildEinvoiceWorkbookBlob(entries,cfg.key==="G1_VS_EINV")
          : ["EWAY_BILL", "G1_VS_EWB"].includes(cfg.key) ? await buildEwayWorkbookBlob(entries, cfg.key === "G1_VS_EWB") : cfg.key === "G1SUM"
          ? await buildXlsxBlobFromWorkbookXml(buildCombinedGstr1SummaryWorkbookXml(entries))
          : await buildXlsxBlobFromSheets(buildCombinedSummaryWorkbookSheets(cfg, entries), { compression: true });
      }
      await downloadBlobAs(blob, downloadFilename);
    } else {
      const payload = {
        return_type: cfg.key,
        entries: entries.map((entry) => ({ period: entry.period.value, payload: entry.payload })),
        failures,
      };
      await downloadBlobAs(
        new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" }),
        `${fileBase}_ALL.json`,
      );
    }
    if (failures.length) {
      setBulkActionMessage(`Downloaded with issues. ${failures.slice(0, 3).join(" | ")}`, "warning");
    } else {
      setBulkActionMessage("Downloaded summary successfully.", "success");
    }
    if (btn) btn.textContent = mode === "excel" ? "Download All Excel" : "Download All JSON";
  } catch (err) {
    const message=err&&err.message?err.message:"Summary download failed";
    setBulkActionMessage(message,isPortalGenerationMessage(message)?"warning":"danger");
    if (btn) btn.textContent = "Failed";
  } finally {
    if (btn) btn.disabled = false;
  }
}

// ── Pure challan export builder (DOM-free) ──────────────────────────
// Extracted from downloadOther()'s CHALLAN_LIST branch so Get All can
// reuse it directly with an explicit FY date range.
// Resolve the working GSTIN from the most reliable source available, in
// order of trust: an already-resolved session value, the client the user
// picked in client-management, the GSTIN embedded in the portal's own
// ustatus JSON response (harvested as a side effect of fetchSubdomainAtToken
// — reliable because it comes from the portal's session data, not the page's
// visible text), and only as a last resort the page-text scrape (getGstin).
// The scrape is unreliable during Get All because by the time challan/notices
// run the tab may have navigated to a payment/services page whose text
// doesn't contain the GSTIN at all — which is what produced the persistent
// "Missing GSTIN" failures even after the previous cache-based fix.
async function resolveSessionGstin() {
  const cached = normalizeGstin(
    session.gstin || session.selectedClientGstin || session.portalGstin,
  );
  if (cached) {
    session.gstin = cached;
    return cached;
  }
  // Try minting an at-token on whatever host we're already connected to —
  // this doesn't require a subdomain switch and fetchSubdomainAtToken
  // populates session.gstin from the ustatus JSON body as a side effect.
  if (currentUrl && currentUrl.origin) {
    await fetchSubdomainAtToken(currentUrl.origin).catch(() => null);
    if (session.gstin) return normalizeGstin(session.gstin);
  }
  // Fall back to services.gst.gov.in specifically — it's the base "you are
  // logged in" domain and typically reachable even when other subdomain
  // switches fail.
  await fetchSubdomainAtToken("https://services.gst.gov.in").catch(() => null);
  if (session.gstin) return normalizeGstin(session.gstin);
  const gstinMsg = await processAsync({ request: "getGstin" }).catch(() => null);
  if (gstinMsg && gstinMsg.status && gstinMsg.response) {
    const scraped = normalizeGstin(gstinMsg.response);
    if (scraped) {
      session.gstin = scraped;
      return scraped;
    }
  }
  return "";
}

async function buildChallanExport(from, to) {
  if (!session.gstin) {
    await resolveSessionGstin();
  }
  if (!session.gstin) throw new Error("Missing GSTIN");
  const startDate = moment(from, "YYYY-MM-DD", true);
  const endDate = moment(to, "YYYY-MM-DD", true);
  if (!startDate.isValid() || !endDate.isValid()) throw new Error("Invalid date range");

  await ensureConnectedToHost("payment.gst.gov.in");
  const cfg = otherConfig.CHALLAN_LIST;
  const ranges = [];
  let cursor = startDate.clone();
  while (cursor.isSameOrBefore(endDate, "day")) {
    const chunkEnd = cursor.clone().add(3, "months").subtract(1, "day");
    const end = chunkEnd.isAfter(endDate) ? endDate.clone() : chunkEnd;
    ranges.push({ from: cursor.clone(), to: end.clone() });
    cursor = end.clone().add(1, "day");
  }

  const consolidated = {
    gstin: session.gstin,
    from: formatLedgerDate(startDate, "DD/MM/YYYY"),
    to: formatLedgerDate(endDate, "DD/MM/YYYY"),
    chunks: [],
    data: [],
    raw: [],
  };

  // payment.gst.gov.in's challan API expects the subdomain's own session
  // token (same pattern litserv uses) — mint it once up front.
  const paymentAt = await fetchSubdomainAtToken("https://payment.gst.gov.in");
  const challanHeaders = paymentAt ? { at: paymentAt } : undefined;

  for (let i = 0; i < ranges.length; i++) {
    const r = ranges[i];
    const url = withParams(cfg.base, [
      ["fm_dt", formatLedgerDate(r.from, "DD/MM/YYYY")],
      ["to_dt", formatLedgerDate(r.to, "DD/MM/YYYY")],
      ["gstin", session.gstin],
    ]);
    const msg = await processAsync({ request: "get", url, headers: challanHeaders });
    if (!msg.status) throw new Error(msg.statusCode ? `HTTP ${msg.statusCode}` : "Failed");
    let parsed = null;
    try {
      parsed = JSON.parse(msg.response);
    } catch (e) {
      parsed = msg.response;
    }
    consolidated.chunks.push({
      from: formatLedgerDate(r.from, "DD/MM/YYYY"),
      to: formatLedgerDate(r.to, "DD/MM/YYYY"),
    });
    consolidated.raw.push(parsed);

    if (Array.isArray(parsed)) {
      consolidated.data = consolidated.data.concat(parsed);
    } else if (parsed && Array.isArray(parsed.data)) {
      consolidated.data = consolidated.data.concat(parsed.data);
    } else if (parsed && parsed.data && Array.isArray(parsed.data.challans)) {
      consolidated.data = consolidated.data.concat(parsed.data.challans);
    } else if (parsed && parsed.data && Array.isArray(parsed.data.list)) {
      consolidated.data = consolidated.data.concat(parsed.data.list);
    }
  }

  const exportFrom = consolidated.from || formatLedgerDate(startDate, "DD/MM/YYYY");
  const exportTo = consolidated.to || formatLedgerDate(endDate, "DD/MM/YYYY");
  return { consolidated, exportFrom, exportTo };
}

async function downloadOther(cfg, period, mode) {
  const btn = getElement("btn-other-download");
  const btnJson = getElement("btn-other-json");
  const btnExcel = getElement("btn-other-excel");
  const statusCell =
    cfg.key === "IMS_IN" || cfg.key === "IMS_OUT"
      ? getElement(`info-${period || ""}`) || getElement("other-status")
      : getElement("other-status");
  const isIms = cfg.key === "IMS_IN" || cfg.key === "IMS_OUT";
  const activeMode = mode === "excel" ? "excel" : "json";
  const activeBtn = activeMode === "excel" ? btnExcel : btnJson;
  if (btn && !isIms) btn.disabled = true;
  if (btnJson) btnJson.disabled = true;
  if (btnExcel) btnExcel.disabled = true;
  if (activeBtn) activeBtn.textContent = activeMode === "excel" ? "Preparing..." : "Downloading...";
  if (statusCell) statusCell.innerHTML = pill("Working", "warning");

  try {
    if (cfg.key === "IMS_OUT") {
      addActivity(`IMS Outward firing for period ${period || "(none)"}`, "text-muted");
    } else if (cfg.key === "IMS_IN") {
      addActivity(`IMS Inward firing`, "text-muted");
    }
    if (cfg.key === "CHALLAN_LIST") {
      const domFrom = getElement("ledgerDateFrom") ? getElement("ledgerDateFrom").value : "";
      const domTo = getElement("ledgerDateTo") ? getElement("ledgerDateTo").value : "";
      const from = (period && period.fromOverride) || domFrom;
      const to = (period && period.toOverride) || domTo;
      const { consolidated, exportFrom, exportTo } = await buildChallanExport(from, to);

      if (activeMode === "excel") {
        const workbookXml = buildChallanWorkbookXml(consolidated);
        const xlsxBlob = await buildXlsxBlobFromWorkbookXml(workbookXml);
        const fname = makeNamedRangeExportFileName(cfg, exportFrom, exportTo, "xlsx");
        await downloadBlobAs(xlsxBlob, fname);
      } else {
        const fname = makeNamedRangeExportFileName(cfg, exportFrom, exportTo, "json");
        const blobUrl = URL.createObjectURL(
          new Blob([JSON.stringify(consolidated, null, 2)], { type: "application/json" }),
        );
        downloadAs(blobUrl, fname);
      }
      if (statusCell) statusCell.innerHTML = pill("Downloaded", "success");
    } else if (cfg.key === "IMS_IN" || cfg.key === "IMS_OUT") {
      await ensureConnectedToHost("return.gst.gov.in");
      const requestUrl =
        cfg.key === "IMS_IN"
          ? cfg.base
          : withParams(cfg.base, [
              ["rtnTyp", "R1"],
              ["section", "ALLOSP"],
              ["viewTyp", "UNI"],
              ["rtnPrd", period || ""],
            ]);
      addActivity(`${cfg.display} request: ${requestUrl}`, "text-muted");
      const msg = await portalGet(requestUrl);
      if (!msg || !msg.status) {
        addActivity(`${cfg.display} failed (${(msg && msg.error) || (msg && msg.statusCode) || "no status"})`, "text-danger");
        throw new Error((msg && msg.error) || "Failed");
      }
      let parsed = null;
      try { parsed = JSON.parse(msg.response); } catch (e) { parsed = null; }
      const finalUrl = getImsOutDownloadUrl(parsed);
      if (finalUrl) {
        addActivity(`${cfg.display} URL: ${finalUrl}`, "text-muted");
        const safePeriod = period || moment().format("MMYYYY");
        // The IMS endpoints serve an Excel workbook, not JSON — naming it .json
        // produced a file Excel refused to open until it was renamed by hand.
        const fname = `${session.gstin || "GSTIN"}_${cfg.fileNameCode}_${safePeriod}.xlsx`;
        if (statusCell) statusCell.innerHTML = pill("Downloading...", "warning");
        await saveRemoteFileWithName(finalUrl, fname, cfg.contentType);
        if (statusCell) statusCell.innerHTML = pill("Downloaded", "success");
      } else {
        const failureText = getOtherResponseMessage(parsed, "No file url");
        addActivity(`${cfg.display}: ${failureText}`, "text-danger");
        if (statusCell) statusCell.innerHTML = pill(failureText, "danger");
        throw new Error(failureText);
      }
    }
  } catch (e) {
    if (statusCell) statusCell.innerHTML = pill(e && e.message ? e.message : "Failed", "danger");
    if (btn) btn.disabled = false;
    if (btnJson) {
      btnJson.disabled = false;
      btnJson.textContent = "JSON";
    }
    if (btnExcel) {
      btnExcel.disabled = false;
      btnExcel.textContent = "Excel";
    }
    // Inside Get All there is no status cell to read, so swallowing the error
    // made a failed item report "Downloaded". Surface it to runGetAllItem().
    if (__getAllCollector) throw e;
    return;
  }

  if (btn) {
    btn.textContent = "Download";
    btn.disabled = false;
  }
  if (btnJson) {
    btnJson.textContent = "JSON";
    btnJson.disabled = false;
  }
  if (btnExcel) {
    btnExcel.textContent = "Excel";
    btnExcel.disabled = false;
  }
}

// ── IMS → Excel ─────────────────────────────────────────────────────
// The IMS endpoints hand back a generated file, not a report. Get All was
// therefore dropping raw .json into the zip while every other item shipped a
// workbook. The IMS schema is deep and varies by section (b2b, b2ba, cdnr,
// cdnra, …), so rather than hard-code it, walk the payload, find every array
// of objects, and give each one its own sheet.

// ── Reading the generated IMS file ──────────────────────────────────
// Three layers of packaging, each of which has bitten us:
//   1. The response BODY is often a `data:` URL string, not raw bytes. That is
//      why decodeDataUrlPayload() exists. Sniffing magic bytes before
//      unwrapping this sees "d" (from "data:") and never finds the archive.
//   2. Once unwrapped it is usually a ZIP — because the portal's IMS export is
//      a real .xlsx workbook, not JSON. Its first entry may be `_rels/.rels`,
//      so testing only for a leading `[Content_Types].xml` is not enough.
//   3. Some tenants get a plain JSON document instead.
// Unwrap in that order, and sniff on bytes rather than on decoded text.

const ZIP_MAGIC = [0x50, 0x4b, 0x03, 0x04];

function bytesFromBinaryString(binary) {
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i) & 0xff;
  return bytes;
}

// Percent-decoding to BYTES. decodeURIComponent() would reassemble the %XX
// sequences as UTF-8 and throw URIError on arbitrary binary — which is exactly
// how a perfectly good ZIP got mistaken for broken JSON.
function percentDecodeToBytes(text) {
  const out = [];
  for (let i = 0; i < text.length; i += 1) {
    const ch = text[i];
    if (ch === "%" && i + 2 < text.length) {
      const hex = text.substr(i + 1, 2);
      if (/^[0-9a-f]{2}$/i.test(hex)) {
        out.push(parseInt(hex, 16));
        i += 2;
        continue;
      }
    }
    out.push(ch.charCodeAt(0) & 0xff);
  }
  return new Uint8Array(out);
}

// If the payload is a `data:` URL, return the bytes it encodes; else null.
function unwrapDataUrlBytes(bytes) {
  const head = new TextDecoder("latin1").decode(bytes.subarray(0, 64));
  if (!/^\s*data:/i.test(head)) return null;
  const text = new TextDecoder("latin1").decode(bytes).replace(/^\s+/, "");
  const commaIdx = text.indexOf(",");
  if (commaIdx < 0) return null;
  const meta = text.slice(0, commaIdx);
  const payload = text.slice(commaIdx + 1);
  try {
    if (/;base64/i.test(meta)) return bytesFromBinaryString(atob(payload));
    return percentDecodeToBytes(payload);
  } catch (e) {
    return null;
  }
}

function looksLikeZip(bytes) {
  if (!bytes || bytes.length < 4) return false;
  // Tolerate leading whitespace — the portal has shipped bodies with it before.
  let offset = 0;
  while (offset < 8 && (bytes[offset] === 0x20 || bytes[offset] === 0x0a || bytes[offset] === 0x0d || bytes[offset] === 0x09)) offset += 1;
  return ZIP_MAGIC.every((byte, index) => bytes[offset + index] === byte);
}

function stripLeadingWhitespaceBytes(bytes) {
  let offset = 0;
  while (offset < 8 && (bytes[offset] === 0x20 || bytes[offset] === 0x0a || bytes[offset] === 0x0d || bytes[offset] === 0x09)) offset += 1;
  return offset ? bytes.subarray(offset) : bytes;
}

// The IMS export IS an Excel workbook — the ZIP has no JSON inside it. Re-parsing
// it with sheet_to_json and rebuilding would silently mangle the portal's title
// rows and merged headers into __EMPTY columns, so the workbook is carried
// through verbatim and only *combined* when several periods are requested.
// The JSON branch below is a fallback for tenants whose portal returns a plain
// document instead; it is not the normal path.
function readImsWorkbook(bytes) {
  if (typeof XLSX === "undefined" || !XLSX || typeof XLSX.read !== "function") {
    throw new Error("SheetJS (XLSX) is required to read the IMS workbook.");
  }
  return XLSX.read(bytes, { type: "array", cellStyles: true, cellDates: true });
}

async function imsFileFromZip(bytes) {
  const zip = await JSZip.loadAsync(bytes);
  const names = Object.keys(zip.files).filter((name) => !zip.files[name].dir);

  // An OOXML package: [Content_Types].xml and xl/workbook.xml both identify it,
  // and neither is guaranteed to be the first entry.
  const isXlsx =
    names.some((name) => /^\[Content_Types\]\.xml$/i.test(name)) ||
    names.some((name) => /^xl\/workbook\.xml$/i.test(name));
  if (isXlsx) return { kind: "xlsx", bytes };

  // Defensive: a ZIP that merely wraps a workbook or a JSON document.
  const innerXlsx = names.find((name) => /\.xlsx?$/i.test(name));
  if (innerXlsx) return { kind: "xlsx", bytes: await zip.file(innerXlsx).async("uint8array") };

  const innerJson = names.find((name) => /\.json$/i.test(name)) || (names.length === 1 ? names[0] : null);
  if (innerJson) return { kind: "json", text: await zip.file(innerJson).async("string") };

  throw new Error(`The IMS archive has no readable document (entries: ${names.slice(0, 5).join(", ")})`);
}

// Returns { kind: "xlsx", bytes } or { kind: "json", text }.
async function fetchImsFile(url) {
  const msg = await bgFetch(url, { method: "GET", responseType: "arraybuffer" });
  if (!msg || !msg.status) {
    throw new Error((msg && msg.error) || (msg && msg.statusCode ? `HTTP ${msg.statusCode}` : "Could not read the generated IMS file"));
  }

  let bytes = bytesFromBinaryString(atob(msg.responseBase64 || ""));
  if (!bytes.length) throw new Error("The IMS file came back empty");

  // Layer 1: the body may be a data: URL wrapping the real content.
  const unwrapped = unwrapDataUrlBytes(bytes);
  if (unwrapped && unwrapped.length) bytes = unwrapped;

  // Layer 2: ZIP — in practice always the .xlsx itself.
  if (looksLikeZip(bytes)) return imsFileFromZip(stripLeadingWhitespaceBytes(bytes));

  // Layer 3: plain JSON. Decode as UTF-8 so non-ASCII trade names survive.
  return { kind: "json", text: new TextDecoder("utf-8").decode(bytes) };
}

// Excel caps worksheet names at 31 chars and forbids \ / ? * [ ] :
function safeSheetName(name, used) {
  let base = String(name || "Sheet").replace(/[\\/?*[\]:]/g, " ").trim().slice(0, 31) || "Sheet";
  let candidate = base;
  let suffix = 2;
  while (used.has(candidate)) {
    candidate = `${base.slice(0, 28)} ${suffix}`;
    suffix += 1;
  }
  used.add(candidate);
  return candidate;
}

// ---------------------------------------------------------------------------
// IMS Outward combined export
//
// The portal hands back one workbook per return period, each with the same
// seven sheets (Summary + six table sheets). Stacking them verbatim produced
// `periods x 7` sheets, which is unusable for a full-year view. Instead the
// periods are folded together: ONE sheet per section, with the period pushed
// into the first column, and ONE pivoted Summary sheet (period down the rows,
// section headings across the columns) instead of a Summary per period.
// ---------------------------------------------------------------------------

const IMS_MONTH_ABBR = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

// "012026" -> "202601" so periods sort chronologically, not lexically.
function imsPeriodSortKey(period) {
  const match = /^(\d{2})(\d{4})$/.exec(String(period || "").trim());
  return match ? `${match[2]}${match[1]}` : String(period || "");
}

// "012026" -> "Jan-2026"
function formatImsPeriodLabel(period) {
  const match = /^(\d{2})(\d{4})$/.exec(String(period || "").trim());
  if (!match) return String(period || "");
  const month = IMS_MONTH_ABBR[parseInt(match[1], 10) - 1];
  return month ? `${month}-${match[2]}` : String(period);
}

function sortImsPeriods(periods) {
  return (periods || []).slice().sort((a, b) => imsPeriodSortKey(a).localeCompare(imsPeriodSortKey(b)));
}

function imsSheetRows(sheet) {
  return XLSX.utils.sheet_to_json(sheet, { header: 1, defval: "", blankrows: true });
}

function isBlankImsRow(row) {
  return !row || !row.some((cell) => cell !== "" && cell !== null && cell !== undefined);
}

function imsRowFilledCount(row) {
  return (row || []).filter((cell) => cell !== "" && cell !== null && cell !== undefined).length;
}

// The portal prefixes every sheet with title/blank rows; the real header row is
// the widest row near the top. Scanning by width beats hardcoding row 5, which
// shifts whenever the portal adds a banner line.
function findImsHeaderRow(rows) {
  const limit = Math.min(rows.length, 12);
  let bestIndex = -1;
  let bestCount = 0;
  for (let i = 0; i < limit; i += 1) {
    const count = imsRowFilledCount(rows[i]);
    if (count > bestCount) {
      bestCount = count;
      bestIndex = i;
    }
  }
  return bestCount >= 2 ? bestIndex : -1;
}

// Nearest single-cell row above the header, e.g. "9A - Amended B2B Invoices".
function findImsSectionTitle(rows, headerIndex) {
  for (let i = headerIndex - 1; i >= 0; i -= 1) {
    if (imsRowFilledCount(rows[i]) === 1) {
      const cell = (rows[i] || []).find((v) => v !== "" && v !== null && v !== undefined);
      return String(cell || "").trim();
    }
  }
  return "";
}

function trimImsHeaders(headerRow) {
  const headers = (headerRow || []).map((v) => String(v === null || v === undefined ? "" : v).trim());
  let width = headers.length;
  while (width > 0 && headers[width - 1] === "") width -= 1;
  return headers.slice(0, width);
}

const IMS_PERIOD_COLUMN = "Period";

// Pivot: one row per period, one column per summary heading (S.no. order).
function buildImsCombinedSummarySheet(periodLabels, summaryByPeriod, headingOrder) {
  const headings = headingOrder.slice();
  const aoa = [["IMS SUMMARY - Universal view of B2B supplies reported in GSTR-1/1A/IFF"], [], [IMS_PERIOD_COLUMN, ...headings]];
  const totals = headings.map(() => 0);

  periodLabels.forEach((label) => {
    const counts = summaryByPeriod[label] || {};
    const row = [label];
    headings.forEach((heading, i) => {
      const raw = counts[heading];
      const value = raw === "" || raw === undefined || raw === null ? 0 : Number(raw);
      const safe = Number.isFinite(value) ? value : raw;
      if (Number.isFinite(value)) totals[i] += value;
      row.push(safe);
    });
    aoa.push(row);
  });

  if (periodLabels.length > 1) aoa.push(["Total", ...totals]);

  const sheet = XLSX.utils.aoa_to_sheet(aoa);
  sheet["!cols"] = [{ wch: 12 }].concat(headings.map(() => ({ wch: 34 })));
  sheet["!autofilter"] = { ref: XLSX.utils.encode_range({ s: { r: 2, c: 0 }, e: { r: 2 + periodLabels.length, c: headings.length } }) };
  sheet["!freeze"] = { xSplit: 1, ySplit: 3 };
  return sheet;
}

function buildImsCombinedSectionSheet(section) {
  const headers = [IMS_PERIOD_COLUMN, ...section.headers];
  const aoa = [[section.title || ""], [], headers].concat(section.rows);
  const sheet = XLSX.utils.aoa_to_sheet(aoa);
  sheet["!cols"] = headers.map((h, i) => ({ wch: i === 0 ? 12 : Math.min(Math.max(String(h).length + 2, 12), 40) }));
  sheet["!autofilter"] = {
    ref: XLSX.utils.encode_range({ s: { r: 2, c: 0 }, e: { r: 2 + section.rows.length, c: headers.length - 1 } }),
  };
  sheet["!freeze"] = { xSplit: 1, ySplit: 3 };
  return sheet;
}

// Folds every period's workbook into one sheet per section, period-first.
function combineImsWorkbooks(entries) {
  const ordered = (entries || []).slice().sort((a, b) => imsPeriodSortKey(a.period).localeCompare(imsPeriodSortKey(b.period)));

  const sections = new Map(); // sheetName -> { title, headers[], rows[][] }
  const summaryByPeriod = {}; // label -> { heading: count }
  const headingOrder = [];
  const periodLabels = [];

  ordered.forEach(({ period, workbook }) => {
    const label = formatImsPeriodLabel(period) || String(period || "");
    if (!periodLabels.includes(label)) periodLabels.push(label);

    (workbook.SheetNames || []).forEach((sheetName) => {
      const rows = imsSheetRows(workbook.Sheets[sheetName]);
      const headerIndex = findImsHeaderRow(rows);
      if (headerIndex < 0) return;

      const headers = trimImsHeaders(rows[headerIndex]);
      if (!headers.length) return;
      const dataRows = rows.slice(headerIndex + 1).filter((row) => !isBlankImsRow(row.slice(0, headers.length)));

      // Summary sheets collapse into a single pivot rather than one sheet each.
      if (/summary/i.test(sheetName)) {
        const bucket = summaryByPeriod[label] || (summaryByPeriod[label] = {});
        dataRows.forEach((row) => {
          const heading = String(row[1] === undefined ? "" : row[1]).trim();
          if (!heading) return;
          if (!headingOrder.includes(heading)) headingOrder.push(heading);
          bucket[heading] = row[2];
        });
        return;
      }

      let section = sections.get(sheetName);
      if (!section) {
        section = { title: findImsSectionTitle(rows, headerIndex) || sheetName, headers: headers.slice(), rows: [] };
        sections.set(sheetName, section);
      }

      // Match by header name, not position: a period that gains/loses a column
      // must not silently shift everything one cell to the left.
      const indexByHeader = new Map();
      headers.forEach((header, i) => {
        if (!indexByHeader.has(header)) indexByHeader.set(header, i);
      });
      headers.forEach((header) => {
        if (!section.headers.includes(header)) section.headers.push(header);
      });

      dataRows.forEach((row) => {
        const out = [label];
        section.headers.forEach((header) => {
          if (!indexByHeader.has(header)) {
            out.push("");
            return;
          }
          const value = row[indexByHeader.get(header)];
          out.push(value === undefined || value === null ? "" : value);
        });
        section.rows.push(out);
      });
    });
  });

  const out = XLSX.utils.book_new();
  const used = new Set();

  if (headingOrder.length) {
    XLSX.utils.book_append_sheet(out, buildImsCombinedSummarySheet(periodLabels, summaryByPeriod, headingOrder), safeSheetName("Summary", used));
  }
  sections.forEach((section, sheetName) => {
    XLSX.utils.book_append_sheet(out, buildImsCombinedSectionSheet(section), safeSheetName(sheetName, used));
  });

  if (!out.SheetNames.length) throw new Error("The IMS workbooks contained no sheets");
  return out;
}

function workbookToBlob(workbook) {
  const buffer = XLSX.write(workbook, { bookType: "xlsx", type: "array" });
  return new Blob([buffer], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" });
}

// Fallback only: turn a JSON IMS document into { sheetName: rows[] }.
function imsTablesFromJsonFile(file, context) {
  return imsTablesFromJsonText(file.text, context);
}

// Flattens scalar + nested-object fields of one record; nested arrays are left
// for collectImsTables to promote into their own sheet.
function flattenImsRecord(record) {
  const out = {};
  const walk = (value, prefix) => {
    if (value === null || value === undefined) return;
    if (Array.isArray(value)) return;
    if (typeof value === "object") {
      Object.keys(value).forEach((key) => walk(value[key], prefix ? `${prefix}_${key}` : key));
      return;
    }
    out[prefix] = value;
  };
  Object.keys(record || {}).forEach((key) => walk(record[key], key));
  return out;
}

const isPlainRecord = (value) => value && typeof value === "object" && !Array.isArray(value);

// A line-item sheet is useless if you can't tell which supplier and invoice a
// line belongs to. Carry the parent's identifying scalars down into the child
// rows rather than a bare positional index.
const IMS_IDENTITY_KEYS = [
  "ctin", "trdnm", "inum", "idt", "dt", "val", "pos", "rev", "typ",
  "nt_num", "nt_dt", "ntty", "srctyp", "irn", "rtnprd", "supprd",
];

function imsParentContext(record) {
  const flat = flattenImsRecord(record);
  const carried = {};
  IMS_IDENTITY_KEYS.forEach((key) => {
    if (Object.prototype.hasOwnProperty.call(flat, key)) carried[key] = flat[key];
  });
  return carried;
}

// Depth-first walk collecting every array-of-objects into tables[path].
function collectImsTables(node, path, tables, context) {
  if (Array.isArray(node)) {
    if (!node.length || !node.some(isPlainRecord)) return;
    const key = path || "records";
    if (!tables[key]) tables[key] = [];
    node.forEach((item) => {
      if (!isPlainRecord(item)) {
        tables[key].push({ ...context, value: item });
        return;
      }
      const parentRow = tables[key].length + 1;
      tables[key].push({ ...context, row_no: parentRow, ...flattenImsRecord(item) });
      const childContext = { ...context, ...imsParentContext(item) };
      Object.keys(item).forEach((childKey) => {
        if (!Array.isArray(item[childKey])) return;
        collectImsTables(item[childKey], `${key}.${childKey}`, tables, childContext);
      });
    });
    return;
  }
  if (isPlainRecord(node)) {
    Object.keys(node).forEach((key) => {
      collectImsTables(node[key], path ? `${path}.${key}` : key, tables, context);
    });
  }
}

// Worksheet names are capped at 31 chars and may not contain \ / ? * [ ] :
function imsSheetNameFor(path, used) {
  const segments = String(path).split(".").filter(Boolean);
  let base = segments.slice(-2).join(" ") || "Data";
  base = base.replace(/[\\/?*[\]:]/g, " ").trim().slice(0, 28) || "Data";
  let name = base;
  let suffix = 2;
  while (used.has(name)) {
    name = `${base.slice(0, 26)} ${suffix}`;
    suffix += 1;
  }
  used.add(name);
  return name;
}

function imsTablesFromJsonText(text, context) {
  let payload;
  try {
    payload = JSON.parse(text);
  } catch (e) {
    // Show printable characters as-is and everything else as hex, so a binary
    // body is recognisable rather than mojibake.
    const preview = Array.from(String(text || "").trim().slice(0, 24))
      .map((ch) => {
        const code = ch.charCodeAt(0);
        return code >= 0x20 && code < 0x7f ? ch : `\\x${code.toString(16).padStart(2, "0")}`;
      })
      .join("");
    throw new Error(`The IMS file is neither an Excel workbook nor valid JSON (starts with: ${preview})`);
  }
  const tables = {};
  collectImsTables(payload, "", tables, context);
  return { tables, kind: "json", payload };
}

// Merges per-period table maps into one, so a twelve-month IMS Outward pull
// lands as one sheet per section with report_period as the leading column,
// rather than twelve near-identical sheets.
function mergeImsTables(tableMaps) {
  const merged = {};
  (tableMaps || []).forEach((tables) => {
    Object.keys(tables || {}).forEach((name) => {
      if (!merged[name]) merged[name] = [];
      merged[name] = merged[name].concat(tables[name]);
    });
  });
  return merged;
}

function buildImsWorkbookXmlFromTables(tables) {
  const used = new Set(["Summary"]);
  const names = Object.keys(tables).sort();
  const populated = names.filter((name) => (tables[name] || []).length);

  const tocRows = names.map((name) => ({ section: name, rows: (tables[name] || []).length }));
  const sheets = populated
    .map((name) => {
      const rows = tables[name];
      const preferred = ["report_period", "row_no", "ctin", "trdnm", "inum", "dt"].filter((column) =>
        rows.some((row) => Object.prototype.hasOwnProperty.call(row, column)),
      );
      return buildSpreadsheetWorksheet(imsSheetNameFor(name, used), rows, preferred, { autoFilter: true });
    })
    .join("\n ");

  return `<?xml version="1.0"?>
<Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet"
 xmlns:o="urn:schemas-microsoft-com:office:office"
 xmlns:x="urn:schemas-microsoft-com:office:excel"
 xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"
 xmlns:html="http://www.w3.org/TR/REC-html40">
 <Styles>
  <Style ss:ID="Header">
   <Font ss:Bold="1"/>
   <Interior ss:Color="#D9E8FB" ss:Pattern="Solid"/>
  </Style>
 </Styles>
 ${buildSpreadsheetWorksheet("Summary", tocRows, ["section", "rows"])}
 ${sheets}
</Workbook>`;
}

async function buildImsExcelBlob(tables) {
  return buildXlsxBlobFromWorkbookXml(buildImsWorkbookXmlFromTables(tables));
}

// ── IMS Outward: one combined file for many periods ─────────────────
// "Download All" used to loop downloadOther() and drop one JSON per period.
// The portal exposes a per-period file, so club them client-side into a single
// keyed JSON. Get All uses the same builder, so both paths now behave alike.
function buildImsOutRequestUrl(cfg, period) {
  return withParams(cfg.base, [
    ["rtnTyp", "R1"],
    ["section", "ALLOSP"],
    ["viewTyp", "UNI"],
    ["rtnPrd", period || ""],
  ]);
}

async function fetchImsOutPeriodFile(cfg, period) {
  const requestUrl = buildImsOutRequestUrl(cfg, period);
  addActivity(`${cfg.display} request: ${requestUrl}`, "text-muted");
  const msg = await portalGet(requestUrl);
  if (!msg || !msg.status || !msg.response) {
    throw new Error((msg && msg.error) || (msg && msg.statusCode ? `HTTP ${msg.statusCode}` : "Failed"));
  }
  let parsed = null;
  try { parsed = JSON.parse(msg.response); } catch (e) { parsed = null; }
  const finalUrl = getImsOutDownloadUrl(parsed);
  if (!finalUrl) {
    throw new Error(getOtherResponseMessage(parsed, "No file url"));
  }
  return fetchImsFile(finalUrl);
}

// Resolves the IMS Inward file (no period) and returns it.
async function fetchImsInwardFile(cfg) {
  await ensureConnectedToHost("return.gst.gov.in");
  addActivity(`${cfg.display} request: ${cfg.base}`, "text-muted");
  const msg = await portalGet(cfg.base);
  if (!msg || !msg.status || !msg.response) {
    throw new Error((msg && msg.error) || (msg && msg.statusCode ? `HTTP ${msg.statusCode}` : "Failed"));
  }
  let parsed = null;
  try { parsed = JSON.parse(msg.response); } catch (e) { parsed = null; }
  const finalUrl = getImsOutDownloadUrl(parsed);
  if (!finalUrl) throw new Error(getOtherResponseMessage(parsed, "No file url"));
  return fetchImsFile(finalUrl);
}

function imsInNorm(value) { return String(value == null ? "" : value).trim().toUpperCase().replace(/[^A-Z0-9]/g, ""); }
function imsInDate(value) {
  if (typeof value === "number" && typeof XLSX !== "undefined" && XLSX.SSF) {
    const d=XLSX.SSF.parse_date_code(value); if(d)return `${String(d.d).padStart(2,"0")}${String(d.m).padStart(2,"0")}${d.y}`;
  }
  const digits=String(value == null ? "" : value).replace(/[^0-9]/g, "");
  if(digits.length===8 && /^\d{4}/.test(digits))return digits.slice(6,8)+digits.slice(4,6)+digits.slice(0,4);
  return digits;
}
function imsInDocClass(value) {
  const v=imsInNorm(value); if(v==="C"||/CREDIT|CRNOTE|CDNR|CDN/.test(v))return "CN"; if(v==="D"||/DEBIT|DRNOTE/.test(v))return "DN"; return "INV";
}
function imsInAction(value) {
  const v=imsInNorm(value);
  if(v==="A"||v.includes("ACCEPT"))return "Accepted";
  if(v==="R"||v.includes("REJECT"))return "Rejected";
  if(v==="P"||v.includes("PENDING"))return "Pending";
  if(v==="N"||v.includes("NOACTION")||v.includes("NOACTIONTAKEN"))return "No Action";
  return String(value||"").trim() || "Not Found";
}
function imsHeaderField(value) {
  const h=imsInNorm(value);
  if(/GSTIN.*SUPPLIER|SUPPLIER.*GSTIN|^CTIN$/.test(h))return "gstin";
  if(/INVOICE.*(NUMBER|NO)|DOCUMENT.*(NUMBER|NO)|DOCNO|NOTENUMBER|NOTENO/.test(h))return "docno";
  if(/INVOICE.*DATE|DOCUMENT.*DATE|DOCDATE|NOTEDATE/.test(h))return "docdate";
  if(/DOCUMENT.*TYPE|DOCTYPE|INVOICETYPE|NOTETYPE/.test(h))return "doctype";
  if(/ACTION.*RECIPIENT|RECIPIENT.*ACTION|RECIPIENT.*RESPONSE|IMS.*RESPONSE|IMSACTION|ACTIONTAKEN|^ACTION$/.test(h))return "action";
  return "";
}
function imsRecordsFromRows(rows, sheetName) {
  let best={index:-1,fields:[],score:0};
  for(let i=0;i<Math.min(rows.length,30);i++) {
    const fields=(rows[i]||[]).map(imsHeaderField), score=new Set(fields.filter(Boolean)).size;
    if(score>best.score)best={index:i,fields,score};
  }
  if(best.score<3||!best.fields.includes("action")||!best.fields.includes("docno"))return [];
  return rows.slice(best.index+1).flatMap(row=>{
    const rec={sheet:sheetName}; best.fields.forEach((field,i)=>{if(field&&!rec[field])rec[field]=row[i];});
    if(!rec.docno||!rec.action)return [];
    rec.action=imsInAction(rec.action); rec.gstin=String(rec.gstin||"").trim(); rec.docno=String(rec.docno).trim(); rec.docdate=rec.docdate||""; rec.doctype=rec.doctype||sheetName;
    return [rec];
  });
}
function imsBuildClassification(records, available, error) {
  const clean=[];
  const seen=new Set();
  (records||[]).forEach(r=>{const sig=[imsInNorm(r.gstin),imsInNorm(r.docno),imsInDate(r.docdate),imsInDocClass(r.doctype),r.action].join('|');if(!seen.has(sig)){seen.add(sig);clean.push(r);}});
  return {available:!!available,error:error||"",records:clean};
}
async function fetchImsInwardClassification(cfg) {
  try {
    const file=await fetchImsInwardFile(cfg);
    let records=[];
    if(file.kind==="xlsx") {
      const wb=XLSX.read(file.bytes,{type:"array",cellDates:false});
      wb.SheetNames.forEach(name=>{records.push(...imsRecordsFromRows(XLSX.utils.sheet_to_json(wb.Sheets[name],{header:1,defval:""}),name));});
    } else {
      const parsed=JSON.parse(file.text||"{}");
      const visit=(node,name)=>{if(Array.isArray(node)){if(node.length&&node[0]&&typeof node[0]==="object"&&!Array.isArray(node[0])){const headers=[...new Set(node.flatMap(x=>Object.keys(x||{})))];records.push(...imsRecordsFromRows([headers,...node.map(x=>headers.map(h=>x&&x[h]))],name));}else node.forEach(x=>visit(x,name));}else if(node&&typeof node==="object")Object.entries(node).forEach(([k,v])=>visit(v,k));};
      visit(parsed,"IMS");
    }
    return imsBuildClassification(records,true,records.length?"":"IMS file was received, but no action rows were recognised.");
  } catch(err) { return imsBuildClassification([],false,err&&err.message?err.message:String(err)); }
}
function classifyGstr2bWithIms(ims,gstin,docno,docdate,doctype) {
  const key=[imsInNorm(gstin),imsInNorm(docno),imsInDate(docdate),imsInDocClass(doctype)].join('|');
  if(!ims||!ims.available)return {action:"IMS unavailable",match:"Not checked",include:"Yes",key};
  const sameDoc=(ims.records||[]).filter(r=>imsInNorm(r.gstin)===imsInNorm(gstin)&&imsInNorm(r.docno)===imsInNorm(docno));
  let found=sameDoc.filter(r=>imsInDate(r.docdate)===imsInDate(docdate)&&imsInDocClass(r.doctype)===imsInDocClass(doctype));
  if(!found.length&&sameDoc.length===1)found=sameDoc;
  const actions=[...new Set(found.map(r=>r.action))];
  if(found.length>1&&actions.length>1)return {action:"Ambiguous",match:"Review - conflicting IMS actions",include:"Yes",key};
  if(!found.length)return {action:"Not Found",match:"Not matched",include:"Yes",key};
  const action=actions[0]||"Not Found";
  if(action==="Accepted")return {action,match:"Matched - IMS Accepted",include:"Yes",key};
  if(action==="Rejected")return {action,match:"Excluded - IMS Rejected",include:"No",key};
  return {action,match:`Review - IMS ${action}`,include:"Yes",key};
}

// IMS Inward is a single portal workbook — hand it back byte-for-byte.
async function buildImsInwardExcelBlob(cfg) {
  const file = await fetchImsInwardFile(cfg);
  if (file.kind === "xlsx") {
    return new Blob([file.bytes], {
      type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    });
  }
  const { tables } = imsTablesFromJsonFile(file, {});
  return buildImsExcelBlob(tables);
}

// Shared handler for the IMS Outward "Download All JSON" / "Download All Excel"
// buttons — same combined multi-period export, two serialisations.
async function runImsOutwardCombined(cfg, rows, button, format, restoreLabel) {
  const original = button.textContent;
  button.disabled = true;
  button.textContent = format === "excel" ? "Preparing..." : "Downloading...";
  try {
    const { ok, total, filename } = await downloadImsOutwardCombined(cfg, rows.map((p) => p.value), format);
    addActivity(`IMS Outward combined: ${ok}/${total} periods → ${filename}`, "text-success");
  } catch (e) {
    addActivity(`IMS Outward combined failed: ${e && e.message ? e.message : e}`, "text-danger");
  } finally {
    button.disabled = false;
    button.textContent = restoreLabel || original;
  }
}

async function downloadImsInwardExcel(cfg) {
  const statusCell = getElement("other-status");
  const button = getElement("btn-ims-in-excel");
  if (button) {
    button.disabled = true;
    button.textContent = "Preparing...";
  }
  if (statusCell) statusCell.innerHTML = pill("Working", "warning");
  try {
    const stamp = moment().format("YYYYMMDD");
    const blob = await buildImsInwardExcelBlob(cfg);
    await downloadBlobAs(blob, `${session.gstin || "GSTIN"}_${cfg.fileNameCode}_${stamp}.xlsx`);
    if (statusCell) statusCell.innerHTML = pill("Downloaded", "success");
  } catch (e) {
    const why = e && e.message ? e.message : "Failed";
    addActivity(`${cfg.display} Excel failed: ${why}`, "text-danger");
    if (statusCell) statusCell.innerHTML = pill(why, "danger");
  } finally {
    if (button) {
      button.disabled = false;
      button.textContent = "Excel";
    }
  }
}

// ---------------------------------------------------------------------------
// NEO-GST Reco Stage 3 — GSTR-1 vs IMS Outward (invoice-level, B2B)
//
// IMS Outward sheets are named by the portal's own "Table N" labels, which
// aren't stable field names to hardcode against. Instead this scans the
// *already-combined* workbook's sheets for one whose header row (row 3 of
// buildImsCombinedSectionSheet's layout: title, blank, headers) contains a
// GSTIN-like and an Invoice/Document-Number-like column — that's the B2B
// invoice table regardless of what the portal happened to title it this
// season. Column positions for taxable value / IGST / CGST / SGST / Cess are
// found the same way, by header text, and left blank (not zero) if a season's
// export doesn't carry them, so an absent column reads as "not available"
// rather than a false zero difference.
//
// NOTE: this one hasn't been checked against a real portal IMS Outward file
// (no sample was available while building this) — the other three Recos in
// this batch were verified against realistic mock payloads matching known
// JSON schemas. If the header detection below misses on a real export, the
// fix is almost certainly just widening the regexes, not the matching logic.
// ---------------------------------------------------------------------------
function findImsOutwardInvoiceSection(workbook) {
  let best = null;
  (workbook.SheetNames || []).forEach((name) => {
    if (/summary/i.test(name)) return;
    const rows = XLSX.utils.sheet_to_json(workbook.Sheets[name], { header: 1, defval: "" });
    if (rows.length < 4) return;
    const headers = (rows[2] || []).map((h) => String(h == null ? "" : h));
    const findCol = (re) => headers.findIndex((h) => re.test(h));
    const gstinIdx = findCol(/gstin/i);
    const invIdx = findCol(/invoice.*(no|num)|note.*(no|num)|document.*(no|num)/i);
    if (gstinIdx < 0 || invIdx < 0) return;
    const candidate = {
      name, headers, dataRows: rows.slice(3),
      gstinIdx, invIdx,
      taxableIdx: findCol(/taxable/i),
      igstIdx: findCol(/integrated/i),
      cgstIdx: findCol(/central/i),
      sgstIdx: findCol(/state/i),
      cessIdx: findCol(/cess/i),
    };
    if (!best || candidate.dataRows.length > best.dataRows.length) best = candidate;
  });
  return best;
}

function extractImsOutwardInvoiceTotals(workbook) {
  const section = findImsOutwardInvoiceSection(workbook);
  const out = new Map(); // "period|gstin|inum" -> totals
  if (!section) return { map: out, sheetName: null };
  const num = (v) => { const n = Number(v); return Number.isFinite(n) ? n : 0; };
  section.dataRows.forEach((row) => {
    const period = row[0]; // IMS_PERIOD_COLUMN is always prepended as column 0
    const gstin = String(row[section.gstinIdx] || "").trim().toUpperCase();
    const inum = String(row[section.invIdx] || "").trim().toUpperCase().replace(/[^A-Z0-9]/g, "");
    if (!gstin || !inum) return;
    const key = `${period}|${gstin}|${inum}`;
    const existing = out.get(key) || {
      period, gstin: row[section.gstinIdx], inum: row[section.invIdx],
      taxable: 0, igst: 0, cgst: 0, sgst: 0, cess: 0,
      hasTaxable: section.taxableIdx >= 0, hasTax: section.igstIdx >= 0 || section.cgstIdx >= 0,
    };
    if (section.taxableIdx >= 0) existing.taxable += num(row[section.taxableIdx]);
    if (section.igstIdx >= 0) existing.igst += num(row[section.igstIdx]);
    if (section.cgstIdx >= 0) existing.cgst += num(row[section.cgstIdx]);
    if (section.sgstIdx >= 0) existing.sgst += num(row[section.sgstIdx]);
    if (section.cessIdx >= 0) existing.cess += num(row[section.cessIdx]);
    out.set(key, existing);
  });
  return { map: out, sheetName: section.name };
}

async function extractGstr1B2BInvoiceTotalsForPeriods(periods) {
  const out = new Map(); // "period|gstin|inum" -> totals
  for (const period of periods) {
    // eslint-disable-next-line no-await-in-loop
    let payload = null;
    try {
      // eslint-disable-next-line no-await-in-loop
      payload = await fetchGstr1JsonPayload({ value: period });
    } catch (err) {
      payload = null;
    }
    if (!payload) continue;
    const periodLabel = formatImsPeriodLabel(period) || String(period);
    const root = getGstr1SectionSourceData(payload);
    const b2bArr = Array.isArray(root && root.b2b) ? root.b2b : [];
    b2bArr.forEach((supplier) => {
      const gstin = String((supplier && (supplier.ctin || supplier.gstin)) || "").trim().toUpperCase();
      (Array.isArray(supplier && supplier.inv) ? supplier.inv : []).forEach((inv) => {
        const inum = String((inv && inv.inum) || "").trim().toUpperCase().replace(/[^A-Z0-9]/g, "");
        if (!gstin || !inum) return;
        const key = `${periodLabel}|${gstin}|${inum}`;
        const existing = out.get(key) || { period: periodLabel, gstin: supplier.ctin || supplier.gstin, inum: inv.inum, taxable: 0, igst: 0, cgst: 0, sgst: 0, cess: 0 };
        const items = Array.isArray(inv.itms) && inv.itms.length ? inv.itms : [null];
        items.forEach((item) => {
          const d = (item && (item.itm_det || item)) || {};
          existing.taxable += asNumber(d.txval); existing.igst += asNumber(d.iamt);
          existing.cgst += asNumber(d.camt); existing.sgst += asNumber(d.samt); existing.cess += asNumber(d.csamt);
        });
        out.set(key, existing);
      });
    });
  }
  return out;
}

function buildReco1VsImsSheet(mapG1, mapIms, imsSheetName) {
  const allKeys = new Set([...mapG1.keys(), ...mapIms.keys()]);
  const fmt = (v) => Math.round((v || 0) * 100) / 100;
  const rows = [];
  let matched = 0, onlyG1 = 0, onlyIms = 0, mismatch = 0;
  allKeys.forEach((key) => {
    const a = mapG1.get(key); const b = mapIms.get(key);
    let status;
    if (a && b) {
      const compareTaxable = b.hasTaxable !== false;
      const compareTax = b.hasTax !== false;
      const diff = (compareTaxable ? Math.abs(a.taxable - b.taxable) : 0) + (compareTax ? Math.abs(a.igst - b.igst) + Math.abs(a.cgst - b.cgst) + Math.abs(a.sgst - b.sgst) + Math.abs(a.cess - b.cess) : 0);
      status = diff <= 1 ? "Matched" : "Value Mismatch";
      if (status === "Matched") matched += 1; else mismatch += 1;
    } else if (a) { status = "Only in GSTR-1"; onlyG1 += 1; }
    else { status = "Only in IMS Outward"; onlyIms += 1; }
    const ref = a || b;
    rows.push({
      period: ref.period, gstin: ref.gstin, inum: ref.inum, status,
      g1_taxable: a ? fmt(a.taxable) : "", g1_igst: a ? fmt(a.igst) : "", g1_cgst: a ? fmt(a.cgst) : "", g1_sgst: a ? fmt(a.sgst) : "", g1_cess: a ? fmt(a.cess) : "",
      ims_taxable: b && b.hasTaxable !== false ? fmt(b.taxable) : (b ? "n/a" : ""),
      ims_igst: b && b.hasTax !== false ? fmt(b.igst) : (b ? "n/a" : ""),
      ims_cgst: b && b.hasTax !== false ? fmt(b.cgst) : (b ? "n/a" : ""),
      ims_sgst: b && b.hasTax !== false ? fmt(b.sgst) : (b ? "n/a" : ""),
      ims_cess: b && b.hasTax !== false ? fmt(b.cess) : (b ? "n/a" : ""),
    });
  });
  const order = { "Value Mismatch": 0, "Only in GSTR-1": 1, "Only in IMS Outward": 2, Matched: 3 };
  rows.sort((x, y) => (order[x.status] - order[y.status]) || String(x.period).localeCompare(String(y.period)) || String(x.gstin).localeCompare(String(y.gstin)));

  const NAVY = "1F3864", LBLUE = "D9E2F3", WHITE = "FFFFFF", GREY = "F2F2F2";
  const bd = { style: "thin", color: { rgb: "8EA9DB" } };
  const border = { top: bd, bottom: bd, left: bd, right: bd };
  const titleStyle = { font: { bold: true, sz: 14, color: { rgb: WHITE } }, fill: { patternType: "solid", fgColor: { rgb: NAVY } }, alignment: { horizontal: "center", vertical: "center" } };
  const summaryStyle = { font: { bold: true, sz: 10 }, fill: { patternType: "solid", fgColor: { rgb: GREY } }, border };
  const headerStyle = { font: { bold: true, sz: 9, color: { rgb: "1F3864" } }, fill: { patternType: "solid", fgColor: { rgb: LBLUE } }, alignment: { horizontal: "center", vertical: "center", wrapText: true }, border };
  const cellStyle = { font: { sz: 9 }, border };
  const numStyle = { font: { sz: 9 }, alignment: { horizontal: "right" }, numFmt: "#,##0;[Red](#,##0)", border };
  const statusFill = { Matched: "E2EFDA", "Value Mismatch": "FCE4D6", "Only in GSTR-1": "FFF2CC", "Only in IMS Outward": "FFF2CC" };

  const headers = ["Period", "GSTIN", "Invoice/Doc No.", "Status", "GSTR-1 Taxable", "GSTR-1 IGST", "GSTR-1 CGST", "GSTR-1 SGST", "GSTR-1 Cess", "IMS Taxable", "IMS IGST", "IMS CGST", "IMS SGST", "IMS Cess"];
  const aoa = [
    ["Reco & Summ \u2014 GSTR-1 vs IMS Outward (B2B, invoice-level)"],
    [`Matched: ${matched}   |   Value Mismatch: ${mismatch}   |   Only in GSTR-1: ${onlyG1}   |   Only in IMS Outward: ${onlyIms}` + (imsSheetName ? `   |   IMS source sheet: "${imsSheetName}"` : "   |   No matching IMS invoice sheet found")],
    [],
    headers,
  ];
  rows.forEach((r) => aoa.push([r.period, r.gstin, r.inum, r.status, r.g1_taxable, r.g1_igst, r.g1_cgst, r.g1_sgst, r.g1_cess, r.ims_taxable, r.ims_igst, r.ims_cgst, r.ims_sgst, r.ims_cess]));

  const ws = XLSX.utils.aoa_to_sheet(aoa);
  ws["!merges"] = [{ s: { r: 0, c: 0 }, e: { r: 0, c: headers.length - 1 } }, { s: { r: 1, c: 0 }, e: { r: 1, c: headers.length - 1 } }];
  ws["!cols"] = [{ wch: 10 }, { wch: 18 }, { wch: 16 }, { wch: 16 }].concat(Array.from({ length: headers.length - 4 }, () => ({ wch: 12 })));
  ws["!autofilter"] = { ref: XLSX.utils.encode_range({ s: { r: 3, c: 0 }, e: { r: 3 + rows.length, c: headers.length - 1 } }) };
  ws["!freeze"] = { xSplit: 0, ySplit: 4 };
  const setStyle = (r, c, style) => { const ref = XLSX.utils.encode_cell({ r, c }); if (!ws[ref]) ws[ref] = { t: "s", v: "" }; ws[ref].s = style; };
  for (let c = 0; c < headers.length; c += 1) { setStyle(0, c, titleStyle); setStyle(1, c, summaryStyle); setStyle(3, c, headerStyle); }
  rows.forEach((r, i) => {
    const rowIdx = 4 + i;
    for (let c = 0; c < headers.length; c += 1) {
      const isNum = c >= 4;
      const base = isNum ? numStyle : cellStyle;
      const fillColor = statusFill[r.status];
      setStyle(rowIdx, c, fillColor ? { ...base, fill: { patternType: "solid", fgColor: { rgb: fillColor } } } : base);
    }
  });
  return ws;
}

async function downloadImsOutwardCombined(cfg, periodValues, format) {
  await ensureConnectedToHost("return.gst.gov.in");
  const periods = (periodValues || []).filter(Boolean);
  if (!periods.length) throw new Error("No periods selected");

  const files = {};
  const failures = [];

  for (const period of periods) {
    const statusCell = getElement(`info-${period}`);
    if (statusCell) statusCell.innerHTML = pill("Working", "warning");
    try {
      files[period] = await fetchImsOutPeriodFile(cfg, period);
      if (statusCell) statusCell.innerHTML = pill("Included", "success");
    } catch (e) {
      const why = e && e.message ? e.message : "Failed";
      failures.push({ period, error: why });
      if (statusCell) statusCell.innerHTML = pill(why, "danger");
    }
  }

  const sorted = sortImsPeriods(periods);
  const okPeriods = sorted.filter((period) => files[period]);
  const okCount = okPeriods.length;
  if (!okCount) {
    throw new Error(failures.length ? failures[failures.length - 1].error : "Nothing downloaded");
  }

  const stem = `${session.gstin || "GSTIN"}_${cfg.fileNameCode}_${sorted[0]}_${sorted[sorted.length - 1]}`;
  const allWorkbooks = okPeriods.every((period) => files[period].kind === "xlsx");

  if (format === "excel") {
    if (allWorkbooks) {
      // Every period is a portal workbook: merge the sheets verbatim so the
      // portal's own layout is preserved, one sheet per period per section.
      const entries = okPeriods.map((period) => ({ period, workbook: readImsWorkbook(files[period].bytes) }));
      const combined = combineImsWorkbooks(entries);
      // NEO-GST Reco Stage 3: best-effort GSTR-1 vs IMS Outward reco, appended
      // as an extra sheet. Never blocks the base IMS download on failure.
      try {
        const { map: imsMap, sheetName: imsSheetName } = extractImsOutwardInvoiceTotals(combined);
        const g1Map = await extractGstr1B2BInvoiceTotalsForPeriods(okPeriods);
        const recoWs = buildReco1VsImsSheet(g1Map, imsMap, imsSheetName);
        combined.SheetNames.splice(0, 0, "Reco");
        combined.Sheets.Reco = recoWs;
        if (!combined.Workbook) combined.Workbook = {};
        combined.Workbook.Sheets = (combined.SheetNames || []).map((nm) => (nm === "Reco" ? { Hidden: 0 } : { Hidden: 0 }));
      } catch (err) {
        // leave the combined workbook exactly as it was
      }
      await downloadBlobAs(workbookToBlob(combined), `${stem}.xlsx`);
      return { ok: okCount, total: periods.length, failures, filename: `${stem}.xlsx` };
    }
    const merged = mergeImsTables(
      okPeriods.map((period) => imsTablesFromJsonFile(files[period], { report_period: period }).tables),
    );
    await downloadBlobAs(await buildImsExcelBlob(merged), `${stem}.xlsx`);
    return { ok: okCount, total: periods.length, failures, filename: `${stem}.xlsx` };
  }

  // JSON mode. The portal file is a workbook, so there is no original JSON to
  // hand back; emit each sheet as an array of rows instead of pretending.
  const sections = {};
  okPeriods.forEach((period) => {
    if (files[period].kind === "json") {
      const { tables } = imsTablesFromJsonFile(files[period], { report_period: period });
      Object.keys(tables).forEach((name) => {
        sections[name] = (sections[name] || []).concat(tables[name]);
      });
      return;
    }
    const workbook = readImsWorkbook(files[period].bytes);
    const label = formatImsPeriodLabel(period) || String(period);
    (workbook.SheetNames || []).forEach((sheetName) => {
      const rows = XLSX.utils.sheet_to_json(workbook.Sheets[sheetName], { header: 1, defval: "", blankrows: false });
      const headerIndex = findImsHeaderRow(rows);
      if (headerIndex < 0) return;
      const headers = trimImsHeaders(rows[headerIndex]);
      const bucket = sections[sheetName] || (sections[sheetName] = []);
      if (!bucket.length) bucket.push([IMS_PERIOD_COLUMN, ...headers]);
      rows
        .slice(headerIndex + 1)
        .filter((row) => !isBlankImsRow(row.slice(0, headers.length)))
        .forEach((row) => bucket.push([label, ...headers.map((h, i) => (row[i] === undefined ? "" : row[i]))]));
    });
  });

  const combined = {
    gstin: session.gstin || "",
    fileType: cfg.fileNameCode,
    generatedAt: moment().format("YYYY-MM-DD HH:mm:ss"),
    periods: okPeriods,
    sections,
  };
  if (failures.length) combined.failures = failures;

  const blobUrl = URL.createObjectURL(
    new Blob([JSON.stringify(combined, null, 2)], { type: "application/json" }),
  );
  try {
    await downloadAs(blobUrl, `${stem}.json`);
  } finally {
    setTimeout(() => { try { URL.revokeObjectURL(blobUrl); } catch (e) {} }, 60000);
  }
  return { ok: okCount, total: periods.length, failures, filename: `${stem}.json` };
}

async function generateOther(cfg, period) {
  const statusCell =
    cfg.key === "IMS_OUT" ? getElement(`info-${period || ""}`) || getElement("other-status") : getElement("other-status");

  if (statusCell) statusCell.innerHTML = pill("Generating...", "warning");

  try {
    if (cfg.key !== "IMS_OUT") {
      if (statusCell) statusCell.innerHTML = pill("Unsupported", "danger");
      return;
    }

    await ensureConnectedToHost("return.gst.gov.in");
    const requestUrl = withParams(cfg.generateBase, [
      ["rtnTyp", "R1"],
      ["section", "ALLOSP"],
      ["viewTyp", "UNI"],
      ["rtnPrd", period || ""],
    ]);
    addActivity(`${cfg.display} generate request: ${requestUrl}`, "text-muted");
    const msg = await processAsync({ request: "get", url: requestUrl });
    if (!msg.status) {
      throw new Error(msg.statusCode ? `HTTP ${msg.statusCode}` : "Generate failed");
    }

    let parsed = null;
    try { parsed = JSON.parse(msg.response); } catch (e) { parsed = null; }

    const successText = getOtherResponseMessage(parsed, "Generated");
    if (
      parsed &&
      (
        parsed.status === 1 ||
        parsed.status === "1" ||
        (parsed.data && (parsed.data.status === 1 || parsed.data.status === "1"))
      )
    ) {
      if (statusCell) statusCell.innerHTML = pill(successText, "success");
    } else {
      if (statusCell) statusCell.innerHTML = pill(successText, "warning");
    }
  } catch (e) {
    if (statusCell) statusCell.innerHTML = pill(e && e.message ? e.message : "Failed", "danger");
  }
}

// Annual returns (GSTR-9 / GSTR-9C)

async function updateWorkspaceForAnnualReturn() {
  const divStatus = getElement("returnStatus");
  divStatus.textContent = `Getting ${session.return.display} status...`;

  let years = [];
  const dropdownMsg = await processAsync({
    request: "get",
    url: gstn.annualDropdown(),
  });
  if (dropdownMsg.status) {
    years = extractAnnualYearsFromDropdownResponse(dropdownMsg.response);
  }
  if (!years.length) {
    const currentFyStart = getCurrentFinancialYearStart();
    for (let fy = currentFyStart; fy >= 2016; fy--) years.push(fy);
  }

  let rowsHtml = "";
  years.forEach((fy) => {
    rowsHtml += `<tr>
      <td class="align-middle">${makeFinancialYearLabel(fy)}</td>
      <td class="align-middle"><div id="annual-info-${fy}"><div class="spinner-border spinner-border-sm text-primary" role="status"><span class="sr-only">Loading...</span></div></div></td>
      <td class="align-middle"><button type="button" class="btn btn-warning btn-sm" id="btn-annual-generate-${fy}">Generate</button></td>
      <td class="align-middle"><button type="button" class="btn btn-success btn-sm" id="btn-annual-json-${fy}" hidden>JSON</button></td>
      <td class="align-middle"><button type="button" class="btn btn-primary btn-sm" id="btn-annual-excel-${fy}" hidden>Excel</button></td>
    </tr>`;
  });

  divStatus.innerHTML = `<div class="row mb-2"><div class="col px-0 text-right"><div class="btn-group btn-group-sm float-right mr-2" role="group"><button type="button" class="btn btn-warning" id="btn-annual-generate-all"><strong>Generate All</strong></button></div></div></div><div class="row"><table class="table table-bordered table-sm table-status"><tr><th>F.Y</th><th>Status</th><th>Generate</th><th>JSON</th><th>Excel</th></tr>${rowsHtml}</table></div>`;

  const btnGenAll = getElement("btn-annual-generate-all");
  if (btnGenAll) {
    btnGenAll.onclick = function (evt) {
      reportButtonClicked(evt);
      generateAllAnnual();
    };
  }

  await Promise.all(years.map((fy) => updateAnnualRow(fy)));
}

async function updateAnnualRow(fy) {
  const infoCell = getElement(`annual-info-${fy}`);
  const btnGenerate = getElement(`btn-annual-generate-${fy}`);
  const btnJson = getElement(`btn-annual-json-${fy}`);
  const btnExcel = getElement(`btn-annual-excel-${fy}`);
  const period = { value: annualPeriodValueFromFy(fy), year: makeFinancialYearLabel(fy) };

  const roleMsg = await processAsync({
    request: "get",
    url: gstn.annualrolestatus(fy),
  });

  if (!roleMsg.status) {
    infoCell.innerHTML = pill(extractFailureText(roleMsg, "Failed"), "danger");
  }

  const checkCfg = getAnnualDownloadConfig(session.return, "json");
  const msgFile = await processAsync({
    request: "get",
    url: gstn.generateFile(checkCfg, period, false),
  });

  if (!msgFile.status) {
    infoCell.innerHTML = pill(extractFailureText(msgFile, "Failed"), "danger");
    btnJson.hidden = true;
    btnExcel.hidden = true;
  } else {
    const resp = JSON.parse(msgFile.response);
    const fileGenStatus = getFileGenStatus(resp);

    if (fileGenStatus) {
      infoCell.innerHTML = pill(
        fileGenStatus,
        fileGenStatus.toLowerCase().includes("generating") ? "warning" : "danger",
      );
      btnJson.hidden = true;
      btnExcel.hidden = true;
    } else {
      showGenTime(infoCell, resp.data.date, resp.data.time);
      btnJson.hidden = false;
      btnExcel.hidden = false;
      btnJson.onclick = function (evt) {
        reportButtonClicked(evt);
        downloadAnnualFile(fy, "json");
      };
      btnExcel.onclick = function (evt) {
        reportButtonClicked(evt);
        downloadAnnualFile(fy, "excel");
      };
    }
  }

  btnGenerate.onclick = function (evt) {
    reportButtonClicked(evt);
    generateAnnualFile(fy);
  };
}

async function generateAnnualFile(fy) {
  const btnGenerate = getElement(`btn-annual-generate-${fy}`);
  const infoCell = getElement(`annual-info-${fy}`);
  const period = { value: annualPeriodValueFromFy(fy), year: makeFinancialYearLabel(fy) };

  btnGenerate.disabled = true;
  btnGenerate.textContent = "Requesting...";

  const jsonCfg = getAnnualDownloadConfig(session.return, "json");
  const excelCfg = getAnnualDownloadConfig(session.return, "excel");

  const msgGenJson = await processAsync({
    request: "get",
    url: gstn.generateFile(jsonCfg, period, true),
  });

  if (!msgGenJson.status) {
    btnGenerate.textContent = "Failed";
    btnGenerate.disabled = false;
    infoCell.innerHTML = pill(extractFailureText(msgGenJson, "Failed"), "danger");
    return;
  }

  const msgGenExcel = await processAsync({
    request: "get",
    url: gstn.generateFile(excelCfg, period, true),
  });

  if (!msgGenExcel.status) {
    btnGenerate.textContent = "Failed";
    btnGenerate.disabled = false;
    infoCell.innerHTML = pill(extractFailureText(msgGenExcel, "Failed"), "danger");
    return;
  }

  infoCell.innerHTML = pill("Generating JSON & Excel...", "warning");
  btnGenerate.textContent = "Requested";
}

async function downloadAnnualFile(fy, mode) {
  const btn = getElement(`btn-annual-${mode}-${fy}`);
  const infoCell = getElement(`annual-info-${fy}`);
  const period = { value: annualPeriodValueFromFy(fy), year: makeFinancialYearLabel(fy) };
  const cfg = getAnnualDownloadConfig(session.return, mode);

  btn.disabled = true;
  btn.textContent = mode === "excel" ? "Downloading Excel..." : "Downloading JSON...";
  infoCell.innerHTML = pill(mode === "excel" ? "Downloading Excel..." : "Downloading JSON...", "warning");

  const msgFile = await processAsync({
    request: "get",
    url: gstn.generateFile(cfg, period, false),
  });

  if (!msgFile.status) {
    btn.textContent = "Failed";
    btn.disabled = false;
    infoCell.innerHTML = pill(extractFailureText(msgFile, "Failed"), "danger");
    return;
  }

  const resp = JSON.parse(msgFile.response);
  const fileGenStatus = getFileGenStatus(resp);
  if (fileGenStatus) {
    btn.textContent = "Failed";
    btn.disabled = false;
    infoCell.innerHTML = pill(fileGenStatus, fileGenStatus.toLowerCase().includes("generating") ? "warning" : "danger");
    return;
  }

  const finalUrl = resp && resp.data && resp.data.url && resp.data.url[0] ? resp.data.url[0] : null;
  if (!finalUrl) {
    btn.textContent = "Failed";
    btn.disabled = false;
    infoCell.innerHTML = pill("No file url", "danger");
    return;
  }

  const fileName =
    makeZipFileName(
      cfg.fileNameCode,
      session.gstin || "GSTIN",
      period.value,
      mode === "excel" ? "EXL" : "",
    ) + ".zip";
  downloadAs(finalUrl, fileName);
  btn.textContent = "Done";
  infoCell.innerHTML = pill(mode === "excel" ? "Downloaded Excel" : "Downloaded JSON", "success");
}

async function generateAllAnnual() {
  const btnGenAll = getElement("btn-annual-generate-all");
  if (!btnGenAll) return;
  btnGenAll.disabled = true;
  btnGenAll.textContent = "Requesting...";

  const fyCells = Array.from(document.querySelectorAll("[id^='annual-info-']"));
  const years = fyCells
    .map((node) => parseInt(String(node.id).replace("annual-info-", ""), 10))
    .filter((value) => Number.isFinite(value))
    .sort((a, b) => b - a);

  for (const fy of years) {
    await generateAnnualFile(fy);
  }

  btnGenAll.textContent = "Done";
}

// ============================================================================
// NEO-GST EXTENDED FEATURES (new in this build)
//   1. Notices & Orders download (litserv API) -> Excel
//   2. Vendor Directory (local GSTIN/contact list + bulk status lookup) -> Excel
//   3. "Get All" — bulk multi-return export for one financial year -> single ZIP
//
// None of this touches any existing single-item download function's output
// format. The Excel-building code paths above (buildGstr1WorkbookXlsxBlob,
// buildGstr2bWorkbookXlsxBlob, buildGstr2aWorkbookXlsxBlob,
// buildGstr3bWorkbookXml, buildGenericLedgerWorkbookXml,
// buildItcLedgerWorkbookXml, buildChallanWorkbookXml, the summary builders,
// etc.) are reused exactly as-is; this section only adds new orchestration
// and one new export type (Notices) that did not exist before.
// ============================================================================

// ── Notices & Orders (new) ──────────────────────────────────────────
// Uses the GST portal's litigation service (litserv) API, the same one the
// portal's own "View Notices and Orders" screen calls. The 'at' session
// token requirement mirrors how the portal's litserv calls behave; if the
// portal changes this contract this is the function to revisit.
const NOTICES_CONFIG = { key: "NOTICES", display: "Notices & Orders", fileNameCode: "NOTICES" };

async function fetchSubdomainAtToken(origin) {
  let host;
  try {
    host = new URL(origin).hostname;
  } catch (e) {
    return null;
  }
  await ensureConnectedToHost(host);
  // gstr2b.gst.gov.in only hands back an `at` token from ustatus when
  // adhrflag=N is present — this is exactly what GST Jet's getSessionStatus()
  // does for the 2B subdomain.
  const ustatusUrl =
    host.toLowerCase() === "gstr2b.gst.gov.in"
      ? `${origin}/services/api/ustatus?adhrflag=N`
      : `${origin}/services/api/ustatus`;
  let msg = await bgFetch(ustatusUrl, {
    method: "GET",
    headers: { Accept: "application/json, text/plain, */*" },
  });
  if (!msg || !msg.status || !msg.responseHeaders) {
    // Fall back to the tab port (older path) if the background fetch could not
    // read the response headers that carry the `at` token.
    const viaPort = await processAsync({
      request: "request",
      method: "GET",
      url: ustatusUrl,
      headers: { Accept: "application/json, text/plain, */*" },
    });
    if (viaPort && viaPort.status) msg = viaPort;
  }
  if (!msg || !msg.status) return null;
  const headerToken =
    msg.responseHeaders && (msg.responseHeaders.at || msg.responseHeaders.AT || msg.responseHeaders.At);
  let parsedBody = null;
  try {
    parsedBody = JSON.parse(msg.response);
  } catch (e) {
    parsedBody = null;
  }
  // The GST portal's ustatus response carries the logged-in GSTIN directly
  // in the JSON body (parsedBody.gstin) — this is what GST Jet's own
  // getSessionStatus() reads. It's available on every subdomain's ustatus
  // (services, return, payment, gstr2b) and doesn't depend on the current
  // tab's visible page text, so it's a far more reliable source than the
  // getGstin DOM-scrape fallback, which only works if the tab happens to be
  // showing a page with the GSTIN printed on it.
  const bodyGstin = normalizeGstin(parsedBody && parsedBody.gstin);
  if (bodyGstin && !session.gstin) {
    session.gstin = bodyGstin;
  }
  if (headerToken) return headerToken;
  if (parsedBody) {
    if (parsedBody.at) return parsedBody.at;
    if (parsedBody.data && parsedBody.data.at) return parsedBody.data.at;
  }
  return null;
}

async function fetchNoticesRaw() {
  if (!session.gstin) {
    await resolveSessionGstin();
  }
  if (!session.gstin) throw new Error("Missing GSTIN");

  await ensureConnectedToHost("services.gst.gov.in");
  const at = await fetchSubdomainAtToken("https://services.gst.gov.in");
  const headers = { Accept: "application/json, text/plain, */*", "Content-Type": "application/json" };
  if (at) headers.at = at;

  const msg = await processAsync({
    request: "request",
    method: "POST",
    url: "https://services.gst.gov.in/litserv/auth/api/case/task/get",
    headers,
    body: JSON.stringify({ gstIn: session.gstin }),
  });
  if (!msg || !msg.status) {
    throw new Error(
      msg && msg.statusCode
        ? `Notices API failed (HTTP ${msg.statusCode})`
        : "Notices API failed — could not reach the GST portal's litigation service",
    );
  }
  let parsed = null;
  try {
    parsed = JSON.parse(msg.response);
  } catch (e) {
    parsed = null;
  }
  if (!parsed) throw new Error("Unexpected response from the notices API");
  const list =
    (Array.isArray(parsed) && parsed) ||
    (Array.isArray(parsed.data) && parsed.data) ||
    (parsed.data && Array.isArray(parsed.data.list) && parsed.data.list) ||
    (parsed.data && Array.isArray(parsed.data.taskList) && parsed.data.taskList) ||
    [];
  return { list, raw: parsed };
}

function noticesValue(row, ...keys) {
  for (const key of keys) {
    if (row && row[key] != null && row[key] !== "") return row[key];
  }
  return "";
}

function parseNoticesJson(value) {
  if (!value) return {};
  if (typeof value === "object") return value;
  try { return JSON.parse(value); } catch (e) { return {}; }
}

function noticesDate(value) {
  const text = String(value || "").trim();
  const match = text.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (match) return `${match[3]}-${formatNumber(match[2], 2)}-${formatNumber(match[1], 2)}`;
  const numeric = Number(value);
  if (Number.isFinite(numeric) && numeric > 100000000000) return moment(numeric).format("YYYY-MM-DD");
  const parsed = moment(text, ["YYYY-MM-DD", moment.ISO_8601], true);
  return parsed.isValid() ? parsed.format("YYYY-MM-DD") : "";
}

function noticesSafeName(value, fallback) {
  return String(value || fallback || "Document")
    .trim()
    .replace(/[\\/:*?"<>|]/g, "_")
    .replace(/\s+/g, "_")
    .replace(/_+/g, "_")
    .replace(/^_|_$/g, "")
    .slice(0, 110) || String(fallback || "Document");
}

function noticeDocumentFileName(doc, index, blob) {
  const rawName = String((doc && doc.name) || `Document_${doc && doc.id ? doc.id : index + 1}`).trim();
  const suppliedExtension = (rawName.match(/\.([A-Za-z0-9]{1,8})$/) || [])[0] || "";
  let extension = suppliedExtension;
  const contentType = String((blob && blob.type) || (doc && doc.contentType) || "").toLowerCase();
  if (!extension) {
    if (contentType.includes("pdf")) extension = ".pdf";
    else if (contentType.includes("jpeg")) extension = ".jpg";
    else if (contentType.includes("png")) extension = ".png";
  }
  const withoutExtension = suppliedExtension ? rawName.slice(0, -suppliedExtension.length) : rawName;
  const safeBase = noticesSafeName(withoutExtension, `Document_${doc && doc.id ? doc.id : index + 1}`).slice(0, 100);
  return `${formatNumber(index + 1, 2)}_${safeBase}${extension.toLowerCase()}`;
}

async function noticesPost(path, body, headers) {
  const request = {
    method: "POST",
    url: `https://services.gst.gov.in/litserv/auth/api/${path}`,
    headers,
    body: JSON.stringify(body || {}),
  };
  const parseResponse = (msg) => {
    if (!msg || !msg.status || !msg.response || isHtmlBody(msg.response) || isPortalDeniedBody(msg.response)) return null;
    try { return JSON.parse(msg.response); } catch (e) { return null; }
  };
  let msg = await bgFetch(request.url, request);
  let parsed = parseResponse(msg);
  if (parsed == null) {
    await ensureConnectedToHost("services.gst.gov.in");
    msg = await processAsync({ request: "request", ...request });
    parsed = parseResponse(msg);
  }
  if (parsed == null) {
    throw new Error(msg && msg.statusCode ? `Notices API failed (HTTP ${msg.statusCode})` : "Notices API request failed");
  }
  return parsed;
}

function noticesResponseArray(value) {
  let current = value;
  for (let depth = 0; depth < 5; depth += 1) {
    if (Array.isArray(current)) return current;
    if (typeof current === "string") {
      try { current = JSON.parse(current); continue; } catch (e) { return []; }
    }
    if (!current || typeof current !== "object") return [];
    const next = current.data ?? current.list ?? current.items ?? current.folders ?? current.caseFolderList ?? current.result ?? current.response;
    if (next === undefined || next === current) return [];
    current = next;
  }
  return Array.isArray(current) ? current : [];
}

async function openOneNoticeCaseContext(caseData, headers) {
  if (!caseData) return false;
  const searchResult = await noticesPost("case/search", {
    caseId: caseData.caseId,
    arn: caseData.arn,
    caseTypeCd: caseData.caseTypeCd,
  }, headers);
  const matches = noticesResponseArray(searchResult);
  if (!matches.length) throw new Error("GST Portal did not return the selected case details");
  const arnData = matches[0];
  const code = String(caseData.caseTypeCd || "").toUpperCase();
  if (["ADJSR", "ADJAS", "ADJAJ"].includes(code) && arnData.appItem && arnData.appItem.itemJson) {
    arnData.caseJson = parseNoticesJson(arnData.appItem.itemJson);
  } else if (arnData.appItem && !["APPEL_APLCN_MUAPL", "APLTD_APLCN_MUAPL"].includes(arnData.appItem.caseCfItemMapId)) {
    delete arnData.caseJson;
  }
  if (arnData.appItem && !["APPEL_APLCN_MUAPL", "APLTD_APLCN_MUAPL"].includes(arnData.appItem.caseCfItemMapId)) {
    delete arnData.appItem.itemJson;
  }
  const tab = await findTabForHost("services.gst.gov.in");
  if (!tab || typeof tab.id !== "number") throw new Error("GST Portal tab was not found");
  addActivity(`Opening case ${caseData.arn || caseData.caseId} to initialize document access...`, "text-muted");
  await new Promise((resolve, reject) => {
    const timeout = setTimeout(() => {
      browser.tabs.onUpdated.removeListener(listener);
      reject(new Error("Opening the GST notice case timed out"));
    }, 20000);
    const listener = (tabId, changeInfo) => {
      if (tabId !== tab.id || changeInfo.status !== "complete") return;
      clearTimeout(timeout);
      browser.tabs.onUpdated.removeListener(listener);
      setTimeout(resolve, 2500);
    };
    browser.tabs.onUpdated.addListener(listener);
    browser.scripting.executeScript({
      target: { tabId: tab.id },
      func: (payload) => {
        const form = document.createElement("form");
        form.method = "POST";
        form.action = "/litserv/auth/case/folder";
        const field = document.createElement("input");
        field.type = "hidden";
        field.name = "arnData";
        field.value = JSON.stringify(payload);
        form.appendChild(field);
        document.body.appendChild(form);
        form.submit();
      },
      args: [arnData],
    }).catch((error) => {
      clearTimeout(timeout);
      browser.tabs.onUpdated.removeListener(listener);
      reject(error);
    });
  });
  const refreshed = await new Promise((resolve) => browser.tabs.get(tab.id, (value) => resolve(value || tab)));
  await connectToTab(refreshed);
  return true;
}

function noticesDetail(item) {
  const json = parseNoticesJson(item && item.itemJson);
  const sdtls = json.sdtls || {};
  const detail = json.reply || Object.values(sdtls).find((value) => value && typeof value === "object") || {};
  return { json, detail };
}

function collectNoticeDocuments(value) {
  const found = [];
  const seen = new Set();
  const walk = (node) => {
    if (!node || typeof node !== "object") return;
    const doc = node.dcupdtls && typeof node.dcupdtls === "object" ? node.dcupdtls : node;
    if (doc.id && (doc.docName || doc.name || doc.ct)) {
      const id = String(doc.id);
      if (!seen.has(id)) {
        seen.add(id);
        found.push({ id, name: doc.docName || doc.name || `Document_${id}`, contentType: doc.ct || "" });
      }
    }
    Object.values(node).forEach((child) => {
      if (child && typeof child === "object" && child !== node.dcupdtls) walk(child);
    });
  };
  walk(value);
  return found;
}

function classifyNoticeItem(folderCode, item) {
  const { json, detail } = noticesDetail(item);
  const folder = String(folderCode || "").toUpperCase();
  const type = String(detail.type || detail.replyty || json.act_cd || "").toUpperCase();
  if (folder === "REPLY") return "reply";
  if (folder === "ORDRS" || folder === "CLOSR" || /ORDER|CLOS/.test(type)) return "order";
  if (folder === "NOTCE" && (json.ntref || /REMINDER/.test(type))) return "reminder";
  if (folder === "NOTCE" || folder === "INTIM") return "notice";
  return "other";
}

function normalizeNoticeItem(folder, item) {
  const { json, detail } = noticesDetail(item);
  const kind = classifyNoticeItem(folder.caseFolderTypeCd, item);
  const ref = String(json.refid || detail.refId || item.refId || "");
  const parentRef = String(detail.ntcno || json.ntref || detail.scnrefno || "");
  const period = detail.tpovl || {};
  const taxPeriod = [period.fromm, period.fromy].filter(Boolean).join(" ") +
    ((period.tom || period.toy) ? ` to ${[period.tom, period.toy].filter(Boolean).join(" ")}` : "");
  const demandTotal = Number(detail.summ && detail.summ.total && detail.summ.total.tot);
  return {
    kind,
    folder: folder.caseFolderTypeCd,
    ref,
    parentRef,
    date: noticesDate(json.refdt || detail.replydt || (detail.decdtls && detail.decdtls.dt) || item.insertDate),
    dueDate: noticesDate(detail.duedt),
    type: detail.type || detail.replyty || json.act_cd || folder.caseFolderTypeName || kind,
    fy: detail.fy || detail.finYearFrom || "",
    taxPeriod,
    section: Array.isArray(detail.sec) ? detail.sec.join(", ") : detail.sec || "",
    demandTotal: Number.isFinite(demandTotal) ? demandTotal : 0,
    hearingDate: noticesDate(detail.phdt),
    hearingTime: detail.pht || "",
    hearingVenue: detail.venu || "",
    reason: detail.reason || detail.othrsn || "",
    officer: json.todtls || {},
    documents: collectNoticeDocuments(json),
    raw: json,
  };
}

function groupNoticeProceeding(items) {
  const sorted = items.filter((item) => item.kind !== "other").sort((a, b) => String(a.date).localeCompare(String(b.date)));
  const roots = sorted.filter((item) => item.kind === "notice");
  const groups = roots.map((notice) => ({ notice, reminders: [], replies: [], orders: [] }));
  const byRef = new Map(groups.filter((group) => group.notice.ref).map((group) => [group.notice.ref, group]));
  const selectGroup = (item) => byRef.get(item.parentRef) || groups.slice().reverse().find((group) => group.notice.date <= item.date) || groups[0];
  sorted.forEach((item) => {
    if (item.kind === "notice") return;
    let group = selectGroup(item);
    if (!group) {
      group = { notice: { kind: "notice", ref: item.parentRef || "", date: "", dueDate: "", type: "", documents: [], raw: {}, placeholder: true }, reminders: [], replies: [], orders: [] };
      groups.push(group);
      if (group.notice.ref) byRef.set(group.notice.ref, group);
    }
    if (item.kind === "reminder") group.reminders.push(item);
    else if (item.kind === "reply") group.replies.push(item);
    else group.orders.push(item);
  });
  return groups;
}

async function fetchNoticeCases() {
  const taskResult = await fetchNoticesRaw();
  const at = await fetchSubdomainAtToken("https://services.gst.gov.in");
  const headers = { Accept: "application/json, text/plain, */*", "Content-Type": "application/json" };
  if (at) headers.at = at;
  const cases = new Map();
  (taskResult.list || []).forEach((task) => {
    const caseId = noticesValue(task, "CaseId", "caseId");
    if (!caseId || cases.has(String(caseId))) return;
    cases.set(String(caseId), {
      caseId,
      arn: noticesValue(task, "Arn", "arn"),
      caseTypeCd: noticesValue(task, "caseTpeCd", "CaseTpeCd", "CaseTypeCd", "caseTypeCd"),
      caseTypeName: noticesValue(task, "CaseTypeName", "caseTypeName", "TaskDesc", "taskDesc"),
      status: noticesValue(task, "Status", "status"),
      task,
      items: [],
      errors: [],
    });
  });
  const contextCase = Array.from(cases.values()).find((caseData) => caseData.caseTypeCd && caseData.arn);
  await openOneNoticeCaseContext(contextCase, headers);
  for (const caseData of cases.values()) {
    try {
      const foldersRaw = await noticesPost("case/folder", { caseId: caseData.caseId, gstid: session.gstin, caseTypeCd: caseData.caseTypeCd }, headers);
      const folders = noticesResponseArray(foldersRaw);
      if (!folders.length) {
        const portalError = foldersRaw && foldersRaw.error && foldersRaw.error.message;
        caseData.errors.push(portalError || "The portal returned no folders for this case");
      }
      for (const folder of folders) {
        if (!folder || !folder.caseFolderId) continue;
        try {
          const itemsRaw = await noticesPost("case/folder/items", { caseFolderId: folder.caseFolderId }, headers);
          const folderItems = noticesResponseArray(itemsRaw);
          folderItems.forEach((item) => caseData.items.push(normalizeNoticeItem(folder, item)));
        } catch (error) {
          caseData.errors.push(`${folder.caseFolderTypeName || folder.caseFolderTypeCd}: ${error.message}`);
        }
      }
    } catch (error) {
      caseData.errors.push(error.message);
    }
    caseData.groups = groupNoticeProceeding(caseData.items);
  }
  return { taskResult, cases: Array.from(cases.values()), headers };
}

async function downloadNoticeDocuments(documents, arn, headers, targetZip, encryptedDocIds, bundleName) {
  const unique = Array.from(new Map((documents || []).map((doc) => [doc.id, doc])).values());
  if (!unique.length) return [];
  const encrypted = encryptedDocIds || {};
  const failures = [];
  for (let index = 0; index < unique.length; index += 1) {
    const doc = unique[index];
    const eh = encrypted && encrypted[doc.id];
    const baseUrl = `https://services.gst.gov.in/downloadhb/download/new?docId=${encodeURIComponent(doc.id)}&arn=${encodeURIComponent(arn || "")}`;
    const urls = eh ? [`${baseUrl}&eh=${encodeURIComponent(eh)}`, baseUrl] : [baseUrl];
    try {
      let blob = null;
      let lastError = null;
      for (const url of urls) {
        const msg = await processAsync({ request: "getBlobBase64", url, headers: { Accept: "application/pdf,application/octet-stream,*/*" } });
        if (msg && msg.status && msg.responseBase64) {
          const binary = atob(msg.responseBase64);
          const bytes = new Uint8Array(binary.length);
          for (let offset = 0; offset < binary.length; offset += 1) bytes[offset] = binary.charCodeAt(offset);
          blob = new Blob([bytes], { type: msg.contentType || doc.contentType || "application/octet-stream" });
          break;
        }
        lastError = new Error((msg && msg.error) || (msg && msg.statusCode ? `HTTP ${msg.statusCode}` : "Document download failed"));
      }
      if (!blob) throw lastError || new Error("Document download failed");
      const savedName = noticeDocumentFileName(doc, index, blob);
      targetZip.file(savedName, blob);
      (documents || []).filter((entry) => entry.id === doc.id).forEach((entry) => {
        entry.downloadStatus = "Downloaded";
        entry.savedName = savedName;
        entry.bundleName = bundleName || "";
        entry.downloadError = "";
      });
    } catch (error) {
      (documents || []).filter((entry) => entry.id === doc.id).forEach((entry) => {
        entry.downloadStatus = "Failed";
        entry.bundleName = bundleName || "";
        entry.downloadError = error.message;
      });
      failures.push(`${doc.name}: ${error.message}`);
    }
  }
  return failures;
}

function noticeCellZipName(kind, number, group, items) {
  const notice = group.notice || {};
  const label = kind === "notice" ? `Notice_${number}` : kind === "reply" ? `Reply_to_Notice_${number}` : `Order_to_Notice_${number}`;
  const refs = (items || []).map((item) => item.ref).filter(Boolean).join("-") || notice.ref || "No_Reference";
  const dates = (items || []).map((item) => item.date).filter(Boolean);
  const datePart = dates.length ? (kind === "reply" ? `Submitted_${dates[0]}` : `Issued_${dates[0]}`) : "Date_Unknown";
  const duePart = kind === "notice" && notice.dueDate ? `_Due_${notice.dueDate}` : "";
  return `${label}_${noticesSafeName(refs, "No_Reference")}_${datePart}${duePart}.zip`;
}

async function buildNoticeCellZip(kind, number, group, caseData, headers) {
  const items = kind === "notice" ? [group.notice].concat(group.reminders) : kind === "reply" ? group.replies : group.orders;
  if (kind === "notice" && group.notice && group.notice.placeholder && !group.reminders.length) return null;
  if (!items.length || (kind !== "notice" && !items.some((item) => item.ref || item.documents.length))) return null;
  const zip = new JSZip();
  const bundleName = noticeCellZipName(kind, number, group, items);
  const failures = await downloadNoticeDocuments(items.flatMap((item) => item.documents || []), caseData.arn, headers, zip, caseData.encryptedDocIds, bundleName);
  const metadata = {
    gstin: session.gstin || "", caseId: String(caseData.caseId || ""), arn: caseData.arn || "",
    caseType: caseData.caseTypeName || caseData.caseTypeCd || "", category: kind, noticeNumber: number,
    items: items.map((item) => ({ reference: item.ref, parentNoticeReference: item.parentRef, type: item.type, date: item.date, dueDate: item.dueDate, financialYear: item.fy, section: item.section, hearingDate: item.hearingDate, hearingTime: item.hearingTime, hearingVenue: item.hearingVenue, reason: item.reason, documents: item.documents.map((doc) => doc.name) })),
    downloadFailures: failures,
  };
  zip.file("Details.json", JSON.stringify(metadata, null, 2));
  if (failures.length) zip.file("Download errors.txt", failures.join("\r\n"));
  return { name: bundleName, blob: await zip.generateAsync({ type: "blob" }), failures };
}

function buildNoticesRegisterBlob(cases, maxGroups) {
  const headers = [
    "Sr No", "Case ID", "ARN", "GSTIN", "Case type", "Portal status", "F.Y.", "Section", "Tax period",
    "Last Reply Due Date", "Latest Hearing", "Notice References", "Notice Types", "Reminder Count",
    "Reply References", "Reply Dates", "Reply Count", "Order References", "Order Types", "Order Dates", "Order Count",
    "Officer", "Designation", "Jurisdiction", "Total Demand", "Document Count",
  ];
  for (let number = 1; number <= maxGroups; number += 1) headers.push(`Notice ${number}`, `Reply to Notice ${number}`, `Order to Notice ${number}`);
  headers.push("Download errors");
  const data = cases.map((caseData, rowIndex) => {
    const notices = caseData.groups.map((group) => group.notice).filter(Boolean);
    const reminders = caseData.groups.flatMap((group) => group.reminders || []);
    const replies = caseData.groups.flatMap((group) => group.replies || []);
    const orders = caseData.groups.flatMap((group) => group.orders || []);
    const allItems = caseData.items || [];
    const unique = (values) => Array.from(new Set(values.filter(Boolean))).join(", ");
    const latest = (values) => values.filter(Boolean).sort().slice(-1)[0] || "";
    const hearing = allItems.filter((item) => item.hearingDate).sort((a, b) => a.hearingDate.localeCompare(b.hearingDate)).slice(-1)[0];
    const officerItem = allItems.filter((item) => item.officer && (item.officer.nm || item.officer.dg)).sort((a, b) => String(a.date).localeCompare(String(b.date))).slice(-1)[0];
    const officer = officerItem ? officerItem.officer : {};
    const row = [
      rowIndex + 1, String(caseData.caseId || ""), caseData.arn || "", session.gstin || "",
      caseData.caseTypeName || caseData.caseTypeCd || "", caseData.status || "",
      unique(allItems.map((item) => item.fy)), unique(allItems.map((item) => item.section)), unique(allItems.map((item) => item.taxPeriod)),
      latest(notices.concat(reminders).map((item) => item.dueDate)),
      hearing ? `${hearing.hearingDate}${hearing.hearingTime ? ` ${hearing.hearingTime}` : ""}${hearing.hearingVenue ? `\n${hearing.hearingVenue}` : ""}` : "",
      unique(notices.map((item) => item.ref)), unique(notices.map((item) => item.type)), reminders.length,
      unique(replies.map((item) => item.ref)), unique(replies.map((item) => item.date)), replies.length,
      unique(orders.map((item) => item.ref)), unique(orders.map((item) => item.type)), unique(orders.map((item) => item.date)), orders.length,
      officer.nm || "", officer.dg || "", officer.jurscd || officer.pl || "",
      notices.reduce((sum, item) => sum + (Number(item.demandTotal) || 0), 0),
      allItems.reduce((sum, item) => sum + (item.documents || []).length, 0),
    ];
    for (let index = 0; index < maxGroups; index += 1) {
      const group = caseData.groups[index];
      row.push(group && group.noticeZip ? group.noticeZip : "", group && group.replyZip ? group.replyZip : "", group && group.orderZip ? group.orderZip : "");
    }
    row.push((caseData.errors || []).join(" | "));
    return row;
  });
  const title = [["Notices Register"], [`GSTIN: ${session.gstin || ""}    Generated: ${moment().format("YYYY-MM-DD HH:mm")}`], []];
  const ws = XLSX.utils.aoa_to_sheet(title.concat([headers], data));
  ws["!cols"] = headers.map((heading) => ({
    wch: heading === "Sr No" ? 8
      : ["Reminder Count", "Reply Count", "Order Count", "Document Count"].includes(heading) ? 12
        : ["F.Y.", "Section", "Portal status"].includes(heading) ? 14
          : /Date|Due/.test(heading) ? 16
            : ["Case ID", "ARN", "GSTIN", "Jurisdiction", "Total Demand"].includes(heading) ? 18
              : /^Notice \d|^Reply to Notice|^Order to Notice/.test(heading) ? 38 : 28,
  }));
  ws["!rows"] = [{ hpt: 24 }, { hpt: 18 }, { hpt: 8 }, { hpt: 34 }].concat(data.map(() => ({ hpt: 45 })));
  ws["!autofilter"] = { ref: `A4:${excelColumnName(headers.length - 1)}${data.length + 4}` };
  ws["!freeze"] = { xSplit: 6, ySplit: 4, topLeftCell: "G5", activePane: "bottomRight", state: "frozen" };
  for (let column = 0; column < headers.length; column += 1) {
    const cell = ws[`${excelColumnName(column)}4`];
    if (cell) cell.s = { fill: { fgColor: { rgb: "1F4E78" } }, font: { bold: true, color: { rgb: "FFFFFF" } }, alignment: { horizontal: "center", vertical: "center", wrapText: true } };
  }
  for (let row = 0; row < data.length; row += 1) {
    for (let column = 0; column < headers.length; column += 1) {
      const address = `${excelColumnName(column)}${row + 5}`;
      if (!ws[address]) continue;
      ws[address].s = { alignment: { vertical: "top", wrapText: true } };
      if (/\.zip$/i.test(String(ws[address].v || ""))) ws[address].l = { Target: String(ws[address].v).replace(/\\/g, "/") };
    }
  }
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, "Notices Register");
  const auditHeaders = ["Sr No", "Case ID", "ARN", "Category", "Reference", "Parent Notice", "Type", "F.Y.", "Section", "Date", "Due Date", "Document Name", "Document ID", "Cell ZIP", "Saved Filename", "Download Status", "Error"];
  const auditRows = [];
  cases.forEach((caseData) => {
    (caseData.items || []).filter((item) => item.kind !== "other").forEach((item) => {
      const documents = item.documents && item.documents.length ? item.documents : [null];
      documents.forEach((doc) => auditRows.push([
        auditRows.length + 1, String(caseData.caseId || ""), caseData.arn || "", item.kind,
        item.ref || "", item.parentRef || "", item.type || "", item.fy || "", item.section || "", item.date || "", item.dueDate || "",
        doc ? doc.name : "", doc ? doc.id : "", doc ? doc.bundleName || "" : "", doc ? doc.savedName || "" : "",
        doc ? doc.downloadStatus || "Not attempted" : "No document listed", doc ? doc.downloadError || "" : "",
      ]));
    });
  });
  const auditSheet = XLSX.utils.aoa_to_sheet([auditHeaders].concat(auditRows));
  auditSheet["!cols"] = auditHeaders.map((heading) => ({ wch: ["Type", "Document Name", "Cell ZIP", "Error"].includes(heading) ? 34 : /Date/.test(heading) ? 14 : 18 }));
  auditSheet["!autofilter"] = { ref: `A1:${excelColumnName(auditHeaders.length - 1)}${auditRows.length + 1}` };
  auditSheet["!freeze"] = { xSplit: 3, ySplit: 1, topLeftCell: "D2", activePane: "bottomRight", state: "frozen" };
  for (let column = 0; column < auditHeaders.length; column += 1) {
    const cell = auditSheet[`${excelColumnName(column)}1`];
    if (cell) cell.s = { fill: { fgColor: { rgb: "1F4E78" } }, font: { bold: true, color: { rgb: "FFFFFF" } }, alignment: { horizontal: "center", vertical: "center", wrapText: true } };
  }
  for (let row = 0; row < auditRows.length; row += 1) {
    const statusCell = auditSheet[`P${row + 2}`];
    if (statusCell) statusCell.s = { font: { color: { rgb: statusCell.v === "Downloaded" ? "008000" : statusCell.v === "Failed" ? "C00000" : "7F6000" }, bold: true } };
  }
  XLSX.utils.book_append_sheet(wb, auditSheet, "Download Status");
  const out = XLSX.write(wb, { bookType: "xlsx", type: "array", compression: true, cellStyles: true });
  return new Blob([out], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" });
}

async function downloadNoticesExcel() {
  if (!(typeof JSZip !== "undefined" && JSZip)) throw new Error("JSZip is required for the Notices Register");
  await ensureNoticesPortalPage();
  const result = await fetchNoticeCases();
  const masterZip = new JSZip();
  let documentFailures = 0;
  let cellZipCount = 0;
  const maxGroups = Math.max(1, ...result.cases.map((caseData) => caseData.groups.length));
  for (const caseData of result.cases) {
    const caseFolder = `${noticesSafeName(caseData.caseId, "Case")}_${noticesSafeName(caseData.arn, "ARN")}`;
    const caseDocIds = Array.from(new Set(caseData.items.flatMap((item) => (item.documents || []).map((doc) => doc.id))));
    caseData.encryptedDocIds = {};
    if (caseDocIds.length) {
      try {
        caseData.encryptedDocIds = await noticesPost("usr/getEncrypDocIds", { arn: caseData.arn, docIdList: caseDocIds }, result.headers);
      } catch (error) {
        caseData.errors.push(`Document authorization: ${error.message}`);
      }
      await new Promise((resolve) => setTimeout(resolve, 150));
    }
    for (let index = 0; index < caseData.groups.length; index += 1) {
      const group = caseData.groups[index];
      for (const kind of ["notice", "reply", "order"]) {
        const cellZip = await buildNoticeCellZip(kind, index + 1, group, caseData, result.headers);
        if (!cellZip) continue;
        const path = `${caseFolder}/${cellZip.name}`;
        masterZip.file(path, cellZip.blob);
        group[`${kind}Zip`] = path;
        documentFailures += cellZip.failures.length;
        if (cellZip.failures.length) caseData.errors.push(`${cellZip.name}: ${cellZip.failures.length} document(s) not downloaded`);
        cellZipCount += 1;
      }
    }
  }
  const workbookName = `NOTICES_REGISTER_${session.gstin || "GSTIN"}_${moment().format("YYYYMMDD")}.xlsx`;
  masterZip.file(workbookName, buildNoticesRegisterBlob(result.cases, maxGroups));
  masterZip.file("README.txt", "Extract this master ZIP before opening the Excel file. Click a ZIP filename in the Notices Register to open the notice, reply or order bundle. Reminders are included with their parent notice.\r\n");
  const outputName = `NOTICES_REGISTER_${session.gstin || "GSTIN"}_${moment().format("YYYYMMDD")}.zip`;
  await downloadBlobAs(await masterZip.generateAsync({ type: "blob" }), outputName);
  return { cases: result.cases.length, cellZips: cellZipCount, documentFailures };
}

// ── Financial-year period helpers (new) ─────────────────────────────
function parseFyToken(fy) {
  const m = String(fy || "").match(/^(\d{4})/);
  const startYear = m ? parseInt(m[1], 10) : new Date().getFullYear();
  return { startYear, endYear: startYear + 1 };
}

function getFyMonthlyPeriods(fy) {
  const { startYear, endYear } = parseFyToken(fy);
  const months = [];
  for (let i = 0; i < 12; i++) {
    const year = i < 9 ? startYear : endYear; // Apr..Dec -> startYear, Jan..Mar -> endYear
    const monthNum = ((i + 3) % 12) + 1; // 4,5,...,12,1,2,3
    months.push({ value: `${formatNumber(monthNum, 2)}${year}`, isValid: true });
  }
  return months;
}

function getFyQuarterlyPeriods(fy) {
  const { startYear, endYear } = parseFyToken(fy);
  // Quarterly-return endpoints on the GST portal key off the quarter's
  // ending month (e.g. "062024" for the Apr-Jun 2024 quarter).
  return [
    { value: `06${startYear}`, isValid: true },
    { value: `09${startYear}`, isValid: true },
    { value: `12${startYear}`, isValid: true },
    { value: `03${endYear}`, isValid: true },
  ];
}

function getFyAnnualPeriod(fy) {
  const { endYear } = parseFyToken(fy);
  return { value: `03${endYear}`, isValid: true };
}

function getFyDateRangeForLedger(cfg, fy) {
  const { startYear, endYear } = parseFyToken(fy);
  // Get All is run mid-year all the time (e.g. FY 2026-27 pulled in July 2026).
  // The portal rejects any range whose `to` date is in the future, so clamp it.
  if (cfg && cfg.format === "MMYYYY") {
    const lastAllowed = moment().subtract(1, "month").startOf("month");
    let to = moment(`${endYear}-03`, "YYYY-MM", true).startOf("month");
    if (to.isAfter(lastAllowed, "month")) to = lastAllowed;
    return { from: `${startYear}-04`, to: to.format("YYYY-MM") };
  }
  const today = moment().startOf("day");
  let to = moment(`${endYear}-03-31`, "YYYY-MM-DD", true);
  if (to.isAfter(today, "day")) to = today;
  return { from: `${startYear}-04-01`, to: to.format("YYYY-MM-DD") };
}

function listAvailableFyOptions() {
  const years = [];
  const nowFyStart = new Date().getMonth() >= 3 ? new Date().getFullYear() : new Date().getFullYear() - 1;
  for (let y = nowFyStart; y >= 2017; y--) {
    years.push(`${y}-${String(y + 1).slice(-2)}`);
  }
  return years;
}

